window.PRACTICAL_DATA = [{"id":1,"title":"Đề thực hành số 1","source":"de co ban 1","timeLimitMinutes":60,"generalNotes":["Đề thi cấp chứng chỉ UDCNTT cơ bản, thời gian làm bài: 60 phút (đợt thi B200229019 theo tiêu đề đề).","Đề thi gồm 3 trang; không được sử dụng tài liệu, USB và các thiết bị lưu trữ khác.","Các file bài làm để trong thư mục D:\\ThiCC, cách đặt tên file: Câu 1: sbd_cau1.docx; Câu 2: sbd_cau2.xlsx; Câu 3: sbd_cau3.pptx. Trong đó sbd là số báo danh của thí sinh.","Trên giấy đề ghi 'ĐỀ THI THỰC HÀNH SỐ 02' dù thư mục là de co ban 1."],"tasks":[{"no":1,"app":"word","title":"Câu 1. Soạn thảo văn bản (Microsoft Word)","statement":{"intro":"Sử dụng phần mềm Microsoft Word soạn thảo nội dung tài liệu trên trang 3 với các yêu cầu sau:","requirements":["1) Soạn và định dạng đầy đủ nội dung văn bản như trang 3.","2) Định dạng trang: Cỡ giấy: A4; Chiều: Portrait; Lề trên (Top): 2.5 cm, Lề dưới (Bottom): 2 cm, Lề trái (Left): 3.5 cm, Lề phải (Right): 1.5 cm; Font: Times New Roman, cỡ 13pt.","3) Sử dụng Tab để thể hiện các thông tin các nội dung cần điền vào chỗ trống.","4) Sử dụng bảng cho thông tin hàng hóa với các đường viền theo đúng mẫu.","5) Sử dụng bảng không đường viền cho phần chữ ký của các bên tham gia."],"material":[{"kind":"text","caption":"Nội dung phần đầu phiếu (trang 3 của đề)","lines":["Đơn vị:................... Mẫu số XX - VT","Bộ phận:...............","PHIẾU XUẤT KHO","Ngày.....tháng.....năm ...... Nợ ........................","Số: .................................. Có ........................","- Họ và tên người nhận hàng: ................ Địa chỉ (bộ phận):.......................................","- Lý do xuất kho: ......................................................................","- Xuất tại kho (ngăn lô): .......................... Địa điểm: ..................................................."]},{"kind":"table","caption":"Bảng hàng hóa của phiếu (hàng 1 và 2 là tiêu đề; ô Số lượng gộp trên hai cột Yêu cầu và Thực xuất; các ô tiêu đề khác gộp dọc hai hàng)","rows":[["STT","Tên, nhãn hiệu, quy cách, phẩm chất vật tư, dụng cụ, sản phẩm, hàng hoá","Mã số","Đơn vị tính","Số lượng","","Đơn giá","Thành tiền"],["","","","","Yêu cầu","Thực xuất","",""],["A","B","C","D","1","2","3","4"],["","","","","","","",""],["","Cộng","x","x","x","x","x",""]]},{"kind":"text","caption":"Nội dung phần cuối phiếu","lines":["- Tổng số tiền (viết bằng chữ): ..................................................................","- Số chứng từ gốc kèm theo: ......................................................................","Ngày .... tháng .... năm...","Người nhận hàng (Ký, họ tên) | Thủ kho (Ký, họ tên) | Kế toán trưởng (Hoặc bộ phận có nhu cầu nhập) (Ký, họ tên) | Giám đốc (Ký, họ tên)"]}]},"solution":{"summary":"Đặt trang A4 Portrait với lề 2.5/2/3.5/1.5 cm và font Times New Roman 13 trước, rồi gõ các dòng thông tin dùng Tab có leader dấu chấm, vẽ bảng hàng hóa 8 cột có gộp ô và đường viền đầy đủ, cuối cùng làm bảng 4 cột không viền cho phần chữ ký. Nên làm đúng thứ tự này để mọi vị trí Tab và độ rộng bảng (16 cm) khớp nhau.","steps":[{"title":"Tạo file mới, đặt tên và thư mục lưu","forRequirement":"Chung","actions":["Mở Microsoft Word, chọn Blank document.","Bấm Ctrl+S ngay từ đầu, chọn thư mục D:\\ThiCC, đặt tên file là sbd_cau1.docx (sbd là số báo danh của bạn, ví dụ số báo danh 123 thì đặt 123_cau1.docx), Save as type: Word Document (*.docx).","Trong lúc làm bài nên bấm Ctrl+S thường xuyên để không mất dữ liệu."],"note":"Đặt sai tên hoặc lưu sai thư mục có thể bị tính sai. Nhớ tên file đúng theo đề.","shots":[{"file":"b1-1.png","caption":"Tài liệu trắng (Blank document) vừa mở. Tab File (khoanh đỏ) là nơi mở menu lưu file.","w":1920,"h":1020},{"file":"b1-2.png","caption":"File, Save As (khoanh đỏ), hoặc bấm Ctrl+S. Chọn thư mục D:\\ThiCC, đặt tên sbd_cau1.docx rồi bấm Save.","w":200,"h":600}]},{"title":"Định dạng trang trước khi gõ nội dung","forRequirement":"2) Định dạng trang, font","actions":["Tab Layout (bản cũ gọi là Page Layout) > nhóm Page Setup > bấm mũi tên nhỏ ở góc dưới phải nhóm (Page Setup dialog launcher) để mở hộp thoại Page Setup. Hoặc: Margins > Custom Margins...","Tab Margins: Top = 2.5 cm; Bottom = 2 cm; Left = 3.5 cm; Right = 1.5 cm. Mục Orientation chọn Portrait. Nếu Word đang hiện đơn vị inch thì cứ gõ \"2.5 cm\", Word sẽ tự đổi.","Chuyển sang tab Paper: Paper size chọn A4 (21 cm x 29.7 cm).","Mục Apply to chọn Whole document. Bấm OK.","Đặt font mặc định: tab Home > nhóm Styles > bấm phải vào Normal > Modify... > chọn Times New Roman, cỡ 13 > bấm Format > Paragraph > Spacing Before = 0 pt, After = 0 pt, Line spacing = Single > OK > OK. Làm vậy mọi đoạn (kể cả trong bảng) sẽ là Times New Roman 13 và phiếu vừa một trang A4.","Cách nhanh hơn nếu không muốn sửa style: bấm Ctrl+A rồi đặt Font = Times New Roman, Font Size = 13 ở tab Home. Nhưng cách này phải làm lại sau khi chèn bảng để chắc chắn bảng cũng đúng font."],"note":"Nên đặt lề và font trước khi gõ để vị trí Tab và độ rộng bảng khớp. Font Times New Roman 13 phải áp dụng cho toàn bộ văn bản, kể cả trong bảng.","shots":[{"file":"b2-1.png","caption":"Tab Layout (bản Office cũ gọi là Page Layout): bấm nút Margins (khoanh đỏ).","w":1920,"h":1020},{"file":"b2-2.png","caption":"Trong danh sách thả xuống, chọn Custom Margins... (khoanh đỏ) ở dưới cùng.","w":1920,"h":1020},{"file":"b2-3.png","caption":"Tab Margins của hộp thoại Page Setup: Top 2.5 cm, Bottom 2 cm, Left 3.5 cm, Right 1.5 cm và chọn Portrait (các ô khoanh đỏ).","w":1920,"h":1020},{"file":"b2-4.png","caption":"Chuyển sang tab Paper, mục Paper size chọn A4 (khoanh đỏ), khổ 21 x 29.7 cm. Apply to: Whole document rồi bấm OK.","w":1920,"h":1020},{"file":"b2-5.png","caption":"Tab Home, bấm phải vào kiểu Normal trong nhóm Styles, chọn Modify... (khoanh đỏ).","w":1920,"h":1020},{"file":"b2-6.png","caption":"Hộp thoại Modify Style: đặt Font Times New Roman, cỡ 13 (khoanh đỏ). Bấm nút Format (khoanh đỏ), chọn Paragraph... để đặt giãn đoạn.","w":1920,"h":1020},{"file":"b2-7.png","caption":"Hộp thoại Paragraph: Spacing Before 0 pt, After 0 pt, Line spacing Single (khoanh đỏ). Bấm OK để đóng các hộp thoại.","w":1920,"h":1020}]},{"title":"Hiện thước kẻ và cách đặt Tab có leader chấm","forRequirement":"3) Sử dụng Tab","actions":["Tab View > nhóm Show > tick Ruler để hiện thước kẻ phía trên trang.","Vùng chữ rộng 16 cm (21 - 3.5 - 1.5 = 16). Vạch 0 của thước là lề trái, vạch 16 là lề phải.","Cách đặt Tab stop cho một dòng: đặt con trỏ trong dòng đó, tab Home > nhóm Paragraph > bấm mũi tên góc dưới phải để mở hộp thoại Paragraph > bấm nút Tabs... ở dưới cùng. Trong hộp thoại Tabs: nhập vị trí vào Tab stop position (đơn vị cm), chọn Alignment (Left, Center hoặc Right), chọn Leader (1 None hoặc 2 .......) rồi bấm Set. Làm lần lượt từng vị trí, cuối cùng bấm OK.","Mỗi dòng có bộ Tab stop riêng. Khi bấm Enter xuống dòng mới, dòng mới thừa hưởng Tab stop của dòng trước; nếu không cần, vào Tabs... bấm Clear All rồi đặt lại cho dòng mới.","Khi gõ, nhấn phím Tab để nhảy tới Tab stop kế tiếp. Chỗ trống có leader chấm sẽ tự được lấp đầy bằng dấu chấm."],"note":"Không dùng phím Space để cách chữ và không gõ dấu chấm bằng tay. Dãy chấm phải do Tab leader tạo ra. Đây là yêu cầu 3.","shots":[{"file":"b3-1.png","caption":"Tab View, tick ô Ruler (khoanh đỏ) để hiện thước kẻ phía trên trang.","w":1920,"h":1020},{"file":"b3-2.png","caption":"Tab Home, bấm mũi tên nhỏ ở góc nhóm Paragraph để mở hộp thoại Paragraph, rồi bấm nút Tabs... (khoanh đỏ).","w":1920,"h":1020},{"file":"b3-3.png","caption":"Hộp thoại Tabs: nhập vị trí vào Tab stop position, chọn Alignment (Left), chọn Leader 2 (dãy chấm), rồi bấm Set (các mục khoanh đỏ).","w":1920,"h":1020}]},{"title":"Gõ phần đầu phiếu: Đơn vị, Bộ phận, Mẫu số","forRequirement":"1) Soạn nội dung; 3) Tab","actions":["Dòng 1: đặt hai Tab stop: 6.5 cm (Left, Leader 2 dots) và 9.5 cm (Left, Leader None). Gõ: Đơn vị: (bấm Ctrl+B để in đậm) > nhấn Tab > nhấn Tab > gõ Mẫu số XX - VT (in đậm). Kết quả: sau \"Đơn vị:\" có dãy chấm dài, bên phải là \"Mẫu số XX - VT\". Trong mẫu có dấu gạch giữa XX và VT, hãy gõ dấu gạch nối thường.","Dòng 2: đặt Tab stop 6.5 cm (Left, Leader 2 dots). Gõ: Bộ phận: (in đậm) > nhấn Tab để có dãy chấm sau chữ \"Bộ phận:\".","Nhấn Enter để chừa một dòng trống trước tiêu đề."],"note":"","shots":[{"file":"b4-1.png","caption":"Hai dòng đầu in đậm (nút B khoanh đỏ). Dãy chấm do phím Tab tạo ra, không gõ dấu chấm bằng tay.","w":1920,"h":1020}]},{"title":"Gõ tiêu đề PHIẾU XUẤT KHO và các dòng Ngày, Số, Nợ, Có","forRequirement":"1) Soạn nội dung; 3) Tab","actions":["Dòng tiêu đề: gõ PHIẾU XUẤT KHO, chọn dòng này, bấm Ctrl+E (căn giữa) và Ctrl+B (in đậm). Giữ cỡ 13 theo đề (có thể tăng nhẹ lên 14 nếu muốn nhưng không bắt buộc).","Dòng Ngày/Nợ: đặt các Tab stop: 3 cm Left (None), 5 cm Left (2 dots), 7.5 cm Left (2 dots), 10 cm Left (2 dots), 11 cm Left (None), 16 cm Right (2 dots). Gõ theo thứ tự: Tab, Ngày (in nghiêng Ctrl+I), Tab, tháng, Tab, năm, Tab, Tab, Nợ, Tab. Kết quả: \"Ngày......tháng......năm......\" rồi \"Nợ.........\".","Dòng Số/Có: đặt Tab stop: 3 cm Left (None), 10 cm Left (2 dots), 11 cm Left (None), 16 cm Right (2 dots). Gõ: Tab, Số:, Tab, Tab, Có, Tab.","Đặt chữ Nợ và Có cùng mốc 11 cm để chúng thẳng hàng như mẫu."],"note":"Các vị trí Tab chỉ là đề xuất để vừa khung 16 cm. Miễn các dòng gọn, thẳng cột và có dãy chấm ở chỗ trống là đạt.","shots":[{"file":"b5-1.png","caption":"Tiêu đề PHIẾU XUẤT KHO căn giữa (nút Center) và in đậm (nút B). Các dòng Ngày, Số, Nợ, Có dùng Tab có leader chấm (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Gõ các dòng thông tin người nhận, lý do, kho","forRequirement":"1) Soạn nội dung; 3) Tab","actions":["Dòng họ tên: đặt Tab stop 8 cm Left (2 dots) và 16 cm Right (2 dots). Gõ: - Họ và tên người nhận hàng: > Tab > Địa chỉ (bộ phận): > Tab.","Dòng lý do: đặt Tab stop 16 cm Right (2 dots). Gõ: - Lý do xuất kho: > Tab.","Dòng kho: đặt Tab stop 7.5 cm Left (2 dots) và 16 cm Right (2 dots). Gõ: - Xuất tại kho (ngăn lô): > Tab > Địa điểm: > Tab.","Nếu đoạn chữ trước Tab dài hơn mốc Tab thì Tab sẽ nhảy sang mốc kế tiếp. Khi đó tăng mốc lên (ví dụ 8.5 cm)."],"note":"Các dòng bắt đầu bằng dấu gạch nối \"- \" như mẫu.","shots":[{"file":"b6-1.png","caption":"Ba dòng thông tin bắt đầu bằng dấu gạch nối, mỗi dòng có Tab stop riêng nên dãy chấm chạy đến lề phải (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Chèn bảng hàng hóa 8 cột, gộp ô, kẻ viền","forRequirement":"4) Bảng hàng hóa với đường viền theo đúng mẫu","actions":["Đặt con trỏ sau dòng \"Xuất tại kho\", bấm Enter chừa một dòng, rồi tab Insert > nhóm Tables > Table > Insert Table... Nhập Number of columns = 8, Number of rows = 5. Chọn Fixed column width = Auto, bấm OK.","Chọn cả bảng (bấm biểu tượng 4 mũi tên ở góc trên trái bảng) > tab Table Layout > nhóm Cell Size > AutoFit > Fixed Column Width.","Đặt độ rộng cột: chọn từng cột > Table Layout > nhóm Cell Size > Width: cột 1 STT 1.2 cm; cột 2 Tên, nhãn hiệu... 4.1 cm; cột 3 Mã số 1.4 cm; cột 4 Đơn vị tính 1.4 cm; cột 5 Yêu cầu 1.8 cm; cột 6 Thực xuất 1.8 cm; cột 7 Đơn giá 2 cm; cột 8 Thành tiền 2.3 cm. Tổng đúng 16 cm khít bề rộng trang.","Gộp ô (Merge): chọn các ô cần gộp rồi tab Table Layout > nhóm Merge > Merge Cells. Gộp dọc ô hàng 1 và hàng 2 cho các cột: STT, Tên..., Mã số, Đơn vị tính, Đơn giá, Thành tiền. Gộp ngang hai ô hàng 1 của cột 5 và cột 6 để tạo ô \"Số lượng\".","Nhập nội dung hàng 1: STT | Tên, nhãn hiệu, quy cách, phẩm chất vật tư, dụng cụ, sản phẩm, hàng hoá | Mã số | Đơn vị tính | Số lượng | Đơn giá | Thành tiền. Hàng 2 chỉ còn hai ô: Yêu cầu | Thực xuất.","Hàng 3: A | B | C | D | 1 | 2 | 3 | 4. Hàng 4: để trống và tăng chiều cao (Table Layout > Cell Size > Height khoảng 3.5 cm; nếu không có ô Height hãy kéo đường viền dưới của hàng). Hàng 5: ô STT để trống, ô thứ 2 gõ Cộng (in nghiêng Ctrl+I), gõ chữ x vào các ô Mã số, Đơn vị tính, Yêu cầu, Thực xuất, Đơn giá; ô Thành tiền để trống.","Chọn cả bảng > tab Table Layout > nhóm Alignment > Align Center (căn giữa cả dọc và ngang) cho các ô tiêu đề và hàng A B C D 1 2 3 4. Ô \"Cộng\" có thể để Align Center Left.","Đường viền: chọn cả bảng > tab Table Design > nhóm Borders > Borders > All Borders (nếu bảng đã có viền sẵn thì All Borders sẽ tắt viền, bấm thêm một lần nữa; hoặc Borders and Shading... chọn Setting All, Style đường đơn, Width 1/2 pt). Kiểm tra ô \"Số lượng\" có đường kẻ ngăn đôi Yêu cầu | Thực xuất ngay phía dưới."],"note":"Bảng phải có đầy đủ đường viền (khung ngoài và lưới bên trong) giống mẫu. Hàng đầu dùng Merge để tạo ô Số lượng nằm trên hai cột nhỏ. Nếu gộp nhầm, bấm Ctrl+Z rồi làm lại.","shots":[{"file":"b7-1.png","caption":"Tab Insert, bấm Table rồi chọn Insert Table... (khoanh đỏ).","w":1920,"h":1020},{"file":"b7-2.png","caption":"Nhập Number of columns 8, Number of rows 5, giữ Fixed column width: Auto (khoanh đỏ) rồi bấm OK.","w":1920,"h":1020},{"file":"b7-3.png","caption":"Tab Table Layout: đặt con trỏ vào cột cần chỉnh, nhập độ rộng vào ô Width (khoanh đỏ). Ảnh minh họa cột 2 rộng 4.1 cm. AutoFit nên để Fixed Column Width.","w":1920,"h":1020},{"file":"b7-4.png","caption":"Gộp ô dọc: bôi chọn hai ô hàng 1 và hàng 2 của cột STT rồi bấm Merge Cells (khoanh đỏ). Làm tương tự cho Tên..., Mã số, Đơn vị tính, Đơn giá, Thành tiền.","w":1920,"h":1020},{"file":"b7-5.png","caption":"Gộp ô ngang: bôi chọn hai ô hàng 1 của cột Yêu cầu và Thực xuất, bấm Merge Cells (khoanh đỏ) để tạo ô Số lượng.","w":1920,"h":1020},{"file":"b7-6.png","caption":"Nhập nội dung, bôi chọn cả bảng, tab Table Layout, bấm Align Center (khoanh đỏ) để căn giữa chữ trong ô.","w":1920,"h":1020},{"file":"b7-7.png","caption":"Bôi chọn cả bảng, tab Table Design, bấm Borders (khoanh đỏ) rồi chọn All Borders (khoanh đỏ). Nếu bảng đã có viền sẵn, bấm All Borders sẽ tắt viền, hãy bấm thêm một lần nữa.","w":1920,"h":1020},{"file":"b7-8.png","caption":"Bảng hàng hóa hoàn chỉnh: đủ đường viền, ô Số lượng gộp trên hai ô Yêu cầu và Thực xuất, hàng trống cao, hàng Cộng có chữ x.","w":1920,"h":1020}]},{"title":"Gõ các dòng cuối phiếu: Tổng số tiền, chứng từ gốc","forRequirement":"1) Soạn nội dung; 3) Tab","actions":["Bấm chuột vào đoạn văn trống ngay dưới bảng. Nếu bảng nằm cuối văn bản, Word luôn giữ một đoạn trống sau bảng; chỉ cần bấm vào đó hoặc nhấn Ctrl+End.","Dòng 1: đặt Tab stop 16 cm Right (2 dots). Gõ: - Tổng số tiền (viết bằng chữ): > Tab.","Dòng 2: đặt Tab stop 16 cm Right (2 dots). Gõ: - Số chứng từ gốc kèm theo: > Tab."],"note":"","shots":[{"file":"b8-1.png","caption":"Hai dòng cuối phiếu: Tổng số tiền và Số chứng từ gốc, dùng Tab leader chấm đến lề phải (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Dòng Ngày tháng năm và bảng chữ ký không đường viền","forRequirement":"5) Bảng không đường viền cho phần chữ ký","actions":["Dòng ngày tháng: đặt Tab stop 10 cm Center (None). Gõ: Tab, Ngày ....tháng ....năm.... rồi chọn và bấm Ctrl+I (in nghiêng). Chữ sẽ nằm giữa cột thứ 3.","Insert > Table > Insert Table...: Columns = 4, Rows = 1. Chọn cả bảng > Table Layout > AutoFit > Fixed Column Width, rồi đặt Width = 4 cm cho mỗi cột (tổng 16 cm).","Cột 1: gõ Người nhận hàng (in đậm Ctrl+B), nhấn Enter, gõ (Ký, họ tên) in nghiêng. Cột 2: Thủ kho, Enter, (Ký, họ tên). Cột 3: Kế toán trưởng, Enter, (Hoặc bộ phận có nhu cầu nhập), Enter, (Ký, họ tên). Cột 4: Giám đốc, Enter, (Ký, họ tên). Phần chữ trong ngoặc in nghiêng, chức danh in đậm.","Chọn cả bảng chữ ký > Table Layout > nhóm Alignment > Align Top Center để căn giữa ngang.","Bỏ đường viền: chọn cả bảng > tab Table Design > Borders > No Border. Nếu còn thấy ô màu xám mờ, đó là View Gridlines (không in ra), không phải đường viền.","Bấm File > Print để xem toàn bộ nằm gọn một trang rồi Ctrl+S để lưu."],"note":"Bảng chữ ký BẮT BUỘC là bảng KHÔNG đường viền (yêu cầu 5). Nếu chỉ dùng phím Space hoặc Tab để dàn chữ ký mà không dùng bảng thì sẽ mất điểm yêu cầu 5.","shots":[{"file":"b9-1.png","caption":"Dòng Ngày tháng năm in nghiêng, đặt bằng một Tab căn giữa tại 10 cm (vùng khoanh đỏ).","w":1920,"h":1020},{"file":"b9-2.png","caption":"Tab Insert, Table, Insert Table...: Number of columns 4, Number of rows 1 (khoanh đỏ), bấm OK.","w":1920,"h":1020},{"file":"b9-3.png","caption":"Đặt độ rộng mỗi cột 4 cm trong ô Width (khoanh đỏ), tổng đúng 16 cm.","w":1920,"h":1020},{"file":"b9-4.png","caption":"Nhập chức danh in đậm và (Ký, họ tên) in nghiêng. Chọn cả bảng, bấm Align Top Center (khoanh đỏ).","w":1920,"h":1020},{"file":"b9-5.png","caption":"Chọn cả bảng, tab Table Design, bấm Borders rồi chọn No Border (khoanh đỏ) để bỏ đường viền.","w":1920,"h":1020},{"file":"b9-6.png","caption":"Toàn bộ phiếu nằm gọn một trang (Page 1 of 1 ở góc dưới trái, khoanh đỏ). Các nét đứt mờ là View Gridlines, không in ra.","w":1920,"h":1020}]}],"formulas":[],"result":"Một trang A4 dọc duy nhất giống trang 3 của đề: đầu phiếu có Đơn vị/Bộ phận và Mẫu số XX - VT; tiêu đề PHIẾU XUẤT KHO in đậm căn giữa; các dòng Ngày, Số, Nợ, Có, họ tên, lý do, kho đều có dãy chấm dẫn bằng Tab; bảng hàng hóa 8 cột có đầy đủ đường viền (ô Số lượng gộp trên Yêu cầu và Thực xuất, hàng A B C D 1 2 3 4, hàng trống cao, hàng Cộng có chữ x); cuối phiếu có hai dòng tổng số tiền và số chứng từ, dòng Ngày tháng năm in nghiêng và bảng 4 chữ ký không viền. Tự kiểm tra: File > Print xem toàn bộ nằm trọn một trang; mở lại Page Setup xem 2.5/2/3.5/1.5 cm; Ctrl+A xem ô Font hiện Times New Roman và cỡ 13 (không bị trống); xem Print Preview thấy bảng chữ ký không có đường kẻ."},"checklist":["Khổ giấy A4, hướng Portrait","Lề Top 2.5 cm, Bottom 2 cm, Left 3.5 cm, Right 1.5 cm","Toàn bộ văn bản (kể cả trong bảng) là Times New Roman 13pt","Đủ nội dung như trang 3: đầu phiếu, tiêu đề, các dòng thông tin, bảng, tổng tiền, chứng từ, ngày tháng, chữ ký","Các chỗ trống điền thông tin dùng Tab với leader chấm, không gõ dấu chấm bằng tay, không dùng phím Space","Bảng hàng hóa 8 cột có gộp ô Số lượng, hàng A B C D 1 2 3 4, hàng Cộng có chữ x, có đường viền đầy đủ","Bảng chữ ký 4 cột, đã chọn No Border","Toàn bộ phiếu nằm trong 1 trang","Đã lưu đúng tên sbd_cau1.docx trong D:\\ThiCC"],"commonMistakes":["Quên đặt lề hoặc đặt nhầm: lề trái 3.5 cm bị đặt thành 2.5 cm, lề dưới 2 cm bị đặt thành 2.5 cm.","Chỉ đổi font cho đoạn gõ mà quên font trong bảng, nên một phần vẫn là Calibri hoặc cỡ 11.","Dùng phím Space hoặc gõ dấu chấm tay để tạo chỗ trống thay vì Tab leader, làm sai yêu cầu 3.","Bảng chữ ký còn đường viền (quên chọn No Border).","Không gộp ô (Merge Cells) nên phần tiêu đề Số lượng - Yêu cầu - Thực xuất sai cấu trúc.","Độ rộng bảng vượt quá 16 cm làm bảng tràn khỏi lề phải.","Để khoảng cách đoạn (Spacing After) mặc định 8pt làm phiếu tràn sang trang 2.","Lưu sai tên hoặc sai thư mục, hoặc lưu định dạng .doc."],"uncertain":["Đề số trên giấy in ghi 'ĐỀ THI THỰC HÀNH SỐ 02' nhưng thư mục là de co ban 1; đã chép theo ảnh trong thư mục de co ban 1.","Trang 3 là ảnh chụp mờ nên các vị trí Tab (3, 5, 7.5, 10, 11, 16 cm) là đề xuất xấp xỉ theo hình dáng mẫu, không phải số liệu bắt buộc trong đề.","Trong mẫu, chữ 'Mẫu số XX - VT' có dấu gạch giữa XX và VT; đã viết bằng dấu gạch nối thông thường.","Bài mẫu 234_Câu 1.docx có lề trái 3.5 cm đúng đề; file 'de 1.docx' lại có lề trái 3.0 cm, đã làm theo đề (3.5 cm).","Chi tiết nghiêng/đậm (Ngày tháng năm, (Ký, họ tên), Cộng in nghiêng; Đơn vị, Bộ phận, tiêu đề in đậm) suy ra từ ảnh mờ và bài mẫu, đề không nêu rõ.","Độ rộng các cột bảng (1, 4.3, 1.4, 1.4, 1.8, 1.8, 2, 2.3 cm) là đề xuất tự tính để tổng đúng 16 cm, không có trong đề."]},{"no":2,"app":"excel","title":"Câu 2. Tạo bảng tính (Microsoft Excel)","statement":{"intro":"Bảng ước tính giá thành của một cửa hàng tạp hóa thể hiện như bảng sau (hai dòng đầu minh họa). Sử dụng phần mềm Microsoft Excel tạo bảng ước tính giá thành với các yêu cầu sau:","requirements":["1) Nhập dữ liệu (giả định) cho 10 mặt hàng trên các cột: TT (thứ tự), Mã hàng, Đơn giá nhập, Số lượng: Cột Mã hàng là chuỗi 04 ký tự: 01 ký tự đầu nhận một trong hai ký tự Y (là hàng dễ vỡ) hoặc N (là hàng không dễ vỡ), 03 ký tự còn lại là các ký tự số thể hiện mã số của mặt hàng. Số lượng là một số nguyên trong khoảng [1, 100]. Kẻ khung, căn chỉnh, định dạng các kiểu dữ liệu cho phù hợp; Font: Times New Roman, cỡ 13pt.","2) Định dạng trang: Khổ giấy A4, Landscape; Top: 2.5 cm, Bottom: 2.5 cm, Left: 2.5 cm, Right: 1.5 cm. Căn chỉnh bảng tính ra giữa trang in (Horizontally).","3) Nhập công thức tính Phí vận chuyển: Biết rằng, Phí vận chuyển bằng 5% của Đơn giá nhập x Số lượng. Giá trị của Phí vận chuyển được làm tròn đến hàng nghìn.","4) Nhập công thức tính Thành tiền và Hao phí: Biết rằng, Thành tiền = Đơn giá nhập x Số lượng + Phí vận chuyển; Hao phí bằng 1% thành tiền nếu là hàng không dễ vỡ và bằng 2% thành tiền nếu là hàng dễ vỡ.","5) Nhập công thức tính Đơn giá bán để có mức lãi là 10%; Biết rằng mức lãi được tính dựa trên thành tiền và hao phí. Giá trị của Đơn giá bán được làm tròn đến hàng nghìn."],"material":[{"kind":"table","caption":"Bảng mẫu trong đề (2 dòng đầu; các cột Phí vận chuyển, Thành tiền, Hao phí, Đơn giá bán để trống cho thí sinh tính)","rows":[["TT","Mã hàng","Đơn giá nhập","Số lượng","Phí vận chuyển","Thành tiền","Hao phí","Đơn giá bán"],["1","Y001","150.000","20","","","",""],["2","N002","70.000","35","","","",""]]},{"kind":"table","caption":"Dữ liệu gợi ý cho 10 mặt hàng (2 dòng đầu theo đề; 8 dòng sau là dữ liệu giả định lấy từ bài mẫu, thí sinh có thể nhập số khác miễn đúng điều kiện)","rows":[["TT","Mã hàng","Đơn giá nhập","Số lượng"],["1","Y001","150000","20"],["2","N002","70000","35"],["3","Y003","80000","35"],["4","Y004","90000","10"],["5","Y005","125000","13"],["6","N006","135000","15"],["7","N007","145000","45"],["8","N008","275000","16"],["9","N009","352000","17"],["10","N010","236000","21"]]}]},"solution":{"summary":"Nhập 10 dòng dữ liệu giả định theo đúng quy tắc mã hàng (Y/N + 3 số) và số lượng 1 đến 100, dùng bốn công thức ROUND/IF/LEFT cho các cột E, F, G, H (viết ở dòng 2 rồi fill xuống dòng 11), sau đó kẻ khung, đặt font Times New Roman 13, rồi thiết lập trang A4 ngang với lề 2.5/2.5/2.5/1.5 cm và căn giữa ngang trang in. Lưu ý dấu phân cách đối số: nếu máy báo lỗi với dấu chấm phẩy ; thì thay bằng dấu phẩy , (hoặc ngược lại), tùy thiết lập vùng Regional của Windows.","steps":[{"title":"Tạo file và đặt tên","forRequirement":"Chung","actions":["Mở Microsoft Excel > Blank workbook.","Ctrl+S > lưu vào D:\\ThiCC với tên sbd_cau2.xlsx (Save as type: Excel Workbook (*.xlsx))."],"note":"Đặt tên đúng theo số báo danh của bạn.","shots":[{"file":"b1-1.png","caption":"Mở Excel, chọn Blank workbook. Tab File (khoanh đỏ) mở menu lưu file.","w":1920,"h":1020},{"file":"b1-2.png","caption":"File, Save As (khoanh đỏ) hoặc Ctrl+S. Chọn thư mục D:\\ThiCC, đặt tên sbd_cau2.xlsx, kiểu Excel Workbook (*.xlsx).","w":200,"h":600}]},{"title":"Nhập tiêu đề cột và 10 dòng dữ liệu","forRequirement":"1) Nhập dữ liệu 10 mặt hàng","actions":["Ở các ô A1 đến H1 nhập lần lượt: TT | Mã hàng | Đơn giá nhập | Số lượng | Phí vận chuyển | Thành tiền | Hao phí | Đơn giá bán (di chuyển bằng phím Tab).","Nhập 10 dòng dữ liệu từ A2 đến D11. Cột TT đi từ 1 đến 10 (gõ 1, 2 rồi chọn hai ô và kéo Fill Handle xuống, hoặc gõ tay). Cột Mã hàng gồm 4 ký tự: ký tự đầu là Y (hàng dễ vỡ) hoặc N (hàng không dễ vỡ), 3 ký tự sau là số (ví dụ Y001, N002). Cột Đơn giá nhập là số (ví dụ 150000), cột Số lượng là số nguyên từ 1 đến 100.","Hai dòng đầu nên dùng đúng như đề: dòng 1 = Y001, 150000, 20; dòng 2 = N002, 70000, 35. Từ dòng 3 trở đi là dữ liệu giả định của bạn (có thể lấy bảng gợi ý ở phần đề).","Chưa nhập các cột E, F, G, H (sẽ dùng công thức ở các bước sau).","Gõ mã hàng bằng chữ HOA (Y hoặc N). Mã có 3 chữ số sau chữ cái nên không bị mất số 0 đầu (ví dụ Y001 vẫn giữ nguyên)."],"note":"Dữ liệu phải tuân thủ: Mã hàng đúng 4 ký tự (1 chữ Y hoặc N + 3 số); Số lượng là số nguyên trong [1, 100]. Nếu muốn, có thể vào Data > Data Validation đặt Whole number từ 1 đến 100 cho cột D, nhưng không bắt buộc.","shots":[{"file":"b2-1.png","caption":"Hàng 1 (khoanh đỏ) là tiêu đề 8 cột, ô A2 đến D11 (khoanh đỏ) là 10 dòng dữ liệu. Cột E đến H còn trống vì sẽ dùng công thức.","w":1920,"h":1020}]},{"title":"Công thức Phí vận chuyển (cột E)","forRequirement":"3) Phí vận chuyển","actions":["Click ô E2. Gõ: =ROUND(5%*C2*D2;-3) rồi Enter (nếu máy dùng dấu phẩy phân cách đối số thì gõ =ROUND(5%*C2*D2,-3)).","Giải thích: 5%*C2*D2 là 5% của Đơn giá nhập nhân Số lượng; ROUND(...;-3) làm tròn đến hàng nghìn (số -3 nghĩa là làm tròn đến 3 chữ số trước dấu thập phân).","Fill xuống: chọn E2, đưa chuột vào hình vuông nhỏ ở góc dưới phải ô (Fill Handle) cho đến khi con trỏ thành dấu +, nhấp đúp chuột trái (hoặc kéo xuống đến E11)."],"note":"Nếu báo lỗi, đổi dấu ; thành , (xem lưu ý dấu phân cách ở phần công thức). Phải gõ dấu trừ ngắn trước số 3.","shots":[{"file":"b3-1.png","caption":"Chọn ô E2 (Name Box ghi E2), gõ công thức vào thanh công thức rồi Enter. Ảnh chụp trên máy dùng dấu phẩy phân cách đối số nên hiện =ROUND(5%*C2*D2,-3).","w":1920,"h":1020},{"file":"b3-2.png","caption":"Fill xuống: đưa chuột vào Fill Handle ở góc dưới phải ô E2 rồi nhấp đúp (hoặc kéo xuống E11). Cột E đã có kết quả cho cả 10 dòng.","w":1920,"h":1020}]},{"title":"Công thức Thành tiền (cột F)","forRequirement":"4) Thành tiền","actions":["Click ô F2. Gõ: =C2*D2+E2 rồi Enter.","Giải thích: Thành tiền = Đơn giá nhập x Số lượng + Phí vận chuyển.","Fill xuống đến F11."],"note":"Dùng dấu cộng giữa tích và phí vận chuyển. Khối đầu của file mẫu đã dùng dấu trừ, lệch đề; hãy theo đề bài.","shots":[{"file":"b4-1.png","caption":"Ô F2 (Thành tiền): =C2*D2+E2, gõ vào thanh công thức rồi Enter.","w":1920,"h":1020},{"file":"b4-2.png","caption":"Fill xuống đến F11.","w":1920,"h":1020}]},{"title":"Công thức Hao phí (cột G)","forRequirement":"4) Hao phí","actions":["Click ô G2. Gõ: =IF(LEFT(B2;1)=\"N\";1%*F2;2%*F2) rồi Enter.","Giải thích: LEFT(B2;1) lấy ký tự đầu của Mã hàng. Nếu là N (hàng không dễ vỡ) thì Hao phí = 1% x Thành tiền; ngược lại (Y là hàng dễ vỡ) thì 2% x Thành tiền.","Fill xuống đến G11.","Cách viết tương đương: =IF(LEFT(B2;1)=\"Y\";2%*F2;1%*F2)."],"note":"Chữ N phải nằm trong dấu nháy kép. Đề không yêu cầu làm tròn Hao phí nên không dùng ROUND ở cột này.","shots":[{"file":"b5-1.png","caption":"Ô G2 (Hao phí): hàm IF và LEFT lấy ký tự đầu của Mã hàng để chọn 1% hay 2% Thành tiền.","w":1920,"h":1020},{"file":"b5-2.png","caption":"Fill xuống đến G11.","w":1920,"h":1020}]},{"title":"Công thức Đơn giá bán (cột H)","forRequirement":"5) Đơn giá bán","actions":["Click ô H2. Gõ: =ROUND((F2+G2)*110%;-3) rồi Enter.","Giải thích: lãi 10% tính trên (Thành tiền + Hao phí) nên giá bán = (F2+G2) x (100% + 10%) = (F2+G2) x 110%; ROUND(...;-3) làm tròn đến hàng nghìn.","Fill xuống đến H11. Có thể chọn E2:H2 rồi kéo Fill Handle xuống một lần cho cả 4 cột."],"note":"Cách viết tương đương: =ROUND((F2+G2)*(1+10%);-3).","shots":[{"file":"b6-1.png","caption":"Ô H2 (Đơn giá bán): =ROUND((F2+G2)*110%,-3), lãi 10% tính trên Thành tiền cộng Hao phí.","w":1920,"h":1020},{"file":"b6-2.png","caption":"Fill xuống đến H11. Bốn cột công thức E, F, G, H đã đầy đủ.","w":1920,"h":1020}]},{"title":"Kẻ khung, căn chỉnh, định dạng kiểu dữ liệu và font","forRequirement":"1) Kẻ khung, căn chỉnh, định dạng kiểu dữ liệu, Times New Roman 13","actions":["Bấm Ctrl+A (chọn toàn bộ bảng tính) > Home > nhóm Font > ô Font chọn Times New Roman, Font Size chọn 13.","Chọn A1:H11 > Home > nhóm Font > Borders > All Borders để kẻ khung toàn bảng.","Hàng tiêu đề A1:H1: Home > nhóm Alignment > Center và Middle Align; bật Wrap Text nếu chữ dài; bấm Ctrl+B in đậm.","Cột A (TT) và cột B (Mã hàng) căn giữa (Center); cột D (Số lượng) căn giữa hoặc căn phải.","Các cột tiền C, E, F, G, H: chọn C2:C11 và E2:H11 > Home > nhóm Number > bấm Comma Style (dấu phẩy) rồi bấm Decrease Decimal hai lần để bỏ số lẻ. Hoặc bấm phải > Format Cells > tab Number > Category: Number > Decimal places: 0 > tick Use 1000 Separator (,). Số sẽ hiện 150.000 theo kiểu Việt Nam.","Cột D (Số lượng) và cột A (TT) là số nguyên: Format Cells > Number > Decimal places = 0 (hoặc General).","Tự giãn cột: chọn các cột A:H > nhấp đúp vào ranh giới giữa hai tiêu đề cột (hoặc Home > Format > AutoFit Column Width)."],"note":"Nên bấm Ctrl+A để đặt font cho cả sheet, tránh sót ô ngoài vùng dữ liệu. Ảnh minh họa chụp trên máy dùng dấu phẩy ngăn cách nghìn nên hiện 150,000; máy cài định dạng Việt Nam sẽ hiện 150.000.","shots":[{"file":"b7-1.png","caption":"Bấm Ctrl+A để chọn cả bảng tính, tab Home, ô Font chọn Times New Roman, Font Size chọn 13 (khoanh đỏ).","w":1920,"h":1020},{"file":"b7-2.png","caption":"Chọn A1:H11, bấm mũi tên cạnh nút Borders (khoanh đỏ), chọn All Borders (khoanh đỏ) để kẻ khung toàn bảng.","w":1920,"h":1020},{"file":"b7-3.png","caption":"Chọn hàng tiêu đề A1:H1 rồi bấm Middle Align, Center, Wrap Text và in đậm B (các nút khoanh đỏ). Cột TT, Mã hàng, Số lượng cũng căn giữa.","w":1920,"h":1020},{"file":"b7-4.png","caption":"Chọn các cột tiền (C và E đến H), bấm Comma Style rồi Decrease Decimal (khoanh đỏ) để có dấu ngăn cách hàng nghìn và bỏ số lẻ.","w":1920,"h":1020},{"file":"b7-5.png","caption":"Chọn A1:H11, tab Home, Format (khoanh đỏ), AutoFit Column Width (khoanh đỏ) để tự giãn cột.","w":1920,"h":1020},{"file":"b7-6.png","caption":"Bảng sau khi định dạng: font Times New Roman 13, có khung, tiêu đề đậm căn giữa, số có dấu ngăn cách hàng nghìn.","w":1920,"h":1020}]},{"title":"Định dạng trang in: A4, Landscape, lề, căn giữa ngang","forRequirement":"2) Định dạng trang","actions":["Tab Page Layout > nhóm Page Setup > bấm mũi tên góc dưới phải để mở hộp thoại Page Setup.","Tab Page: Orientation chọn Landscape; Paper size chọn A4.","Tab Margins: Top = 2.5; Bottom = 2.5; Left = 2.5; Right = 1.5 (đơn vị cm). Trong cùng tab, tick Horizontally ở mục Center on page.","Bấm OK. Kiểm tra bằng File > Print (Ctrl+P): bảng phải nằm giữa theo chiều ngang và vừa 1 trang.","Nhấn Ctrl+S để lưu."],"note":"Chỉ tick Horizontally, không tick Vertically. Nếu Excel hiện inch thì gõ \"2.5 cm\" vào ô.","shots":[{"file":"b8-1.png","caption":"Tab Page Layout, bấm mũi tên nhỏ ở góc dưới phải nhóm Page Setup (khoanh đỏ) để mở hộp thoại Page Setup.","w":1920,"h":1020},{"file":"b8-2.png","caption":"Tab Page: Orientation chọn Landscape, Paper size chọn A4 (khoanh đỏ).","w":1920,"h":1020},{"file":"b8-3.png","caption":"Tab Margins: Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 (cm), tick Horizontally ở mục Center on page (khoanh đỏ), rồi bấm OK.","w":1920,"h":1020}]}],"formulas":[{"cell":"E2","formula":"=ROUND(5%*C2*D2;-3)","meaning":"Phí vận chuyển = 5% của (Đơn giá nhập x Số lượng), làm tròn đến hàng nghìn (số -3 nghĩa là làm tròn đến nghìn). Fill xuống E11."},{"cell":"F2","formula":"=C2*D2+E2","meaning":"Thành tiền = Đơn giá nhập x Số lượng + Phí vận chuyển. Fill xuống F11."},{"cell":"G2","formula":"=IF(LEFT(B2;1)=\"N\";1%*F2;2%*F2)","meaning":"Hao phí: nếu ký tự đầu Mã hàng là N (không dễ vỡ) thì 1% Thành tiền, ngược lại (Y, dễ vỡ) thì 2% Thành tiền. Fill xuống G11."},{"cell":"H2","formula":"=ROUND((F2+G2)*110%;-3)","meaning":"Đơn giá bán để có lãi 10% tính trên (Thành tiền + Hao phí) rồi làm tròn đến hàng nghìn. Fill xuống H11."}],"result":"Một bảng tính 8 cột (TT, Mã hàng, Đơn giá nhập, Số lượng, Phí vận chuyển, Thành tiền, Hao phí, Đơn giá bán), gồm tiêu đề và 10 dòng dữ liệu, có đủ đường viền, font Times New Roman 13, cột tiền có dấu ngăn cách hàng nghìn, trang in A4 ngang với lề 2.5/2.5/2.5/1.5 và bảng nằm giữa trang theo chiều ngang. Kiểm tra dòng 1 (Y001, 150000, 20): C*D = 3.000.000; Phí vận chuyển = 5% x 3.000.000 = 150.000; Thành tiền = 3.150.000; Hao phí (Y, dễ vỡ) = 2% x 3.150.000 = 63.000; Đơn giá bán = ROUND((3.150.000 + 63.000) x 1,1; -3) = ROUND(3.534.300; -3) = 3.534.000. Dòng 2 (N002, 70000, 35): C*D = 2.450.000; Phí vận chuyển = 122.500, làm tròn thành 123.000; Thành tiền = 2.573.000; Hao phí (N) = 1% x 2.573.000 = 25.730; Đơn giá bán = ROUND((2.573.000 + 25.730) x 1,1; -3) = ROUND(2.858.603; -3) = 2.859.000. Tự kiểm tra thêm: bấm Ctrl+` (phím dưới Esc) để xem công thức, bấm File > Print xem bảng nằm giữa một trang."},"checklist":["Có 10 dòng dữ liệu, cột TT từ 1 đến 10","Mã hàng đúng 4 ký tự: 1 chữ Y hoặc N + 3 số","Số lượng là số nguyên từ 1 đến 100","Toàn bộ bảng kẻ khung, căn chỉnh hợp lý, font Times New Roman cỡ 13","Cột tiền có dấu ngăn cách hàng nghìn, không có số lẻ thập phân","Trang in A4 Landscape, Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 cm","Đã tick Center on page: Horizontally","Phí vận chuyển dùng công thức, làm tròn đến hàng nghìn","Thành tiền = Đơn giá nhập x Số lượng + Phí vận chuyển (dùng dấu cộng)","Hao phí dùng IF + LEFT: N là 1%, Y là 2%","Đơn giá bán = (Thành tiền + Hao phí) x 110% làm tròn đến hàng nghìn","Công thức đã fill xuống đủ 10 dòng","Đã lưu đúng tên sbd_cau2.xlsx trong D:\\ThiCC"],"commonMistakes":["Gõ số cứng thay vì tham chiếu ô trong công thức (ví dụ gõ 5%*150000*20).","Dùng nhầm dấu phân cách đối số: máy cài kiểu Việt/Pháp thường dùng ; còn kiểu Anh/Mỹ dùng , nên công thức báo lỗi. Thử lại với dấu còn lại.","Làm tròn sai: dùng ROUND(...;3) thay vì ROUND(...;-3), kết quả giữ 3 số lẻ thay vì tròn nghìn.","Trừ phí vận chuyển thay vì cộng khi tính Thành tiền.","Quên đặt chữ N hoặc Y trong dấu nháy kép trong hàm IF.","Quên tick Horizontally nên bảng lệch trái khi in.","Nhầm Landscape với Portrait, hoặc để giấy Letter thay vì A4.","Đặt lề Right là 2.5 thay vì 1.5 cm.","Chỉ đặt font cho vùng dữ liệu và quên dòng tiêu đề.","Số lượng nhập số lẻ hoặc ngoài khoảng 1 đến 100; Mã hàng gõ 5 ký tự hoặc thiếu số."],"uncertain":["Đề số trên giấy ghi 'SỐ 02' nhưng thư mục là de co ban 1; đã chép theo ảnh.","Ảnh 1.1 hơi mờ ở yêu cầu 4. Dòng 'lượng + Phí vận chuyển' khá mờ; đọc là 'Đơn giá nhập x Số lượng + Phí vận chuyển'. Khối thứ hai của bài mẫu cũng dùng dấu cộng nên chọn dấu cộng (khối đầu của bài mẫu dùng dấu trừ, lệch đề; đã theo đề).","Bên lề trái ảnh 1.1 có chữ viết tay: 'ROUNDDOWN(5%*(C2*D2);-3)' và 'IF(LEFT(B2;1)=\"N\";F2*1%;F2*2%)'. Đề in chỉ nói 'làm tròn đến hàng nghìn' nên dùng ROUND; nếu muốn làm tròn xuống thì thay ROUND bằng ROUNDDOWN trong cột E (và có thể cả cột H). Hai hàm chỉ khác nhau khi phần dư từ 500 trở lên. Công thức IF viết tay khớp với công thức Hao phí ở trên.","Đề không yêu cầu làm tròn Hao phí; bài mẫu ở khối đầu có làm tròn Hao phí nhưng đó là lệch đề nên không làm tròn.","Đơn giá bán tính theo (F+G)*110% đúng như bài mẫu và mô tả 'mức lãi tính dựa trên thành tiền và hao phí', không chia cho Số lượng.","Dữ liệu dòng 3 đến 10 là giả định lấy từ bài mẫu; đề cho phép nhập dữ liệu giả định miễn đúng quy tắc. Ở dòng 2 bài mẫu ghi Y002 và số lượng 25, còn đề in N002 và 35; đã theo đề.","Đề tiếp tục ở đầu ảnh 1.2 (yêu cầu 5 của Câu 2); đã gộp vào Câu 2."]},{"no":3,"app":"powerpoint","title":"Câu 3. Tạo các trang trình chiếu (Microsoft PowerPoint)","statement":{"intro":"Sử dụng phần mềm Microsoft PowerPoint thiết kế slides trình chiếu phục vụ cho bài thuyết trình giới thiệu về Bảo tàng ở Hà Nội (05 slides), thông tin đưa ra trong bài thuyết trình được thí sinh chọn lọc trong tập tin 10_BaotangHaNoi.docx, trong đó có các nội dung sau:","requirements":["- Trang 1: Giới thiệu. Tên bài thuyết trình \"Bảo tàng ở Hà Nội\".","- Trang 2: Nội dung trình bày: tên 3 bảo tàng được trình bày ở các trang tiếp theo.","- Trang 3, 4, 5: Mỗi trang trình bày về một bảo tàng: nội dung trình bày tùy vào hiểu biết của từng thí sinh, tuy nhiên mỗi di tích phải đảm bảo 3 nội dung và có hình ảnh đi kèm.","Lưu ý: Trên slides trình chiếu không chứa nội dung liên quan thông tin cá nhân của thí sinh.","Yêu cầu:","1) Trình bày và căn chỉnh 5 slide theo yêu cầu nội dung như trên. Đánh số trang tự động cho các slide (trừ slide đầu tiên).","2) Trong Master Slide, điều chỉnh tất cả font chữ về Arial, nội dung căn chỉnh 2 bên.","3) Tạo mới và sử dụng ít nhất 02 layout cho bài trình chiếu.","4) Sử dụng ít nhất 02 hiệu ứng hoạt hình khác nhau (Animation).","5) Sử dụng ít nhất 02 hiệu ứng chuyển slide khác nhau (Transition)."],"material":[{"kind":"text","caption":"Cấu trúc 5 slide theo đề","lines":["Slide 1: BẢO TÀNG Ở HÀ NỘI","Slide 2: Nội dung trình bày: tên 3 bảo tàng (ví dụ: Bảo tàng Lịch sử Hà Nội; Bảo tàng Hà Nội; Bảo tàng Hồ Chí Minh)","Slide 3: Bảo tàng thứ nhất: 3 nội dung + hình ảnh","Slide 4: Bảo tàng thứ hai: 3 nội dung + hình ảnh","Slide 5: Bảo tàng thứ ba: 3 nội dung + hình ảnh"]},{"kind":"text","caption":"Ví dụ nội dung theo bài mẫu tuân01.pptx (tham khảo; thí sinh tự chọn lọc từ tệp 10_BaotangHaNoi.docx, tệp này không có trong thư mục)","lines":["BẢO TÀNG LỊCH SỬ HÀ NỘI: Tọa lạc ở quận Hoàn Kiếm đã từ lâu đời, bảo tàng lịch sử quốc gia là nơi trưng bày lưu giữ và bảo quản khoảng 200.000 hiện vật, tư liệu lịch sử văn hóa Việt Nam.","BẢO TÀNG HÀ NỘI: Thủ đô cũng có riêng cho mình một địa điểm để trưng bày những nét độc đáo trong nền văn hóa của mảnh đất hơn một ngàn năm tuổi.","BẢO TÀNG HỒ CHÍ MINH: Đây là nơi lưu trữ những hiện vật gắn liền với chủ tịch Hồ Chí Minh, bạn có thể tìm thấy cả cuộc đời người lãnh tụ vĩ đại của dân tộc tại nơi này."]}]},"solution":{"summary":"Chỉnh Slide Master trước (font Arial, căn đều 2 bên, thêm ít nhất 2 layout mới), rồi tạo 5 slide dùng các layout đó, chèn số trang tự động trừ slide đầu, sau cùng gán ít nhất 2 hiệu ứng Animation và 2 hiệu ứng Transition khác nhau.","steps":[{"title":"Tạo file và đặt tên, chuẩn bị nội dung","forRequirement":"Chung","actions":["Mở PowerPoint > Blank Presentation.","Ctrl+S > lưu D:\\ThiCC với tên sbd_cau3.pptx.","Mở tệp 10_BaotangHaNoi.docx (đề cho sẵn) để chọn lọc nội dung. Không đưa thông tin cá nhân của thí sinh (tên, số báo danh) lên slide."],"note":"Trên slide không được chứa nội dung liên quan thông tin cá nhân của thí sinh.","shots":[{"file":"b1-1.png","caption":"Mở PowerPoint, chọn Blank Presentation. Tab File (khoanh đỏ) mở menu lưu file.","w":1920,"h":1020},{"file":"b1-2.png","caption":"File, Save As (khoanh đỏ) hoặc Ctrl+S. Chọn thư mục D:ThiCC, đặt tên sbd_cau3.pptx.","w":200,"h":600}]},{"title":"Trong Slide Master: đổi font về Arial và căn đều hai bên","forRequirement":"2) Master Slide: font Arial, nội dung căn chỉnh 2 bên","actions":["Tab View > nhóm Master Views > Slide Master.","Đổi font toàn theme: tab Slide Master > nhóm Background > Fonts > Customize Fonts... > Heading font: Arial; Body font: Arial > đặt Name (ví dụ Arial All) > Save. Nhờ đó mọi layout và mọi ô văn bản đều dùng Arial.","Nếu muốn chắc chắn, chọn từng ô văn bản trên Slide Master (ô Title, ô Click to edit Master text styles) và đặt Font = Arial ở tab Home.","Căn đều hai bên (Justify): ở slide master lớn nhất (trên cùng cột trái), click vào khung \"Click to edit Master text styles\", chọn cả khung (bấm viền khung) > Home > nhóm Paragraph > Justify (Ctrl+J). Làm tương tự cho các khung nội dung, khung văn bản trong các layout sẽ dùng. Tiêu đề có thể giữ căn giữa hoặc căn trái.","Bấm Close Master View (tab Slide Master) để quay lại."],"note":"Phải làm trong Slide Master chứ không chỉ sửa từng slide. Sửa từng ô trên slide không được tính là làm trong Master Slide.","shots":[{"file":"b2-1.png","caption":"Tab View, bấm Slide Master (khoanh đỏ) để vào chế độ chỉnh slide mẫu.","w":1920,"h":1020},{"file":"b2-2.png","caption":"Tab Slide Master, bấm Fonts rồi chọn Customize Fonts... (khoanh đỏ).","w":1920,"h":1020},{"file":"b2-3.png","caption":"Hộp thoại Create New Theme Fonts: Heading font và Body font đều chọn Arial, đặt Name rồi bấm Save (các ô khoanh đỏ).","w":1920,"h":1020},{"file":"b2-4.png","caption":"Chọn slide master lớn nhất ở đầu cột trái, bấm vào khung nội dung rồi tab Home, bấm Justify (khoanh đỏ) để căn đều hai bên.","w":1920,"h":1020}]},{"title":"Tạo ít nhất 02 layout mới","forRequirement":"3) Tạo mới và sử dụng ít nhất 02 layout","actions":["Tab View > Slide Master. Trong cột trái click vào một layout, hoặc click vào khoảng trống cuối danh sách layout.","Tab Slide Master > nhóm Edit Master > Insert Layout. Một layout mới xuất hiện ở cuối (có Title và 3 ô Date, Footer, Slide Number).","Bấm Rename (nhóm Edit Master) > đặt tên, ví dụ: Gioi thieu > OK.","Chèn ô giữ chỗ: tab Slide Master > nhóm Master Layout > Insert Placeholder > chọn loại (Text, Picture, Content). Ví dụ Layout 1 \"Gioi thieu\": Title ở giữa và 1 ô Text phía dưới làm phụ đề. Layout 2 \"Bao tang va anh\": Title ở trên, ô Text bên trái (3 ý nội dung), ô Picture bên phải (hình ảnh).","Kéo, đổi kích thước các placeholder cho hợp lý. Đảm bảo ô Slide Number còn trong layout (tick Slide Number ở nhóm Master Layout nếu thiếu).","Lặp lại để có ít nhất 02 layout mới (2 layout nên có bố cục khác nhau).","Bấm Close Master View."],"note":"Layout mới phải có tên riêng và được DÙNG thực sự cho slide (xem bước sau), không chỉ tạo ra rồi bỏ.","shots":[{"file":"b3-1.png","caption":"Trong Slide Master, bấm Insert Layout (khoanh đỏ) để thêm một layout mới.","w":1920,"h":1020},{"file":"b3-2.png","caption":"Bấm Rename, đặt tên layout (ví dụ Gioi thieu) rồi bấm Rename (các ô khoanh đỏ).","w":1920,"h":1020},{"file":"b3-3.png","caption":"Insert Placeholder: chọn loại khung cần thêm vào layout như Text hoặc Picture (khoanh đỏ).","w":1920,"h":1020},{"file":"b3-4.png","caption":"Layout mới Gioi thieu (khoanh đỏ) có khung tiêu đề ở giữa và một khung chữ phía dưới.","w":1920,"h":1020},{"file":"b3-5.png","caption":"Layout thứ hai Bao tang va anh (khoanh đỏ): tiêu đề ở trên, khung chữ bên trái, khung Picture bên phải.","w":1920,"h":1020},{"file":"b3-6.png","caption":"Bấm Close Master View (khoanh đỏ) để quay về chế độ soạn slide.","w":1920,"h":1020}]},{"title":"Tạo 5 slide và áp dụng layout","forRequirement":"3) Sử dụng layout; 1) Trình bày 5 slide","actions":["Slide 1: Home > New Slide, rồi Home > Layout > chọn layout mới \"Gioi thieu\". Gõ tiêu đề: Bảo tàng ở Hà Nội.","Slide 2: Home > New Slide > Layout > chọn Title and Content (hoặc layout mới). Gõ tiêu đề (ví dụ Nội dung trình bày) và 3 dòng tên 3 bảo tàng theo đúng thứ tự trình bày ở các slide tiếp theo, ví dụ: Bảo tàng Lịch sử Hà Nội; Bảo tàng Hà Nội; Bảo tàng Hồ Chí Minh.","Slide 3, 4, 5: mỗi slide dùng layout mới \"Bao tang va anh\": tiêu đề là tên bảo tàng; ô văn bản ghi 3 nội dung ngắn (3 ý, ví dụ: vị trí, ý nghĩa lịch sử, hiện vật tiêu biểu); chèn hình ảnh qua ô Picture (bấm biểu tượng Picture) hoặc Insert > Pictures.","Lấy nội dung từ 10_BaotangHaNoi.docx: mở Word, chọn đoạn cần, Ctrl+C; quay lại PowerPoint, click vào ô văn bản, bấm Ctrl+Alt+V và chọn Unformatted Text (hoặc Paste > Keep Text Only) để không mang font lạ vào slide.","Kiểm tra thứ tự: slide 2 liệt kê 3 bảo tàng đúng thứ tự trình bày ở slide 3, 4, 5."],"note":"Mỗi slide bảo tàng phải bảo đảm 3 nội dung và có hình ảnh kèm theo. Không ghi tên thí sinh lên slide.","shots":[{"file":"b4-1.png","caption":"Tab Home, bấm Layout (khoanh đỏ): hai layout vừa tạo là Gioi thieu và Bao tang va anh (khoanh đỏ) nằm trong danh sách.","w":1920,"h":1020},{"file":"b4-2.png","caption":"Slide 1 dùng layout Gioi thieu: gõ tiêu đề Bảo tàng ở Hà Nội ở khung tiêu đề (các khung khoanh đỏ).","w":1920,"h":1020},{"file":"b4-3.png","caption":"Slide 2 dùng Title and Content: tiêu đề Nội dung trình bày và 3 dòng tên 3 bảo tàng theo thứ tự trình bày.","w":1920,"h":1020},{"file":"b4-4.png","caption":"Slide 3 dùng layout Bao tang va anh: tên bảo tàng, 3 ý nội dung và một hình ảnh (các khung khoanh đỏ). Chữ đã là Arial, căn đều hai bên.","w":1920,"h":1020},{"file":"b4-5.png","caption":"Cột trái hiện đủ 5 slide: slide 1 giới thiệu, slide 2 nội dung, slide 3 đến 5 mỗi slide một bảo tàng có hình (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Đánh số trang tự động, trừ slide đầu","forRequirement":"1) Đánh số trang tự động (trừ slide đầu tiên)","actions":["Tab Insert > nhóm Text > Slide Number (hoặc Header & Footer).","Trong hộp thoại Header and Footer, tab Slide: tick Slide number; tick Don't show on title slide.","Bấm Apply to All.","Nếu slide 1 không dùng layout Title Slide thì \"Don't show on title slide\" sẽ không loại slide 1. Khi đó bấm chọn slide 1 > Insert > Header & Footer > bỏ tick Slide number > bấm Apply (không bấm Apply to All).","Cách của bài mẫu: số trang hiện 1 ở slide 2, nghĩa là đã đặt Design > Slide Size > Custom Slide Size... > Number slides from: 0. Đây không bắt buộc, đề chỉ yêu cầu đánh số tự động trừ slide đầu."],"note":"Slide 1 không có số; slide 2 đến 5 có số tự động (không gõ số bằng tay).","shots":[{"file":"b5-1.png","caption":"Chọn slide 2, tab Insert, bấm Slide Number (khoanh đỏ).","w":1920,"h":1020},{"file":"b5-2.png","caption":"Hộp thoại Header and Footer, tab Slide: tick Slide number và Don't show on title slide, rồi bấm Apply to All (các mục khoanh đỏ).","w":1920,"h":1020},{"file":"b5-3.png","caption":"Số trang xuất hiện tự động ở góc dưới phải (khoanh đỏ), tính từ slide 2. Slide 1 không có số vì đã bỏ tick Slide number riêng cho slide này.","w":1920,"h":1020}]},{"title":"Thêm hiệu ứng hoạt hình (Animation) khác nhau","forRequirement":"4) Ít nhất 02 hiệu ứng hoạt hình khác nhau","actions":["Chọn một đối tượng trên slide (tiêu đề, ô văn bản hoặc hình ảnh). Tab Animations > nhóm Animation > chọn một hiệu ứng trong thư viện, ví dụ Fade.","Chọn đối tượng khác (ví dụ hình ảnh) > chọn hiệu ứng khác, ví dụ Fly In, Zoom hoặc Wipe.","Dùng Animation Pane để kiểm tra thứ tự: Animations > Advanced Animation > Animation Pane. Chọn Start: On Click hoặc After Previous trong nhóm Timing.","Làm ở ít nhất 2 slide hoặc 2 đối tượng, bảo đảm có ít nhất 2 loại hiệu ứng khác nhau trong cả bài (ví dụ Fade ở slide 3, Fly In ở slide 4, Zoom ở slide 5)."],"note":"Hai hiệu ứng phải KHÁC nhau. Dùng Fade ở mọi chỗ là không đủ.","shots":[{"file":"b6-1.png","caption":"Slide 3: chọn tiêu đề, tab Animations, chọn hiệu ứng Fade (khoanh đỏ).","w":1920,"h":1020},{"file":"b6-2.png","caption":"Bấm Animation Pane (khoanh đỏ) để mở bảng liệt kê các hiệu ứng của slide và kiểm tra thứ tự.","w":1920,"h":1020},{"file":"b6-3.png","caption":"Slide 4: chọn hình ảnh, chọn hiệu ứng Fly In (khoanh đỏ), khác với Fade ở slide 3.","w":1920,"h":1020},{"file":"b6-4.png","caption":"Slide 5: chọn hình ảnh, bấm mũi tên mở rộng thư viện rồi chọn Zoom (khoanh đỏ). Bài có 3 hiệu ứng khác nhau: Fade, Fly In, Zoom.","w":1920,"h":1020}]},{"title":"Thêm hiệu ứng chuyển slide (Transition) khác nhau","forRequirement":"5) Ít nhất 02 hiệu ứng chuyển slide khác nhau","actions":["Chọn slide 1 trong cột trái > tab Transitions > nhóm Transition to This Slide > chọn Split (hoặc Fade).","Chọn slide 2 > chọn Wipe; slide 3 > Circle (hoặc Push); slide 4 > Fade (bài mẫu dùng Split, Wipe, Circle, Fade).","Điều chỉnh Duration ở nhóm Timing nếu cần (ví dụ 01.00). Để On Mouse Click hoặc đặt After đều được.","Tránh dùng Apply To All cho cùng một hiệu ứng vì sẽ không đủ 2 loại khác nhau."],"note":"Apply To All làm mọi slide cùng một hiệu ứng, không thỏa yêu cầu 2 hiệu ứng khác nhau.","shots":[{"file":"b7-1.png","caption":"Slide 1: tab Transitions, chọn Split (khoanh đỏ).","w":1920,"h":1020},{"file":"b7-2.png","caption":"Slide 2: chọn Wipe (khoanh đỏ).","w":1920,"h":1020},{"file":"b7-3.png","caption":"Slide 3: chọn Push (khoanh đỏ).","w":1920,"h":1020},{"file":"b7-4.png","caption":"Slide 4: chọn Fade (khoanh đỏ). Mỗi slide một hiệu ứng khác nhau, không bấm Apply To All.","w":1920,"h":1020},{"file":"b7-5.png","caption":"Các slide đã gắn hiệu ứng chuyển có biểu tượng ngôi sao nhỏ cạnh số slide ở cột trái (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Rà soát và lưu","forRequirement":"Chung","actions":["Bấm F5 (Slide Show từ đầu) để xem 5 slide, kiểm tra animation, transition, số trang.","Kiểm tra: toàn bộ font Arial; nội dung căn đều 2 bên; 5 slide đúng thứ tự; không có tên thí sinh trên slide.","Ctrl+S để lưu tệp sbd_cau3.pptx trong D:\\ThiCC."],"note":"","shots":[{"file":"b8-1.png","caption":"Tab Slide Show, bấm From Beginning (khoanh đỏ) hoặc phím F5 để xem cả bài từ đầu.","w":1920,"h":1020},{"file":"b8-2.png","caption":"Chế độ Slide Sorter cho thấy đủ 5 slide: slide 1 giới thiệu không có số trang, các slide còn lại có số trang và biểu tượng hiệu ứng.","w":1920,"h":1020}]}],"formulas":[],"result":"Tệp sbd_cau3.pptx gồm 5 slide: slide 1 tên 'Bảo tàng ở Hà Nội' (không số trang), slide 2 liệt kê tên 3 bảo tàng, slide 3 đến 5 mỗi slide một bảo tàng có 3 nội dung và hình ảnh; toàn bộ font Arial; nội dung căn đều hai bên; có ít nhất 2 layout tự tạo và có dùng trong slide; số trang tự động từ slide 2; có ít nhất 2 loại Animation và 2 loại Transition khác nhau. Tự kiểm tra: mở View > Slide Master xem layout đã tạo; chạy F5 xem hiệu ứng; mở View > Slide Sorter, biểu tượng ngôi sao nhỏ dưới slide cho biết slide đã có hiệu ứng."},"checklist":["Có đúng 5 slide: slide 1 giới thiệu, slide 2 liệt kê 3 bảo tàng, slide 3 đến 5 mỗi slide một bảo tàng","Mỗi slide bảo tàng có đủ 3 nội dung và có hình ảnh","Slide 1 không hiện số trang, slide 2 đến 5 có số trang tự động","Slide Master: font Arial cho tiêu đề và nội dung","Slide Master: nội dung căn đều hai bên (Justify)","Đã tạo ít nhất 02 layout mới và đã dùng cho slide","Có ít nhất 02 hiệu ứng Animation khác nhau","Có ít nhất 02 hiệu ứng Transition khác nhau","Không có thông tin cá nhân của thí sinh trên slide","Đã lưu đúng tên sbd_cau3.pptx trong D:\\ThiCC"],"commonMistakes":["Chỉnh font ở từng slide thay vì ở Slide Master, hoặc chỉ đổi font Title mà quên font Body.","Quên căn đều 2 bên (Justify) trong Master, hoặc chỉ căn đều trên một slide.","Chỉ chọn layout có sẵn mà không tạo layout mới (Insert Layout), hoặc có tạo nhưng không dùng cho slide nào.","Gõ số trang bằng tay thay vì Insert > Slide Number; hoặc quên tick Don't show on title slide làm slide đầu vẫn hiện số.","Dùng cùng một hiệu ứng Animation hoặc Transition cho tất cả (Apply To All) nên không đủ 02 loại khác nhau.","Slide bảo tàng thiếu hình ảnh hoặc chỉ có 1 đến 2 nội dung.","Ghi tên, số báo danh của thí sinh lên slide.","Lưu sai tên hoặc sai thư mục."],"uncertain":["Ảnh 1.2 chụp lệch, có một trang giấy khác chồng lên phía trên (đề câu Excel khác với các dòng 'Mã SV', 'Họ tên', 'theo dõi điểm quá trình'); phần đó không thuộc đề này nên đã bỏ qua. Dòng yêu cầu 5 của Câu 2 (Đơn giá bán) nằm ở đầu ảnh này và đã được gộp vào Câu 2.","Đề không cho nội dung cụ thể từng bảo tàng và tệp 10_BaotangHaNoi.docx không có trong thư mục; phần ví dụ lấy từ bài mẫu tuân01.pptx.","Bài mẫu tuân01.pptx dùng layout dựng sẵn (Title Slide, Title Only, Content with Caption) và mỗi bảo tàng chỉ có 1 đoạn mô tả; đề yêu cầu tạo layout mới và 3 nội dung mỗi bảo tàng nên hướng dẫn làm theo đề.","Bài mẫu đánh số 1 ở slide 2 (Number slides from 0); đề chỉ yêu cầu đánh số tự động trừ slide đầu nên không bắt buộc cách này.","'Nội dung căn chỉnh 2 bên' được hiểu là căn đều hai bên (Justify)."]}]},{"id":2,"title":"Đề thực hành số 2","source":"de co ban 2","timeLimitMinutes":60,"generalNotes":["Đề thi cấp chứng chỉ UDCNTT cơ bản, Học viện Kỹ thuật Quân sự, Khoa Công nghệ thông tin, đợt thi B200208018, thời gian 60 phút.","Đề thi gồm 3 trang; không được sử dụng tài liệu, USB và các thiết bị lưu trữ khác.","Các file bài làm để trong thư mục D:\\ThiCC, cách đặt tên file: Câu 1: sbd_cau1.docx; Câu 2: sbd_cau2.xlsx; Câu 3: sbd_cau3.pptx. Trong đó sbd là số báo danh của thí sinh."],"tasks":[{"no":1,"app":"word","title":"Câu 1. Soạn thảo văn bản (Microsoft Word)","statement":{"intro":"Sử dụng phần mềm Microsoft Word soạn thảo nội dung tài liệu trên trang 3 với các yêu cầu sau:","requirements":["1) Soạn và định dạng đầy đủ nội dung văn bản như trang 3.","2) Định dạng trang: Cỡ giấy: A4; Chiều: Portrait; Lề trên (Top): 2.5 cm, Lề dưới (Bottom): 2 cm, Lề trái (Left): 3.5 cm, Lề phải (Right): 1.5 cm; Font: Times New Roman, cỡ 13pt.","3) Sử dụng bảng 1 dòng 2 cột không đường viền cho phần thông tin của 2 dòng đầu tiên. Nội dung căn ở giữa.","4) Sử dụng bảng để thể hiện các thông tin về thời gian chương trình đào tạo. Sử dụng trộn ô, thiết lập chiều cao các dòng của bảng bằng đúng 1,5 cm.","5) Sử dụng danh sách để điền số cho cột số thứ tự (TT)."],"material":[{"kind":"text","caption":"Phần đầu văn bản (đưa vào bảng 1 dòng 2 cột không viền)","lines":["Ô trái, dòng 1: BỘ GIÁO DỤC VÀ ĐÀO TẠO","Ô trái, dòng 2: TRƯỜNG ĐẠI HỌC ABC (in đậm)","Ô phải, dòng 1: CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM (in đậm)","Ô phải, dòng 2: Độc lập - Tự do - Hạnh phúc (in đậm)"]},{"kind":"text","caption":"Tiêu đề văn bản (in đậm, căn giữa)","lines":["THỜI GIAN TỐI THIỂU THỰC HIỆN CHƯƠNG TRÌNH ĐÀO TẠO TỪ XA","CHO TỪNG TRÌNH ĐỘ VÀ NGÀNH ĐÀO TẠO"]},{"kind":"table","caption":"Bảng thời gian đào tạo (9 dòng x 3 cột; cột TT đánh số tự động dạng (1), (2), ...; ô thời gian của dòng (2)-(3) và của dòng (7)-(8) là ô trộn)","rows":[["TT","Trình độ và ngành đầu vào","Thời gian tối thiểu hoàn thành chương trình ĐTTX các ngành"],["(1)","Từ đại học trở lên và ngành gần","1,0 năm"],["(2)","Từ đại học trở lên và khác ngành","1,5 năm"],["(3)","Cao đẳng cùng ngành hoặc ngành gần","1,5 năm"],["(4)","Cao đẳng khác ngành","2,0 năm"],["(5)","Trung học chuyên nghiệp hoặc trung cấp chuyên nghiệp có cùng ngành hoặc ngành gần","2,5 năm"],["(6)","Có bằng THPT và Trung cấp lý luận chính trị","3,0 năm"],["(7)","Trung học chuyên nghiệp hoặc trung cấp chuyên nghiệp, khác ngành","3,5 năm"],["(8)","Trung học phổ thông hoặc Bổ túc trung học hoặc Trung cấp nghề","3,5 năm"]]},{"kind":"text","caption":"Dòng cuối văn bản (in đậm, nằm lệch bên phải)","lines":["TRƯỜNG ĐẠI HỌC ABC"]}]},"solution":{"summary":"Thiết lập trang và font mặc định trước, sau đó chèn bảng 1x2 không viền chứa 2 dòng đầu, gõ tiêu đề, chèn bảng 9 dòng x 3 cột, trộn ô, đặt chiều cao dòng Exactly 1.5 cm và đánh số cột TT bằng Numbering dạng (1).","steps":[{"title":"Tạo file và lưu tên đúng quy định","forRequirement":"Ghi chú chung","actions":["Mở Word, tạo Blank document (Ctrl+N).","Bấm Ctrl+S, chọn thư mục D:\\ThiCC, đặt tên file là sbd_cau1.docx (sbd là số báo danh của bạn, ví dụ 123_cau1.docx), bấm Save.","Trong lúc làm, thỉnh thoảng bấm Ctrl+S để tránh mất bài."],"note":"Lưu ngay từ đầu. Nhớ đúng thư mục D:\\ThiCC và đuôi .docx.","shots":[{"file":"b1-1.png","caption":"Mở Word, chọn Blank document. Tab File (khoanh đỏ) mở menu lưu file.","w":1920,"h":1020},{"file":"b1-2.png","caption":"File, Save As (khoanh đỏ) hoặc Ctrl+S. Chọn thư mục D:ThiCC, đặt tên sbd_cau1.docx rồi bấm Save.","w":200,"h":600}]},{"title":"Định dạng trang: khổ A4, Portrait, 4 lề","forRequirement":"2","actions":["Chọn tab Layout (bản Office cũ gọi là Page Layout).","Ở nhóm Page Setup, bấm mũi tên nhỏ ở góc dưới bên phải nhóm (Dialog Launcher) để mở hộp thoại Page Setup.","Tab Margins: nhập Top = 2.5 cm, Bottom = 2 cm, Left = 3.5 cm, Right = 1.5 cm. Gutter để 0 cm. Mục Orientation chọn Portrait (hướng đứng). Mục Apply to: Whole document.","Chuyển sang tab Paper: ở ô Paper size chọn A4 (21 cm x 29.7 cm). Kiểm tra Width = 21 cm, Height = 29.7 cm.","Bấm OK. Nếu Word hỏi về lề nằm ngoài vùng in thì chọn Ignore."],"note":"Nếu ô hiển thị đơn vị inch, gõ kèm chữ cm sau số, ví dụ 2.5 cm, Word sẽ tự đổi. Máy dùng dấu phẩy thập phân thì gõ 2,5.","shots":[{"file":"b2-1.png","caption":"Tab Layout, bấm mũi tên nhỏ ở góc dưới phải nhóm Page Setup (khoanh đỏ) để mở hộp thoại Page Setup.","w":1920,"h":1020},{"file":"b2-2.png","caption":"Tab Margins: Top 2.5 cm, Bottom 2 cm, Left 3.5 cm, Right 1.5 cm và chọn Portrait (các ô khoanh đỏ).","w":1920,"h":1020},{"file":"b2-3.png","caption":"Tab Paper: Paper size chọn A4 (khoanh đỏ), khổ 21 x 29.7 cm, rồi bấm OK.","w":1920,"h":1020}]},{"title":"Đặt font Times New Roman 13pt và giãn dòng gọn","forRequirement":"2","actions":["Tab Home > nhóm Styles > bấm chuột phải vào style Normal > Modify (Sửa đổi).","Trong hộp thoại Modify Style, mục Formatting chọn Font = Times New Roman, Size = 13. Bấm nút Format (góc dưới trái) > Paragraph, đặt Spacing Before = 0 pt, After = 0 pt, Line spacing = Single, bấm OK hai lần.","Cuối bài, bấm Ctrl+A rồi kiểm tra ô Font (Home) hiển thị Times New Roman và ô cỡ chữ hiển thị 13. Nếu có nội dung nào khác thì chọn lại Times New Roman, 13."],"note":"Từ Word 2007 trở lên, mặc định After = 10pt và Line spacing = 1.15, nếu không chỉnh thì chữ trong ô dễ bị cắt khi đặt chiều cao Exactly 1.5 cm.","shots":[{"file":"b3-1.png","caption":"Tab Home, bấm phải vào kiểu Normal trong nhóm Styles, chọn Modify... (khoanh đỏ).","w":1920,"h":1020},{"file":"b3-2.png","caption":"Hộp thoại Modify Style: Font Times New Roman, cỡ 13 (khoanh đỏ). Bấm Format (khoanh đỏ), chọn Paragraph... để đặt giãn đoạn Before 0, After 0, Line spacing Single.","w":1920,"h":1020}]},{"title":"Tạo bảng 1 dòng 2 cột không viền cho 2 dòng đầu","forRequirement":"3","actions":["Đặt con trỏ ở đầu tài liệu trống. Tab Insert > nhóm Tables > Table > Insert Table, nhập Number of columns = 2, Number of rows = 1, bấm OK. (Dưới bảng sẽ có sẵn một đoạn trống để gõ tiêu đề.)","Ô trái: gõ 'BỘ GIÁO DỤC VÀ ĐÀO TẠO', bấm Enter, gõ 'TRƯỜNG ĐẠI HỌC ABC', bôi đen dòng này và bấm Ctrl+B để in đậm.","Ô phải: gõ 'CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM', Enter, 'Độc lập - Tự do - Hạnh phúc'. Bôi đen cả hai dòng, bấm Ctrl+B in đậm.","Chọn cả bảng: đưa chuột vào bảng, bấm dấu chữ thập 4 mũi tên ở góc trên trái bảng. Bấm Ctrl+E để căn giữa nội dung trong ô.","Bỏ đường viền: khi bảng vẫn đang chọn, vào tab Home > nhóm Paragraph > nút Borders (hình ô vuông) > chọn No Border. (Hoặc tab Table Design > Borders > No Border.)","Kiểm tra: tab tab Table Layout > View Gridlines chỉ là đường kẻ ảo để dễ nhìn. Bấm Ctrl+P xem trước, sẽ không còn đường viền nào."],"note":"Hai dòng đầu tiên của văn bản chính là hai dòng nằm trong bảng này, không gõ chúng ngoài bảng.","shots":[{"file":"b4-1.png","caption":"Tab Insert, bấm Table rồi chọn Insert Table... (khoanh đỏ).","w":1920,"h":1020},{"file":"b4-2.png","caption":"Nhập Number of columns 2, Number of rows 1 (khoanh đỏ) rồi bấm OK.","w":1920,"h":1020},{"file":"b4-3.png","caption":"Gõ nội dung hai ô, in đậm các dòng cần đậm (nút B), chọn cả bảng và bấm Center (các nút khoanh đỏ) để căn giữa.","w":1920,"h":1020},{"file":"b4-4.png","caption":"Chọn cả bảng, tab Home, bấm mũi tên cạnh nút Borders (khoanh đỏ) rồi chọn No Border (khoanh đỏ) để bỏ đường viền.","w":1920,"h":1020}]},{"title":"Gõ tiêu đề văn bản","forRequirement":"1","actions":["Bấm chuột vào đoạn trống ngay dưới bảng 1x2. (Nếu không thấy đoạn trống, đặt con trỏ ở cuối ô cuối cùng của bảng rồi bấm Alt+Enter hoặc mũi tên xuống để tạo đoạn bên dưới.)","Gõ 'THỜI GIAN TỐI THIỂU THỰC HIỆN CHƯƠNG TRÌNH ĐÀO TẠO TỪ XA CHO TỪNG TRÌNH ĐỘ VÀ NGÀNH ĐÀO TẠO'.","Bôi đen tiêu đề, bấm Ctrl+B (in đậm) và Ctrl+E (căn giữa). Có thể đặt Spacing Before/After = 6 pt cho thoáng."],"note":"","shots":[{"file":"b5-1.png","caption":"Gõ tiêu đề dưới bảng, in đậm (nút B) và căn giữa (nút Center), các nút khoanh đỏ; tiêu đề nằm trong vùng khoanh đỏ.","w":1920,"h":1020}]},{"title":"Chèn bảng thời gian đào tạo 9 dòng x 3 cột","forRequirement":"1, 4","actions":["Bấm Enter cuối tiêu đề để tạo đoạn mới. Tab Insert > Table > Insert Table, nhập Number of columns = 3, Number of rows = 9, bấm OK.","Gõ dòng tiêu đề: ô 1 'TT', ô 2 'Trình độ và ngành đầu vào', ô 3 'Thời gian tối thiểu hoàn thành chương trình ĐTTX các ngành'. Bôi đen dòng này, in đậm (Ctrl+B), căn giữa (Ctrl+E).","Gõ nội dung cột 2 và cột 3 của 8 dòng dữ liệu đúng như đề. Cột TT để trống ở bước này (sẽ đánh số bằng danh sách).","Chỉnh độ rộng cột: kéo đường kẻ dọc hoặc dùng tab Table Layout > nhóm Cell Size > Width. Gợi ý: cột 1 = 1.5 cm, cột 2 = 8 cm, cột 3 = 6.5 cm (tổng 16 cm = vùng soạn thảo rộng 21 - 3.5 - 1.5 = 16 cm).","Căn chỉnh: cột 1 và cột 3 căn giữa (Ctrl+E), cột 2 căn trái (Ctrl+L). Canh giữa theo chiều dọc: chọn cả bảng > tab Table Layout > nhóm Alignment > Align Center Left (cột 2) hoặc Align Center (cột 1, 3)."],"note":"Dòng tiêu đề cột 3 khá dài nên có thể xuống 3 dòng. Với Exactly 1.5 cm, 3 dòng chữ 13pt vẫn vừa nếu Spacing Before/After = 0 và Line spacing = Single. Nếu bị cắt thì nới rộng cột 3.","shots":[{"file":"b6-1.png","caption":"Bấm Enter dưới tiêu đề, Insert, Table, Insert Table...: Number of columns 3, Number of rows 9 (khoanh đỏ), bấm OK.","w":1920,"h":1020},{"file":"b6-2.png","caption":"Gõ nội dung, đặt độ rộng cột trong tab Table Layout, ô Width (khoanh đỏ): cột 1 rộng 1.5 cm, cột 2 rộng 8 cm, cột 3 rộng 6.5 cm.","w":1920,"h":1020}]},{"title":"Trộn ô (Merge Cells) cho cột Thời gian","forRequirement":"4","actions":["Cặp 1: bôi đen 2 ô '1,5 năm' ở cột 3 của dòng (2) và dòng (3) (hai ô liền nhau trong cùng một cột).","Bấm chuột phải vào vùng đã chọn > Merge Cells, hoặc tab tab Table Layout > nhóm Merge > Merge Cells.","Cặp 2: bôi đen 2 ô '3,5 năm' ở cột 3 của dòng (7) và (8), bấm Merge Cells tương tự.","Sau khi trộn, nội dung hai ô nối thành hai đoạn trong ô mới (đúng như trang 3 hiển thị hai dòng '1,5 năm' và hai dòng '3,5 năm'). Có thể giữ nguyên hoặc xóa bớt một dòng cho gọn; yêu cầu chấm là ô đã được trộn.","Căn giữa nội dung ô trộn cả chiều ngang (Ctrl+E) và chiều dọc (Layout > Align Center)."],"note":"Chọn đúng hai ô liền nhau trong cùng một cột; chọn nhầm cả dòng sẽ trộn sai.","shots":[{"file":"b7-1.png","caption":"Bôi chọn hai ô 1,5 năm liền nhau ở cột 3 rồi bấm Merge Cells (khoanh đỏ) trong tab Table Layout.","w":1920,"h":1020},{"file":"b7-2.png","caption":"Kết quả sau khi trộn: ô 1,5 năm và ô 3,5 năm đã là ô trộn (vùng khoanh đỏ), mỗi ô hiện hai dòng.","w":1920,"h":1020}]},{"title":"Đặt chiều cao các dòng của bảng đúng 1,5 cm","forRequirement":"4","actions":["Chọn toàn bộ bảng (bấm dấu chữ thập góc trên trái bảng).","Bấm chuột phải > Table Properties (hoặc tab Table Layout > Properties).","Chuyển tab Row. Tích 'Specify height', nhập 1.5 cm. Ở ô 'Row height is' chọn Exactly (đúng bằng). Bỏ tích 'Allow row to break across pages' cho gọn.","Bấm OK. Kiểm tra: bấm vào từng dòng, tab Table Layout > nhóm Cell Size > Height hiển thị 1.5 cm."],"note":"Nhập ở ô Height của nhóm Cell Size chỉ là 'At least' (tối thiểu). Để đúng 1,5 cm hãy dùng Table Properties > Row > Exactly.","shots":[{"file":"b8-1.png","caption":"Chọn cả bảng, tab Table Layout, bấm Properties (khoanh đỏ) để mở hộp thoại Table Properties.","w":1920,"h":1020},{"file":"b8-2.png","caption":"Tab Row: tick Specify height, nhập 1.5 cm và chọn Row height is Exactly (khoanh đỏ), rồi bấm OK.","w":1920,"h":1020}]},{"title":"Đánh số cột TT bằng danh sách Numbering dạng (1), (2), ...","forRequirement":"5","actions":["Bôi đen 8 ô trống của cột TT (từ dòng thứ 2 đến dòng thứ 9, không bôi ô tiêu đề 'TT').","Tab Home > nhóm Paragraph > bấm mũi tên cạnh nút Numbering > chọn Define New Number Format.","Ở ô Number style chọn '1, 2, 3, ...'. Ở ô Number format, con số xám giữ nguyên, xóa dấu chấm sau số rồi gõ thêm '(' trước con số và ')' sau con số để thành '(1)'. Alignment chọn Centered. Bấm OK.","Số (1) đến (8) xuất hiện trong 8 ô. Nếu số bị lệch vào lề trái ô: Home > Paragraph Dialog Launcher > Indentation đặt Left = 0 và Special = (none).","Căn giữa cột TT: bôi đen cột và bấm Ctrl+E."],"note":"Không gõ tay (1), (2). Nếu mỗi ô lại bắt đầu từ (1) thì do áp dụng từng ô riêng; hãy bôi đen cả 8 ô cùng lúc rồi bấm Numbering.","shots":[{"file":"b9-1.png","caption":"Bôi chọn 8 ô cột TT (không gồm ô tiêu đề), tab Home, bấm mũi tên cạnh nút Numbering rồi chọn Define New Number Format... (các mục khoanh đỏ).","w":1920,"h":1020},{"file":"b9-2.png","caption":"Number style chọn 1, 2, 3, Number format gõ (1) bằng cách thêm dấu ngoặc quanh con số, Alignment chọn Centered, rồi bấm OK (các ô khoanh đỏ).","w":1920,"h":1020},{"file":"b9-3.png","caption":"Cột TT đã có số (1) đến (8) tự động (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Dòng cuối 'TRƯỜNG ĐẠI HỌC ABC' và hoàn thiện","forRequirement":"1","actions":["Đặt con trỏ dưới bảng (nếu không có đoạn trống, bấm vào ô cuối bảng rồi bấm Alt+Enter), cách một dòng rồi gõ 'TRƯỜNG ĐẠI HỌC ABC'.","In đậm (Ctrl+B). Đẩy sang phải: Home > Paragraph Dialog Launcher > Indentation Left = 9 cm (hoặc dùng phím Tab).","Bấm Ctrl+A, kiểm tra lại Times New Roman, 13.","Bấm Ctrl+P xem trước: toàn bộ nội dung nên vừa 1 trang A4.","Bấm Ctrl+S để lưu bài."],"note":"","shots":[{"file":"b10-1.png","caption":"Gõ dòng cuối TRƯỜNG ĐẠI HỌC ABC, in đậm và đẩy sang phải. Toàn bộ nằm gọn trong một trang (Page 1 of 1 khoanh đỏ).","w":1920,"h":1020}]}],"formulas":[],"result":"Một trang A4 đứng. Trên cùng là bảng 1x2 không viền chứa 2 dòng đầu, nội dung căn giữa. Tiếp theo là tiêu đề in đậm căn giữa. Sau đó là bảng 9 dòng x 3 cột có viền, mỗi dòng cao đúng 1,5 cm, có hai cặp ô trộn ở cột Thời gian (dòng (2)-(3) và dòng (7)-(8)), cột TT hiển thị (1) đến (8) bằng Numbering. Cuối trang có 'TRƯỜNG ĐẠI HỌC ABC' in đậm lệch phải. Tất cả font Times New Roman 13pt. Tự kiểm tra: Page Setup hiển thị đúng 4 lề và A4; Table Properties > Row hiển thị 1.5 cm Exactly; Ctrl+A rồi xem ô Font không bị trống (nghĩa là chỉ có một font)."},"checklist":["File lưu tại D:\\ThiCC với tên sbd_cau1.docx","Cỡ giấy A4, hướng Portrait","Lề Top 2.5 cm, Bottom 2 cm, Left 3.5 cm, Right 1.5 cm","Toàn bộ văn bản Times New Roman, 13pt (kể cả trong bảng)","Hai dòng đầu nằm trong bảng 1 dòng 2 cột, không có đường viền, nội dung căn giữa","Tiêu đề in đậm, căn giữa, đúng nội dung","Bảng thời gian đào tạo 9 dòng x 3 cột, đủ nội dung như trang 3","Ô thời gian dòng (2)-(3) đã trộn; ô thời gian dòng (7)-(8) đã trộn","Mọi dòng của bảng cao đúng 1.5 cm (Row height is Exactly)","Cột TT điền số dạng (1) đến (8) bằng danh sách Numbering, không gõ tay","Dòng 'TRƯỜNG ĐẠI HỌC ABC' in đậm ở cuối"],"commonMistakes":["Quên chọn A4 (Word có thể đang để Letter, kích thước 21.59 x 27.94 cm).","Để mặc định Spacing After 10pt và Line spacing 1.15 khiến chữ trong ô bị cắt khi đặt chiều cao Exactly 1.5 cm.","Đặt chiều cao ở Cell Size (At least) thay vì Exactly trong Table Properties.","Gõ tay số thứ tự (1), (2) thay vì dùng Numbering.","Chỉ tô trắng đường viền hoặc tắt Gridlines thay vì chọn No Border cho bảng 1x2.","Trộn nhầm ô (chọn cả hàng thay vì hai ô cùng cột).","Quên đổi font cho nội dung trong bảng nên một số ô vẫn dùng font mặc định.","Đặt tên file sai hoặc lưu sai thư mục (không phải D:\\ThiCC)."],"uncertain":["Ảnh 2.3 (trang 3) chụp nghiêng, mép phải của bảng bị cắt; nội dung chữ vẫn đọc rõ và khớp với file mẫu DE 2.docx.","Trên trang 3, ô trộn hiển thị hai dòng '1,5 năm' và hai dòng '3,5 năm' (nội dung hai ô nối lại sau khi trộn); đã giữ đúng như vậy. Xóa bớt một dòng không ảnh hưởng yêu cầu trộn ô.","Mức in đậm của dòng đầu: giả định ô trái chỉ in đậm dòng 'TRƯỜNG ĐẠI HỌC ABC', ô phải in đậm cả hai dòng, theo hình trang 3.","Dòng cuối 'TRƯỜNG ĐẠI HỌC ABC' ở ảnh nằm lệch phải; đề không nêu căn lề cụ thể.","File mẫu 234_CÂU 1.docx dùng giấy Letter (21.59 x 27.94 cm) và DE 2.docx dùng lề trái 3.0 cm; hai điểm này lệch so với đề (A4, Left 3.5 cm), đã làm theo đề. Hai file mẫu đặt dòng cao Exactly 1.5 cm và Numbering dạng (1), khớp với cách hướng dẫn."]},{"no":2,"app":"excel","title":"Câu 2. Tạo bảng tính (Microsoft Excel)","statement":{"intro":"Bảng theo dõi điểm quá trình của môn Tương tác người máy thể hiện như bảng sau (hàng tiêu đề 2 tầng: TT, Mã SV, Họ tên, nhóm Lý thuyết gồm L1, L2, L3, nhóm Bài tập gồm B1, B2, B3, B4, rồi LT, BT, QT; dòng mẫu: 1, SV001, Nguyễn Văn A, 7, 5, 3, 8, 5, 8, 9). Sử dụng phần mềm Microsoft Excel tạo bảng điểm quá trình với các yêu cầu sau:","requirements":["1) Nhập dữ liệu (giả định) cho 10 sinh viên trên các cột: TT (thứ tự), Mã SV (Mã sinh viên), Họ tên, L1 (lần 1), L2 (lần 2), L3 (lần 3), B1 (bài 1), B2 (bài 2), B3 (bài 3), B4 (bài 4); các cột L1, L2, L3, B1, B2, B3, B4 nhận giá trị nguyên từ 0 đến 10. Kẻ khung, căn chỉnh, định dạng các kiểu dữ liệu cho phù hợp; Font: Times New Roman, cỡ 13pt.","2) Định dạng trang: Khổ giấy A4, Landscape; Top: 2.5 cm, Bottom: 2.5 cm, Left: 2.5 cm, Right: 1.5 cm. Căn chỉnh bảng tính ra giữa trang in (Horizontally).","3) Nhập công thức tính Điểm lý thuyết vào cột LT; Biết rằng Điểm lý thuyết là trung bình cộng của L1, L2, L3; làm tròn với 1 chữ số sau dấu phẩy.","4) Nhập công thức tính Điểm bài tập vào cột BT; Biết rằng Điểm bài tập là trung bình cộng của ba cột điểm lớn hơn trong bốn cột B1, B2, B3, B4; làm tròn với 1 chữ số sau dấu phẩy.","5) Nhập công thức tính Điểm quá trình vào cột QT; Biết rằng nếu Điểm lý thuyết lớn hơn 7 thì QT=BT+1, ngược lại QT=BT. Lưu ý QT nhận giá trị lớn nhất bằng 10."],"material":[{"kind":"table","caption":"Bố cục bảng và dữ liệu gợi ý (hàng 1-2 là tiêu đề 2 tầng; chỉ dòng SV001 có trong đề, các dòng còn lại là dữ liệu giả định; cột LT, BT, QT để trống vì sẽ nhập công thức)","rows":[["TT","Mã SV","Họ tên","Lý thuyết","","","Bài tập","","","","LT","BT","QT"],["","","","L1","L2","L3","B1","B2","B3","B4","","",""],["1","SV001","Nguyễn Văn A","7","5","3","8","5","8","9","","",""],["2","SV002","Nguyễn Thanh Bình","6","7","4","9","8","9","8","","",""],["3","SV003","Phan Đình Đạt","7","9","7","8","9","8","5","","",""],["4","SV004","Ngô Văn Hùng","5","8","5","7","5","7","7","","",""],["5","SV005","Lê Hồng Long","2","8","9","5","4","4","7","","",""],["6","SV006","Dương Hoài Nam","5","3","5","6","8","6","5","","",""],["7","SV007","Nguyễn Đức Quân","10","10","6","10","9","10","9","","",""],["8","SV008","Nguyễn Anh Trường","7","9","8","8","7","7","9","","",""],["9","SV009","Phạm Công Tuân","8","7","9","9","6","8","5","","",""],["10","SV010","Nguyễn Mạnh Tuyên","9","8","9","8","5","9","8","","",""]]}]},"solution":{"summary":"Dựng bảng tiêu đề 2 tầng có trộn ô ở A1:M2, nhập 10 dòng dữ liệu từ hàng 3 đến hàng 12, kẻ khung, đặt font Times New Roman 13, rồi nhập 3 công thức ở K3, L3, M3 và kéo xuống hàng 12; cuối cùng thiết lập Page Setup A4 Landscape, 4 lề và căn giữa ngang.","steps":[{"title":"Tạo file và lưu tên đúng quy định","forRequirement":"Ghi chú chung","actions":["Mở Excel, tạo Blank workbook. Bấm Ctrl+S, chọn D:\\ThiCC, đặt tên sbd_cau2.xlsx (sbd là số báo danh), bấm Save."],"note":"","shots":[{"file":"b1-1.png","caption":"Mở Excel, chọn Blank workbook. Tab File (khoanh đỏ) mở menu lưu file.","w":1920,"h":1020},{"file":"b1-2.png","caption":"File, Save As (khoanh đỏ) hoặc Ctrl+S. Chọn thư mục D:ThiCC, đặt tên sbd_cau2.xlsx, kiểu Excel Workbook (*.xlsx).","w":200,"h":600}]},{"title":"Nhập tiêu đề 2 tầng","forRequirement":"1","actions":["Ô A1 gõ TT, B1 gõ Mã SV, C1 gõ Họ tên, D1 gõ Lý thuyết, G1 gõ Bài tập, K1 gõ LT, L1 gõ BT, M1 gõ QT.","Hàng 2: D2 gõ L1, E2 gõ L2, F2 gõ L3, G2 gõ B1, H2 gõ B2, I2 gõ B3, J2 gõ B4.","Trộn ô: bôi đen A1:A2, vào tab Home > nhóm Alignment > Merge & Center. Làm tương tự cho B1:B2, C1:C2, K1:K2, L1:L2, M1:M2.","Bôi đen D1:F1 > Merge & Center (ô 'Lý thuyết'). Bôi đen G1:J1 > Merge & Center (ô 'Bài tập').","Bôi đen A1:M2: Home > Bold (Ctrl+B), căn giữa ngang (Center) và căn giữa dọc (Middle Align)."],"note":"Bảng mẫu trong đề có tiêu đề 2 tầng trộn ô, nên làm giống bảng mẫu.","shots":[{"file":"b2-1.png","caption":"Gõ tiêu đề rồi bôi chọn A1:A2, bấm Merge & Center (khoanh đỏ). Làm tương tự cho B, C, K, L, M và cho D1:F1, G1:J1.","w":1920,"h":1020},{"file":"b2-2.png","caption":"Tiêu đề hai tầng sau khi trộn ô, in đậm, căn giữa ngang và dọc (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Nhập dữ liệu cho 10 sinh viên","forRequirement":"1","actions":["Từ hàng 3 đến hàng 12 nhập: cột A là TT (1 đến 10), cột B là Mã SV (SV001 đến SV010), cột C là Họ tên, cột D đến J là điểm L1, L2, L3, B1, B2, B3, B4.","Gõ A3 = 1, A4 = 2 rồi bôi đen A3:A4 và kéo ô điền (Fill handle, chấm vuông nhỏ góc dưới phải) xuống A12. Tương tự Mã SV: gõ SV001, SV002 rồi kéo xuống SV010.","Điểm là số nguyên từ 0 đến 10. Có thể dùng bộ dữ liệu gợi ý ở phần material (dòng đầu là Nguyễn Văn A: 7, 5, 3, 8, 5, 8, 9 như đề)."],"note":"Điểm phải nhập dạng số (mặc định căn phải), không nhập dạng chữ.","shots":[{"file":"b3-1.png","caption":"Nhập 10 dòng dữ liệu từ hàng 3 đến hàng 12 (vùng khoanh đỏ): TT, Mã SV, Họ tên và điểm L1, L2, L3, B1, B2, B3, B4. Dùng Fill Handle để điền TT và Mã SV.","w":1920,"h":1020}]},{"title":"Giới hạn điểm là số nguyên 0 đến 10 (Data Validation)","forRequirement":"1","actions":["Bôi đen D3:J12.","Tab Data > nhóm Data Tools > Data Validation > Data Validation.","Tab Settings: Allow = Whole number, Data = between, Minimum = 0, Maximum = 10.","Tab Error Alert (tùy chọn): Title 'Sai điểm', Error message 'Chỉ nhập số nguyên từ 0 đến 10'. Bấm OK."],"note":"Bước này thể hiện ràng buộc 'nhận giá trị nguyên từ 0 đến 10'. Nếu thi gấp thì có thể bỏ qua nhưng dữ liệu nhập vẫn phải là số nguyên 0 đến 10.","shots":[{"file":"b4-1.png","caption":"Bôi chọn D3:J12, tab Data, bấm Data Validation (khoanh đỏ).","w":1920,"h":1020},{"file":"b4-2.png","caption":"Tab Settings: Allow chọn Whole number, Data chọn between, Minimum 0, Maximum 10 (các ô khoanh đỏ), rồi bấm OK.","w":1920,"h":1020}]},{"title":"Đặt font, kẻ khung, căn chỉnh, định dạng số","forRequirement":"1","actions":["Bấm Ctrl+A (chọn cả sheet), Home > Font = Times New Roman, Size = 13.","Kẻ khung: bôi đen A1:M12 > Home > nhóm Font > Borders > All Borders.","Căn chỉnh: cột A, B căn giữa (Ctrl+E); cột C căn trái (Ctrl+L); cột D đến M căn giữa.","Định dạng số: bôi đen K3:M12 > chuột phải > Format Cells > tab Number > Category Number > Decimal places = 1 > OK. Cột D:J: Number, Decimal places = 0. Cột TT và Mã SV để General.","Chỉnh độ rộng cột: bôi đen các cột A:M > Home > Format > AutoFit Column Width, hoặc bấm đúp vào đường kẻ giữa hai tên cột."],"note":"Nên đặt font trước khi nhập công thức để khỏi phải chỉnh nhiều lần.","shots":[{"file":"b5-1.png","caption":"Bấm Ctrl+A, tab Home, ô Font chọn Times New Roman, Font Size chọn 13 (khoanh đỏ).","w":1920,"h":1020},{"file":"b5-2.png","caption":"Chọn A1:M12, bấm mũi tên cạnh nút Borders (khoanh đỏ), chọn All Borders (khoanh đỏ) để kẻ khung.","w":1920,"h":1020},{"file":"b5-3.png","caption":"Chọn K3:M12, mở hộp thoại Format Cells (mũi tên góc nhóm Number): tab Number, Category Number, Decimal places 1 (các ô khoanh đỏ), rồi bấm OK.","w":1920,"h":1020},{"file":"b5-4.png","caption":"Chọn A1:M12, Home, Format (khoanh đỏ), AutoFit Column Width (khoanh đỏ) để tự giãn cột.","w":1920,"h":1020},{"file":"b5-5.png","caption":"Bảng sau khi định dạng: font Times New Roman 13, có khung, căn chỉnh theo từng cột (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Nhập công thức cột LT (Điểm lý thuyết)","forRequirement":"3","actions":["Bấm vào ô K3, gõ: =ROUND(AVERAGE(D3:F3),1) rồi Enter.","Giải thích: AVERAGE(D3:F3) tính trung bình cộng L1, L2, L3; ROUND(...,1) làm tròn còn 1 chữ số sau dấu phẩy.","Chọn lại K3 và bấm đúp vào ô điền ở góc dưới phải ô (hoặc kéo xuống) để điền xuống K12.","Ví dụ dòng mẫu 7, 5, 3: (7+5+3)/3 = 5.0 nên K3 hiển thị 5.0."],"note":"Nếu máy báo lỗi công thức khi gõ dấu phẩy, đổi sang dấu chấm phẩy: =ROUND(AVERAGE(D3:F3);1). Tùy Regional Settings của máy (dấu phân cách đối số là , hay ;), các công thức bên dưới đều áp dụng tương tự.","shots":[{"file":"b6-1.png","caption":"Ô K3: =ROUND(AVERAGE(D3:F3),1), gõ vào thanh công thức rồi Enter (Name Box ghi K3, ô và thanh công thức khoanh đỏ).","w":1920,"h":1020},{"file":"b6-2.png","caption":"Fill xuống đến K12 bằng Fill Handle. Cột LT có kết quả một chữ số thập phân.","w":1920,"h":1020}]},{"title":"Nhập công thức cột BT (Điểm bài tập)","forRequirement":"4","actions":["Bấm vào ô L3, gõ: =ROUND((SUM(G3:J3)-MIN(G3:J3))/3,1) rồi Enter.","Giải thích: SUM(G3:J3) là tổng 4 điểm; MIN(G3:J3) là điểm nhỏ nhất; tổng trừ điểm nhỏ nhất chính là tổng của 3 điểm lớn hơn; chia 3 rồi ROUND 1 chữ số.","Cách khác dùng LARGE: =ROUND(AVERAGE(LARGE(G3:J3,{1,2,3})),1) hoặc không dùng hằng mảng: =ROUND((LARGE(G3:J3,1)+LARGE(G3:J3,2)+LARGE(G3:J3,3))/3,1).","Điền xuống L12 bằng cách bấm đúp ô điền.","Ví dụ dòng mẫu 8, 5, 8, 9: bỏ điểm 5, (8+8+9)/3 = 8.33 làm tròn 8.3."],"note":"Cách SUM trừ MIN đơn giản nhất và không phụ thuộc dấu phân cách của máy.","shots":[{"file":"b7-1.png","caption":"Ô L3: =ROUND((SUM(G3:J3)-MIN(G3:J3))/3,1), trung bình ba điểm bài tập lớn nhất.","w":1920,"h":1020},{"file":"b7-2.png","caption":"Fill xuống đến L12.","w":1920,"h":1020}]},{"title":"Nhập công thức cột QT (Điểm quá trình)","forRequirement":"5","actions":["Bấm vào ô M3, gõ: =IF(K3>7,MIN(L3+1,10),L3) rồi Enter.","Giải thích: nếu Điểm lý thuyết (K3) lớn hơn 7 thì QT = BT + 1 nhưng không vượt quá 10 (hàm MIN chặn trần 10); ngược lại QT = BT.","Điền xuống M12.","Cách viết tương đương: =MIN(10,IF(K3>7,L3+1,L3)).","Kiểm tra: SV001 có K3 = 5.0 không lớn hơn 7 nên QT = BT = 8.3. SV007 (10, 10, 6, 10, 9, 10, 9) có LT = 8.7, BT = 9.7 nên QT = MIN(10.7, 10) = 10."],"note":"'Lớn hơn 7' nghĩa là >7 chứ không phải >=7. LT đúng bằng 7.0 thì không được cộng 1.","shots":[{"file":"b8-1.png","caption":"Ô M3: =IF(K3>7,MIN(L3+1,10),L3), cộng 1 điểm nếu LT lớn hơn 7 nhưng không vượt quá 10.","w":1920,"h":1020},{"file":"b8-2.png","caption":"Fill xuống đến M12. Dòng SV007 được chặn ở mức 10.0 nhờ hàm MIN.","w":1920,"h":1020}]},{"title":"Định dạng trang in: A4, Landscape, 4 lề, căn giữa ngang","forRequirement":"2","actions":["Chọn tab Page Layout > nhóm Page Setup > bấm Dialog Launcher (mũi tên góc dưới phải) để mở hộp thoại Page Setup.","Tab Page: Orientation = Landscape; Paper size = A4.","Tab Margins: Top = 2.5, Bottom = 2.5, Left = 2.5, Right = 1.5 (cm). Tích chọn Horizontally trong mục 'Center on page'.","Bấm OK. Bấm Ctrl+P để xem trước: bảng nằm giữa trang theo chiều ngang, vừa 1 trang."],"note":"Nếu hộp thoại hiển thị inch thì gõ kèm 'cm' (ví dụ 2.5 cm). Nếu bảng tràn sang trang 2, thu hẹp độ rộng cột hoặc vào tab Page chọn Fit to 1 page wide.","shots":[{"file":"b9-1.png","caption":"Tab Page Layout, bấm mũi tên góc dưới phải nhóm Page Setup (khoanh đỏ).","w":1920,"h":1020},{"file":"b9-2.png","caption":"Tab Page: Orientation chọn Landscape, Paper size chọn A4 (khoanh đỏ).","w":1920,"h":1020},{"file":"b9-3.png","caption":"Tab Margins: Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 (cm), tick Horizontally ở mục Center on page (khoanh đỏ), rồi bấm OK.","w":1920,"h":1020}]},{"title":"Lưu bài","forRequirement":"Ghi chú chung","actions":["Bấm Ctrl+S. Kiểm tra file nằm ở D:\\ThiCC và tên là sbd_cau2.xlsx."],"note":"","shots":[{"file":"b10-1.png","caption":"Bấm Ctrl+S hoặc File, Save (khoanh đỏ) để lưu bài vào D:ThiCC với tên sbd_cau2.xlsx.","w":200,"h":600}]}],"formulas":[{"cell":"K3","formula":"=ROUND(AVERAGE(D3:F3),1)","meaning":"Điểm lý thuyết: trung bình cộng L1, L2, L3 làm tròn 1 chữ số. Điền xuống K12."},{"cell":"L3","formula":"=ROUND((SUM(G3:J3)-MIN(G3:J3))/3,1)","meaning":"Điểm bài tập: trung bình cộng của 3 điểm lớn hơn trong B1 đến B4 (tổng trừ điểm nhỏ nhất, chia 3), làm tròn 1 chữ số. Điền xuống L12."},{"cell":"L3","formula":"=ROUND(AVERAGE(LARGE(G3:J3,{1,2,3})),1)","meaning":"Cách thay thế cho BT: LARGE lấy lần lượt điểm lớn nhất, lớn thứ hai, lớn thứ ba rồi AVERAGE. Nếu máy lỗi thì dùng cách SUM trừ MIN ở trên."},{"cell":"M3","formula":"=IF(K3>7,MIN(L3+1,10),L3)","meaning":"Điểm quá trình: nếu LT lớn hơn 7 thì BT cộng 1 nhưng tối đa 10; ngược lại bằng BT. Điền xuống M12."}],"result":"Bảng gồm 2 dòng tiêu đề trộn ô và 10 dòng sinh viên, 13 cột A đến M, có khung đầy đủ, font Times New Roman 13. Cột LT, BT, QT hiển thị 1 chữ số thập phân. QT không vượt quá 10 và chỉ cộng 1 khi LT lớn hơn 7. Với dòng mẫu SV001 (7, 5, 3, 8, 5, 8, 9) kết quả là LT = 5.0, BT = 8.3, QT = 8.3. Print Preview cho thấy khổ A4 nằm ngang, bảng nằm giữa trang theo chiều ngang. Tự kiểm tra: bấm vào từng ô K3, L3, M3 xem thanh công thức; đổi thử một điểm xem kết quả có tự cập nhật; kiểm tra không có ô nào hiển thị #### (cột hẹp) hoặc #NAME? (sai tên hàm hay dấu phân cách)."},"checklist":["File lưu tại D:\\ThiCC với tên sbd_cau2.xlsx","Có đủ 10 sinh viên, các cột TT, Mã SV, Họ tên, L1, L2, L3, B1, B2, B3, B4, LT, BT, QT","Điểm L1 đến B4 là số nguyên từ 0 đến 10","Bảng có kẻ khung, căn chỉnh hợp lý, kiểu dữ liệu phù hợp","Toàn bộ font Times New Roman 13pt","Page Setup: A4, Landscape, Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 cm","Đã tích Center on page > Horizontally","Cột LT dùng công thức trung bình L1, L2, L3, làm tròn 1 chữ số","Cột BT dùng công thức trung bình 3 điểm lớn nhất trong B1 đến B4, làm tròn 1 chữ số","Cột QT: LT > 7 thì BT + 1, ngược lại BT, tối đa 10","Các công thức đã điền hết cho cả 10 dòng, không có ô lỗi"],"commonMistakes":["Gõ kết quả bằng tay thay vì dùng công thức.","Dùng AVERAGE(G3:J3) cho cả 4 điểm thay vì chỉ 3 điểm lớn nhất.","Dùng >=7 thay vì >7 ở điều kiện cộng 1 điểm.","Quên chặn trần 10 cho QT (ví dụ BT = 9.7 cộng 1 ra 10.7).","Chỉ giảm số chữ số thập phân hiển thị mà không dùng ROUND, nên giá trị thực còn nhiều số lẻ (LT 7.03 hiển thị 7.0 nhưng vẫn lớn hơn 7 khi so sánh).","Dùng sai dấu phân cách đối số (, và ;) theo cấu hình máy nên báo lỗi công thức.","Quên chọn A4, quên Landscape hoặc quên tích Horizontally.","Tham chiếu ô sai khi điền xuống (vô tình dùng $ khóa dòng).","Chỉ đổi font ở vùng có dữ liệu mà bỏ sót ô tiêu đề."],"uncertain":["Ảnh 2.1 chụp hơi nghiêng; ở yêu cầu 1 danh sách cột in là 'L2 (lần 1), L3 (lần 2), L3 (lần 3)', rất có thể là lỗi in; đã chép thành 'L1 (lần 1), L2 (lần 2), L3 (lần 3)' cho khớp với tiêu đề bảng.","Dữ liệu 10 sinh viên là 'giả định' do thí sinh tự nhập; chỉ dòng SV001 (1, SV001, Nguyễn Văn A, 7, 5, 3, 8, 5, 8, 9) có trong đề. Các dòng còn lại lấy từ file mẫu 234_Câu 2.xlsx làm ví dụ.","Ảnh 2.2 là trang 2 của đề; phía trên có vài chữ của trang khác lọt vào ảnh ('hàng nghìn', 'bài thuy...', 'các nội') không thuộc yêu cầu nào.","File mẫu có công thức QT = IF(K<7,L,IF(AND(K>7,L<9),L+1,10)), lệch so với đề tại K = 7 đúng (mẫu cho QT = 10) và L >= 9 luôn cho 10 (cũng cần chú ý). Đã làm theo đề: LT > 7 thì BT + 1 (tối đa 10), còn lại bằng BT.","File mẫu dùng LARGE với hằng mảng; hướng dẫn dùng SUM trừ MIN cho đơn giản và không phụ thuộc cấu hình máy."]},{"no":3,"app":"powerpoint","title":"Câu 3. Tạo các trang trình chiếu (Microsoft PowerPoint)","statement":{"intro":"Sử dụng phần mềm Microsoft PowerPoint thiết kế slides trình chiếu phục vụ cho bài thuyết trình giới thiệu về Các địa danh của Việt Nam (05 slides) trong đó có các nội dung sau. Lưu ý: Trên slides trình chiếu không chứa nội dung liên quan thông tin cá nhân của thí sinh.","requirements":["Nội dung các trang. Trang 1: Giới thiệu, Tên bài thuyết trình \"Địa danh ở Việt Nam\". Trang 2: Nội dung trình bày: tên 3 địa danh được trình bày ở các trang tiếp theo. Trang 3, 4, 5: Mỗi trang trình bày về một địa danh: nội dung trình bày tùy vào hiểu biết của từng thí sinh, tuy nhiên mỗi địa danh phải đảm bảo 3 nội dung và có hình ảnh đi kèm (nội dung gợi ý: tên địa danh, vị trí địa lý, đặc điểm, phương tiện đi lại, ....).","1) Trình bày và căn chỉnh 5 slide theo yêu cầu nội dung như trên. Đánh số trang tự động cho các slide (trừ slide đầu tiên).","2) Trong Master Slide, điều chỉnh tất cả font chữ về Arial, nội dung căn chỉnh 2 bên.","3) Tạo mới và sử dụng ít nhất 02 layout cho bài trình chiếu.","4) Sử dụng ít nhất 02 hiệu ứng hoạt hình khác nhau (Animation).","5) Sử dụng ít nhất 02 hiệu ứng chuyển slide khác nhau (Transition)."],"material":[{"kind":"text","caption":"Nội dung gợi ý cho 5 slide (thí sinh có thể chọn địa danh khác; không ghi tên, số báo danh hay thông tin cá nhân)","lines":["Slide 1: Địa danh ở Việt Nam","Slide 2: Nội dung trình bày: Vịnh Hạ Long; Hang Sơn Đoòng; Phố cổ Hội An","Slide 3 - Vịnh Hạ Long: Vị trí: tỉnh Quảng Ninh. Đặc điểm: được UNESCO công nhận là di sản thiên nhiên thế giới, là một trong 7 kỳ quan thiên nhiên mới của thế giới. Phương tiện đi lại: ô tô theo cao tốc, tàu thuyền, du thuyền. Kèm 1 hình ảnh.","Slide 4 - Hang Sơn Đoòng: Vị trí: tỉnh Quảng Bình, thuộc Vườn quốc gia Phong Nha - Kẻ Bàng. Đặc điểm: hang động tự nhiên lớn nhất thế giới, vẻ hoang sơ, bí ẩn. Phương tiện đi lại: máy bay đến Đồng Hới, ô tô, đi bộ xuyên rừng cùng đoàn thám hiểm. Kèm 1 hình ảnh.","Slide 5 - Phố cổ Hội An: Vị trí: tỉnh Quảng Nam (Hội An). Đặc điểm: di sản văn hóa thế giới, nhà cổ, phố đèn lồng. Phương tiện đi lại: máy bay đến Đà Nẵng rồi đi ô tô, xe đạp, đi bộ trong phố cổ. Kèm 1 hình ảnh."]}]},"solution":{"summary":"Sửa Slide Master (font Arial, căn đều hai bên, có khung số trang), tạo ít nhất 2 layout riêng bằng Insert Layout, dựng 5 slide dùng các layout đó, thêm hình, đánh số trang trừ slide 1, rồi thêm tối thiểu 2 Animation khác nhau và 2 Transition khác nhau.","steps":[{"title":"Tạo file và lưu tên đúng quy định","forRequirement":"Ghi chú chung","actions":["Mở PowerPoint, chọn Blank Presentation. Bấm Ctrl+S, chọn D:\\ThiCC, đặt tên sbd_cau3.pptx (sbd là số báo danh), bấm Save.","Lưu ý: nội dung slide không được ghi họ tên, số báo danh hoặc thông tin cá nhân."],"note":"","shots":[{"file":"b1-1.png","caption":"Mở PowerPoint, chọn Blank Presentation. Tab File (khoanh đỏ) mở menu lưu file.","w":1920,"h":1020},{"file":"b1-2.png","caption":"File, Save As (khoanh đỏ) hoặc Ctrl+S. Chọn thư mục D:ThiCC, đặt tên sbd_cau3.pptx.","w":200,"h":600}]},{"title":"Chỉnh Slide Master: font Arial cho tất cả","forRequirement":"2","actions":["Tab View > nhóm Master Views > Slide Master. Ngăn trái hiện slide cha lớn nhất (Office Theme Slide Master) và các layout con.","Cách chắc chắn nhất: tab Slide Master > nhóm Background > Fonts > Customize Fonts. Đặt Heading font = Arial và Body font = Arial, đặt Name là Arial, bấm Save. Mọi tiêu đề và nội dung dùng Arial.","Kiểm tra: chọn slide cha (slide lớn nhất ở trên cùng), bấm vào khung 'Click to edit Master title style' xem Home hiển thị Arial; làm tương tự với khung 'Click to edit Master text styles'. Nếu chưa phải Arial, bôi đen khung và chọn Arial trong Home > Font.","Chọn các khung Date, Footer, Slide Number ở slide cha và đặt font Arial."],"note":"Sửa ở slide cha thì tất cả layout con kế thừa; sửa riêng một layout thì chỉ layout đó đổi.","shots":[{"file":"b2-1.png","caption":"Tab View, bấm Slide Master (khoanh đỏ) để vào chế độ chỉnh slide mẫu.","w":1920,"h":1020},{"file":"b2-2.png","caption":"Tab Slide Master, bấm Fonts rồi chọn Customize Fonts... (khoanh đỏ).","w":1920,"h":1020},{"file":"b2-3.png","caption":"Hộp thoại Create New Theme Fonts: Heading font và Body font đều chọn Arial, đặt Name rồi bấm Save (các ô khoanh đỏ).","w":1920,"h":1020}]},{"title":"Căn chỉnh nội dung hai bên (Justify) trong Master","forRequirement":"2","actions":["Vẫn ở chế độ Slide Master, trên slide cha bấm vào khung 'Click to edit Master text styles'.","Bấm vào viền khung để chọn cả khung, rồi bấm Justify (Ctrl+J) trong Home > nhóm Paragraph. Mọi cấp bullet đều được căn đều hai bên.","Làm tương tự với các khung Text ở layout bạn tạo ở bước sau.","Khung tiêu đề (Title) có thể giữ căn giữa hoặc trái; yêu cầu chỉ nói 'nội dung căn chỉnh 2 bên'."],"note":"Justify chỉ nhìn rõ khi đoạn văn dài hơn một dòng.","shots":[{"file":"b3-1.png","caption":"Chọn slide master lớn nhất ở đầu cột trái, bấm vào khung nội dung rồi tab Home, bấm Justify (khoanh đỏ) để căn đều hai bên.","w":1920,"h":1020}]},{"title":"Kiểm tra khung số trang trên Master","forRequirement":"1","actions":["Trong Slide Master, kiểm tra khung Slide Number (hình <#>) còn tồn tại ở slide cha và ở các layout. Nếu bị xóa, chọn layout đó rồi tab Slide Master > nhóm Master Layout > tích Slide Number.","Có thể chỉnh vị trí, cỡ chữ, màu số trang ở slide cha cho dễ nhìn."],"note":"Số trang lấy từ khung Slide Number của layout đang dùng, nên layout tự tạo cũng phải có khung này.","shots":[{"file":"b4-1.png","caption":"Khung số trang (hình <#>, khoanh đỏ) vẫn còn trên slide master. Nếu mất, chọn layout rồi tick Slide Number trong nhóm Master Layout.","w":1920,"h":1020}]},{"title":"Tạo mới ít nhất 02 layout","forRequirement":"3","actions":["Ở chế độ Slide Master, tab Slide Master > nhóm Edit Master > Insert Layout. Một layout mới xuất hiện ở cuối danh sách.","Layout 1 (dùng cho slide địa danh): nhóm Master Layout > Insert Placeholder > Picture, kéo một khung hình; Insert Placeholder > Text, kéo một khung chữ. Kéo thả bố trí: tiêu đề ở trên, hình bên trái, nội dung bên phải. Chuột phải layout trong ngăn trái > Rename Layout > đặt tên (ví dụ DiaDanh).","Layout 2 (dùng cho slide 2): Insert Layout lần nữa, giữ Title và thêm 1 khung Text lớn. Rename Layout đặt tên khác (ví dụ NoiDung).","Cách nhanh: chuột phải layout 'Title and Content' > Duplicate Layout rồi sửa lại bố cục.","Bấm Close Master View khi xong."],"note":"Đề yêu cầu 'tạo mới' nên không chỉ dùng layout có sẵn; các layout tạo ra phải được dùng cho slide thật sự.","shots":[{"file":"b5-1.png","caption":"Trong Slide Master, chọn một layout rồi bấm Insert Layout (khoanh đỏ) để thêm layout mới.","w":1920,"h":1020},{"file":"b5-2.png","caption":"Bấm Rename, đặt tên layout là DiaDanh rồi bấm Rename (các ô khoanh đỏ).","w":1920,"h":1020},{"file":"b5-3.png","caption":"Insert Placeholder: chọn loại khung cần thêm như Text hoặc Picture (khoanh đỏ), kéo khung vào vị trí mong muốn.","w":1920,"h":1020},{"file":"b5-4.png","caption":"Layout DiaDanh (khoanh đỏ): tiêu đề ở trên, khung hình bên trái, khung chữ bên phải.","w":1920,"h":1020},{"file":"b5-5.png","caption":"Layout thứ hai NoiDung (khoanh đỏ): tiêu đề ở trên và một khung chữ lớn bên dưới.","w":1920,"h":1020},{"file":"b5-6.png","caption":"Bấm Close Master View (khoanh đỏ) để quay về chế độ soạn slide.","w":1920,"h":1020}]},{"title":"Dựng 5 slide và áp dụng layout","forRequirement":"1, 3","actions":["Slide 1: tab Home > Layout > chọn Title Slide. Title gõ 'Địa danh ở Việt Nam'. Subtitle gõ 'Giới thiệu' hoặc xóa khung trống.","Slide 2: Home > New Slide, Layout chọn layout NoiDung vừa tạo. Title gõ 'Nội dung trình bày'. Nội dung 3 dòng: Vịnh Hạ Long, Hang Sơn Đoòng, Phố cổ Hội An (cùng thứ tự với slide 3, 4, 5).","Slide 3, 4, 5: New Slide, Layout chọn DiaDanh. Title là tên địa danh, khung chữ gõ vị trí địa lý, đặc điểm, phương tiện đi lại (ít nhất 3 nội dung). Chèn hình: bấm biểu tượng Picture trong khung hình để chọn ảnh từ máy (hoặc Insert > Pictures / Online Pictures).","Căn chỉnh hình, chữ cân đối giữa các slide (Format > Align). Kiểm tra chữ không tràn khung và không có thông tin cá nhân."],"note":"Nếu đề thi không cung cấp ảnh thì dùng ảnh có sẵn trong máy hoặc Insert > Online Pictures.","shots":[{"file":"b6-1.png","caption":"Tab Home, bấm Layout (khoanh đỏ): hai layout vừa tạo là DiaDanh và NoiDung (khoanh đỏ) nằm trong danh sách.","w":1920,"h":1020},{"file":"b6-2.png","caption":"Slide 1 dùng layout Title Slide: gõ tiêu đề Địa danh ở Việt Nam và phụ đề Giới thiệu (các khung khoanh đỏ).","w":1920,"h":1020},{"file":"b6-3.png","caption":"Slide 2 dùng layout NoiDung: tiêu đề Nội dung trình bày và 3 dòng tên 3 địa danh theo thứ tự trình bày (các khung khoanh đỏ).","w":1920,"h":1020},{"file":"b6-4.png","caption":"Slide 3 dùng layout DiaDanh: tên địa danh, hình ảnh và 3 nội dung vị trí, đặc điểm, phương tiện đi lại (các khung khoanh đỏ).","w":1920,"h":1020},{"file":"b6-5.png","caption":"Cột trái hiện đủ 5 slide: slide 1 giới thiệu, slide 2 nội dung, slide 3 đến 5 mỗi slide một địa danh có hình (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Đánh số trang tự động, trừ slide đầu","forRequirement":"1","actions":["Tab Insert > nhóm Text > Slide Number (hoặc Header & Footer).","Trong hộp thoại Header and Footer, tab Slide: tích 'Slide number' và tích 'Don't show on title slide'.","Bấm Apply to All. Slide 1 (Title Slide) không có số, slide 2 hiển thị 2, slide 3 hiển thị 3, ...","Kiểm tra: duyệt qua từng slide, chắc chắn số trang xuất hiện ở slide 2 đến 5."],"note":"Nếu slide dùng layout tự tạo không hiện số: mở Slide Master, chọn layout đó, tích Slide Number trong Master Layout, rồi làm lại Apply to All.","shots":[{"file":"b7-1.png","caption":"Chọn slide 2, tab Insert, bấm Slide Number (khoanh đỏ).","w":1920,"h":1020},{"file":"b7-2.png","caption":"Hộp thoại Header and Footer, tab Slide: tick Slide number và Don't show on title slide, rồi bấm Apply to All (các mục khoanh đỏ).","w":1920,"h":1020},{"file":"b7-3.png","caption":"Số trang xuất hiện tự động ở góc dưới phải (khoanh đỏ) từ slide 2; slide 1 là Title Slide nên không có số.","w":1920,"h":1020}]},{"title":"Thêm ít nhất 02 hiệu ứng hoạt hình khác nhau (Animation)","forRequirement":"4","actions":["Slide 3: bấm vào khung tiêu đề, tab Animations > chọn Fade (nhóm Entrance).","Bấm khung nội dung, chọn Fly In (Effect Options: From Left).","Bấm vào hình ảnh, chọn Zoom hoặc Wipe.","Có thể thêm hiệu ứng cho slide 4 và 5. Đảm bảo ít nhất hai kiểu khác nhau (ví dụ Fade và Fly In).","Mở Animation Pane (Animations > Advanced Animation > Animation Pane) kiểm tra danh sách hiệu ứng, thứ tự, Start (On Click hoặc After Previous), Duration.","Bấm Preview hoặc F5 để xem thử."],"note":"Hai hiệu ứng khác nhau nghĩa là hai kiểu khác nhau (Fade khác Fly In), không phải hai lần cùng một kiểu.","shots":[{"file":"b8-1.png","caption":"Slide 3: chọn khung tiêu đề, tab Animations, chọn hiệu ứng Fade (khoanh đỏ).","w":1920,"h":1020},{"file":"b8-2.png","caption":"Chọn khung nội dung, chọn hiệu ứng Fly In (khoanh đỏ).","w":1920,"h":1020},{"file":"b8-3.png","caption":"Chọn hình ảnh, bấm mũi tên mở rộng thư viện rồi chọn Zoom (khoanh đỏ).","w":1920,"h":1020},{"file":"b8-4.png","caption":"Bấm Animation Pane (khoanh đỏ) để xem danh sách 3 hiệu ứng, thứ tự và cách bắt đầu (vùng khoanh đỏ bên phải).","w":1920,"h":1020}]},{"title":"Thêm ít nhất 02 hiệu ứng chuyển slide khác nhau (Transition)","forRequirement":"5","actions":["Chọn slide 1 trong ngăn trái. Tab Transitions > nhóm Transition to This Slide > chọn Fade.","Chọn slide 2 và slide 3, chọn Push (hoặc Wipe, Split).","Chọn slide 4 và 5, áp dụng một trong hai kiểu trên hoặc một kiểu khác.","Không bấm Apply To All vì sẽ làm mọi slide giống nhau. Bấm Preview xem thử."],"note":"Phải có ít nhất 2 kiểu Transition khác nhau trên các slide khác nhau.","shots":[{"file":"b9-1.png","caption":"Chọn slide 1, tab Transitions, chọn Fade (khoanh đỏ).","w":1920,"h":1020},{"file":"b9-2.png","caption":"Chọn slide 2 và slide 3, chọn Push (khoanh đỏ).","w":1920,"h":1020},{"file":"b9-3.png","caption":"Chọn slide 4 và slide 5, chọn Wipe (khoanh đỏ). Không bấm Apply To All để các slide có hiệu ứng khác nhau.","w":1920,"h":1020},{"file":"b9-4.png","caption":"Các slide đã gắn hiệu ứng có biểu tượng ngôi sao nhỏ cạnh số slide ở cột trái (vùng khoanh đỏ).","w":1920,"h":1020}]},{"title":"Kiểm tra cuối cùng và lưu","forRequirement":"1, 2, 3, 4, 5","actions":["Bấm F5 trình chiếu từ đầu: kiểm tra số trang (trừ slide 1), hiệu ứng, chuyển slide, hình ảnh.","Mở View > Slide Master một lần nữa xem font Arial và Justify đã áp dụng.","Kiểm tra lại không có thông tin cá nhân trên slide.","Bấm Ctrl+S để lưu sbd_cau3.pptx trong D:\\ThiCC."],"note":"","shots":[{"file":"b10-1.png","caption":"Tab Slide Show, bấm From Beginning (khoanh đỏ) hoặc phím F5 để xem cả bài từ đầu.","w":1920,"h":1020},{"file":"b10-2.png","caption":"Chế độ Slide Sorter cho thấy đủ 5 slide: slide 1 không có số trang, các slide còn lại có số trang và biểu tượng hiệu ứng.","w":1920,"h":1020}]}],"formulas":[],"result":"Bài trình chiếu 5 slide: slide 1 tiêu đề 'Địa danh ở Việt Nam' (không có số trang); slide 2 liệt kê 3 địa danh và hiện số 2; slide 3, 4, 5 mỗi slide một địa danh có ít nhất 3 nội dung (vị trí, đặc điểm, phương tiện đi lại) kèm hình ảnh và số trang 3, 4, 5. Toàn bộ chữ Arial, nội dung căn đều hai bên theo Master. Có ít nhất 2 layout tự tạo được dùng. Có ít nhất 2 Animation khác kiểu và 2 Transition khác kiểu. Tự kiểm tra bằng F5, Animation Pane và Slide Master."},"checklist":["File lưu tại D:\\ThiCC với tên sbd_cau3.pptx","Bài có đúng 5 slide","Slide 1: tên bài 'Địa danh ở Việt Nam'","Slide 2: nêu tên 3 địa danh trình bày ở các trang sau","Slide 3, 4, 5: mỗi slide một địa danh, có ít nhất 3 nội dung và có hình ảnh","Số trang tự động hiển thị ở slide 2 đến 5, slide 1 không có số","Trong Slide Master tất cả font là Arial","Nội dung trong Master căn chỉnh hai bên (Justify)","Đã tạo ít nhất 2 layout mới và đã sử dụng chúng trong bài","Có ít nhất 2 Animation khác nhau","Có ít nhất 2 Transition khác nhau","Không có thông tin cá nhân của thí sinh trên slide"],"commonMistakes":["Đổi font từng slide thay vì sửa trong Slide Master (hoặc Customize Fonts).","Dùng Apply to All trong Transition nên tất cả slide cùng một kiểu, chỉ có 1 hiệu ứng.","Chỉ dùng layout có sẵn mà không tạo layout mới.","Để số trang hiện cả ở slide đầu (quên tích Don't show on title slide).","Tạo layout mới nhưng quên khung Slide Number nên slide dùng layout đó không có số trang.","Dùng cùng một kiểu hiệu ứng nhiều lần rồi coi là 2 hiệu ứng.","Nhập tên, số báo danh lên slide.","Ảnh chèn không rõ địa danh hoặc tràn khung.","Slide 2 liệt kê địa danh không khớp thứ tự với slide 3, 4, 5."],"uncertain":["Ảnh 2.2 (trang 2 của đề) đọc khá rõ; ở mép trên và mép phải có vài chữ của trang khác lọt vào ảnh nên không dùng.","Nội dung gợi ý của các địa danh là do người soạn hướng dẫn viết (đề cho phép tùy hiểu biết thí sinh).","File mẫu tuan02.pptx chưa có Animation hoặc Transition nào (kiểm tra qua python-pptx) và dùng layout có sẵn 'Content with Caption'; đã làm theo đề (cần ít nhất 2 layout tạo mới, 2 Animation, 2 Transition).","File mẫu có lỗi chính tả ('Sơn Đoongf', 'chử tịch'); không dùng.","Thứ tự 3 địa danh ở slide 2 của file mẫu không trùng với slide 3, 4, 5; hướng dẫn yêu cầu viết cùng thứ tự.","Đề không nêu rõ cách 'căn chỉnh 2 bên'; đã hiểu là Justify (Ctrl+J)."]}]},{"id":3,"title":"Đề thực hành số 3","source":"de co ban 3","timeLimitMinutes":60,"generalNotes":["Đợt thi B190316002, thời gian làm bài 60 phút.","Đề thi gồm 2 trang; không được sử dụng tài liệu, USB và các thiết bị lưu trữ khác.","Các file bài làm để trong thư mục E:\\ThiCC, cách đặt tên file: Câu 1: xyz_cau1.docx; Câu 2: xyz_cau2.xlsx; Câu 3: xyz_cau3.pptx. Trong đó xyz là số báo danh của thí sinh.","Lưu ý: ghi chú tên file ghi Câu 2 là xlsx và Câu 3 là pptx, nhưng nội dung đề lại ghi Câu 2 là PowerPoint và Câu 3 là Excel. Khi thi thật nên hỏi giám thị để chắc chắn."],"tasks":[{"no":1,"app":"word","title":"Câu 1. Soạn thảo văn bản (Microsoft Word)","statement":{"intro":"Sử dụng phần mềm Microsoft Word soạn thảo nội dung tài liệu trên trang 2 với các yêu cầu sau:","requirements":["1) Soạn và định dạng đầy đủ nội dung văn bản như trang 2.","2) Định dạng trang: Cỡ giấy: A4; Chiều: Portrait; Lề trên (Top): 2.5 cm, Lề dưới (Bottom): 2 cm, Lề trái (Left): 3.5 cm, Lề phải (Right): 1.5 cm; Font: Times New Roman, cỡ 13.","3) Sử dụng Heading 1 để định dạng cho các Mục A, B. Sử dụng Heading 2 để định dạng cho các mục 1 và 2 trong mục lớn A, B.","4) Sử dụng công cụ insert equation để thêm công thức tính chỉ số BMI.","5) Sử dụng cross-reference để tạo tham chiếu đến tài liệu tham khảo."],"material":[{"kind":"text","caption":"Tiêu đề và Mục A (Giới thiệu)","lines":["BMI - CHỈ SỐ KHỐI CƠ THỂ","A. Giới thiệu","Chỉ số khối cơ thể - thường được biết đến với chữ viết tắt BMI theo tên tiếng Anh Body Mass Index - được dùng để đánh giá mức độ gầy hay béo của một người. Chỉ số này do nhà bác học người Bỉ Adolphe Quetelet đưa ra năm 1832 (xem [1]).","Chỉ số khối cơ thể của một người tính bằng cân nặng của người đó (kg) chia cho bình phương chiều cao (đo theo mét hoặc cm). Có thể tính theo công thức định nghĩa hoặc cho theo những bảng tiêu chuẩn (xem [2]).","1) Cách tính","Gọi W là khối lượng của một người (tính bằng kg) và H là chiều cao của người đó (tính bằng m), chỉ số khối cơ thể được tính theo công thức (xem [3]):","[Công thức: BMI(kg/m2) = W / H2, phân số W trên H bình phương, căn giữa dòng]","2) Phân loại theo WHO","Theo WHO, người lớn có BMI trong phạm vi từ 18,50 đến 24,99 là người bình thường. Dưới 18,5 là gầy, từ 25 đến 29,99 là người béo và trên 30 là béo phì.","[Bảng phân loại WHO, xem bảng bên dưới]"]},{"kind":"table","caption":"Bảng phân loại theo WHO (hàng 1: ô 'Phân loại' gộp 2 hàng, 'BMI (kg/m2)' gộp 2 cột, 'BMI nguyên tố' gộp 2 cột)","rows":[["Phân loại","BMI (kg/m2)","","BMI nguyên tố",""],["","Từ","Đến","Từ","Đến"],["Thiếu cân","","18,5","","0,74"],["Bình thường","18,5","25,0","0,74","1,00"],["Thừa cân","25,0","30,0","1,00","1,20"],["Béo phì","30,0","","1,20",""]]},{"kind":"text","caption":"Mục B (Phân loại chung) và Tài liệu tham khảo","lines":["B. Phân loại chung người lớn hơn 20 tuổi","1) Kiểu 1","BMI < 18: người gầy","BMI = 18,5 - 25: người bình thường","BMI = 25 - 30: người béo phì độ I","2) Kiểu 2 (với Nam)","BMI < 20: người dưới cân","20 <= BMI < 25: người bình thường","25 <= BMI < 30: người quá cân","Tài liệu tham khảo","[1] Eknoyan, Garabed (2007). \"Adolphe Quetelet (1796-1874) - the average man and indices of obesity\".","[2] Ví dụ Bảng chỉ số khối cơ thể của Viện Sức khỏe quốc gia Hoa Kỳ.","[3] Beyond BMI: Why doctors won't stop using an outdated measure for obesity, by Jeremy Singer -Vine."]}]},"solution":{"summary":"Đặt lề giấy A4 và font Times New Roman 13 trước, gõ đủ nội dung rồi áp Heading 1 cho A, B và Heading 2 cho các mục 1, 2 trong mỗi mục lớn. Công thức BMI chèn bằng Insert > Equation với phân số xếp chồng, danh mục tài liệu tham khảo đánh số tự động [1] [2] [3] để Insert > Cross-reference chèn được các tham chiếu '(xem [1])'.","steps":[{"title":"Bước 0. Tạo file và lưu đúng tên","forRequirement":"Chung","actions":["Mở Microsoft Word, chọn Blank document.","Nhấn Ctrl+S, chọn thư mục E:\\ThiCC, đặt tên xyz_cau1.docx (xyz là số báo danh của bạn), bấm Save.","Nhớ nhấn Ctrl+S sau mỗi vài bước để không mất bài."],"note":"Trên máy thi, đề yêu cầu lưu trong thư mục E:\\ThiCC. Khi tự ôn tập, bạn lưu ở thư mục bất kỳ."},{"title":"Bước 1. Định dạng trang (làm trước khi gõ để khỏi lệch trang)","forRequirement":"2","actions":["Tab Page Layout (Bố cục) > nhóm Page Setup > Margins > Custom Margins... (hoặc bấm mũi tên nhỏ ở góc dưới bên phải nhóm Page Setup).","Trong hộp thoại Page Setup, tab Margins: nhập Top = 2.5 cm, Bottom = 2 cm, Left = 3.5 cm, Right = 1.5 cm. Mục Orientation chọn Portrait.","Sang tab Paper: mục Paper size chọn A4 (21 cm x 29.7 cm).","Mục Apply to chọn Whole document, bấm OK.","Nếu Word hiện bảng hỏi về lề nằm ngoài vùng in thì chọn Ignore."],"note":"Nếu máy đang dùng đơn vị Inch, vào File > Options > Advanced > Display > Show measurements in units of > Centimeters để nhập được cm."},{"title":"Bước 2. Đặt font Times New Roman cỡ 13 cho toàn bộ văn bản","forRequirement":"2","actions":["Tab Home > nhóm Styles, bấm chuột phải vào kiểu Normal > Modify...","Trong hộp Modify Style, mục Formatting chọn font Times New Roman, cỡ 13. Bấm OK.","Heading 1 và Heading 2 có font riêng (không theo Normal) nên sẽ chỉnh ở Bước 4."],"note":"Cách thay thế: gõ xong toàn bộ nội dung, nhấn Ctrl+A rồi chọn Times New Roman và cỡ 13 trong nhóm Font. Làm cách này thì phải chọn lại Ctrl+A và đặt lại font sau khi áp Heading."},{"title":"Bước 3. Soạn nội dung văn bản","forRequirement":"1","actions":["Gõ dòng tiêu đề 'BMI - CHỈ SỐ KHỐI CƠ THỂ' rồi nhấn Ctrl+E để căn giữa, nhấn Ctrl+B để in đậm.","Gõ lần lượt các dòng của mục A: 'A. Giới thiệu', hai đoạn văn, '1) Cách tính', đoạn 'Gọi W...' (chừa một dòng trống cho công thức), '2) Phân loại theo WHO', đoạn 'Theo WHO...' (chừa chỗ cho bảng). Gõ đúng như đề, kể cả dấu phẩy thập phân (18,50 ; 24,99).","Tại các chỗ 'xem [1]', 'xem [2]', 'xem [3]' tạm gõ '(xem )'; phần số tham chiếu sẽ chèn bằng cross-reference ở Bước 8 (đừng gõ tay [1], [2], [3] ở chỗ này).","Gõ tiếp mục B: 'B. Phân loại chung người lớn hơn 20 tuổi', '1) Kiểu 1' kèm 3 dòng BMI, '2) Kiểu 2 (với Nam)' kèm 3 dòng BMI, rồi 'Tài liệu tham khảo' và 3 mục tài liệu (chưa gõ [1], [2], [3], sẽ đánh số tự động ở Bước 7).","Ký hiệu '<=' gõ hai ký tự < và =. Nếu Word tự đổi thành ký tự khác thì nhấn Ctrl+Z ngay sau khi nó đổi.","Gõ tiếng Việt có dấu bằng Unikey (Telex hoặc VNI), bảng mã Unicode."],"note":"Đề yêu cầu soạn thảo đầy đủ nội dung như trang 2, nên phải đủ cả công thức, bảng, các dấu đầu dòng và danh mục tài liệu tham khảo."},{"title":"Bước 4. Áp dụng Heading 1 và Heading 2","forRequirement":"3","actions":["Đặt con trỏ vào dòng 'A. Giới thiệu', tab Home > nhóm Styles > chọn Heading 1. Làm tương tự với dòng 'B. Phân loại chung người lớn hơn 20 tuổi'.","Đặt con trỏ vào dòng '1) Cách tính' > chọn Heading 2. Làm tương tự với '2) Phân loại theo WHO' (thuộc mục A), '1) Kiểu 1' và '2) Kiểu 2 (với Nam)' (thuộc mục B).","Không áp Heading cho các đoạn văn thường, dòng tiêu đề lớn đầu văn bản và dòng 'Tài liệu tham khảo' (đề chỉ yêu cầu H1 cho mục A, B và H2 cho các mục 1, 2).","Chỉnh style cho đúng font: bấm chuột phải vào Heading 1 trong nhóm Styles > Modify... > chọn font Times New Roman, cỡ 13, Bold, màu Automatic (đen). Bấm OK.","Làm tương tự với Heading 2: Times New Roman, cỡ 13, Bold + Italic, màu đen.","Các số '1)', '2)' gõ tay như đề, đây là cách ít lỗi nhất (nếu muốn tự động thì dùng Home > Multilevel List, nhưng không bắt buộc)."],"note":"Kiểm tra bằng View > tick Navigation Pane: ô Headings phải hiện 2 mục cấp 1 (A, B) và mỗi mục có 2 mục con cấp 2 thụt vào bên dưới."},{"title":"Bước 5. Chèn công thức BMI bằng Insert Equation","forRequirement":"4","actions":["Đặt con trỏ vào dòng trống sau đoạn 'Gọi W là khối lượng...'.","Tab Insert > nhóm Symbols > Equation (hoặc bấm Alt+=). Một khung công thức xuất hiện, tab Design hiện ra.","Gõ: BMI(kg/m^2 rồi nhấn phím Space (Word đổi ^2 thành số mũ), sau đó gõ dấu ) rồi gõ =.","Tab Design > nhóm Structures > Fraction > chọn Stacked Fraction (phân số xếp chồng). Ô trên gõ W, nhấn mũi tên xuống để sang ô dưới, gõ H^2 rồi nhấn Space để thành H bình phương.","Nhấn mũi tên phải để thoát khỏi phân số. Công thức hoàn chỉnh: BMI(kg/m2) = W / H2.","Bấm ra ngoài khung công thức, công thức tự căn giữa dòng riêng."],"note":"Không dùng ảnh chụp hay gõ chữ 'W/H^2' thông thường; đề yêu cầu dùng Insert Equation nên khi click vào công thức phải thấy khung Equation."},{"title":"Bước 6. Tạo bảng phân loại theo WHO","forRequirement":"1, 2","actions":["Đặt con trỏ vào dòng trống sau đoạn 'Theo WHO...'. Tab Insert > Table > Insert Table..., nhập Number of columns = 5, Number of rows = 6, bấm OK.","Gộp ô: bôi đen hai ô dọc đầu tiên của cột 1 (hàng 1 và 2), chuột phải > Merge Cells. Gõ 'Phân loại'.","Gộp 2 ô cột 2-3 của hàng 1 thành 1 ô, gõ 'BMI (kg/m2)', bôi đen số 2 và nhấn Ctrl+Shift+= để thành số mũ.","Gộp 2 ô cột 4-5 của hàng 1 thành 1 ô, gõ 'BMI nguyên tố'.","Hàng 2: gõ 'Từ', 'Đến' dưới BMI và 'Từ', 'Đến' dưới BMI nguyên tố.","Nhập 4 hàng dữ liệu: Thiếu cân (ô Từ trống, 18,5, ô Từ nguyên tố trống, 0,74); Bình thường (18,5; 25,0; 0,74; 1,00); Thừa cân (25,0; 30,0; 1,00; 1,20); Béo phì (30,0; để trống; 1,20; để trống).","Bôi đen cả bảng: tab Layout > nhóm Alignment > Align Center (căn giữa cả ngang và dọc). Hai hàng tiêu đề tô đậm (Ctrl+B).","Kẻ khung: tab Design > Borders > All Borders (hoặc Home > nhóm Paragraph > Borders > All Borders).","Nếu bảng rộng quá lề: tab Layout > AutoFit > AutoFit Window."],"note":"Bảng phải có đủ khung viền và hai dòng tiêu đề có ô gộp giống hình trong đề."},{"title":"Bước 7. Tạo dấu đầu dòng và danh mục tài liệu tham khảo tự động","forRequirement":"1, 5","actions":["Bôi đen 3 dòng của Kiểu 1, tab Home > nhóm Paragraph > Bullets (nút dấu chấm tròn). Làm tương tự với 3 dòng của Kiểu 2.","Danh mục tài liệu tham khảo: bôi đen 3 dòng tài liệu, tab Home > Numbering (mũi tên bên cạnh) > Define New Number Format...","Trong hộp Define New Number Format: Number style chọn 1, 2, 3. Ở ô Number format, giữ nguyên số 1 màu xám và gõ thêm dấu [ trước số 1 và dấu ] sau số 1 để thành [1]. Bấm OK.","Ba dòng được đánh số [1], [2], [3] tự động. Chỉnh thụt lề nếu cần ở Home > Paragraph (nút mũi tên nhỏ) > Indentation."],"note":"Phải dùng danh sách đánh số tự động cho [1] [2] [3]. Nếu gõ tay thì Word không tạo được cross-reference tới các mục này ở bước sau."},{"title":"Bước 8. Dùng Cross-reference để tạo tham chiếu đến tài liệu tham khảo","forRequirement":"5","actions":["Đặt con trỏ ngay sau chữ 'xem ' trong cụm '(xem )' ở đoạn đầu mục A.","Tab Insert > nhóm Links > Cross-reference. Trong hộp thoại: Reference type chọn Numbered item.","Insert reference to chọn Paragraph number.","Trong danh sách 'For which numbered item' chọn tài liệu thứ nhất (Eknoyan...). Tick 'Insert as hyperlink', bấm Insert.","Kết quả hiện [1]. Bấm Close.","Lặp lại: sau 'xem ' ở cuối đoạn 2 chèn cross-reference tới tài liệu thứ hai ([2]); ở câu 'Gọi W...' chèn tới tài liệu thứ ba ([3]).","Kiểm tra: giữ Ctrl rồi click vào [1] sẽ nhảy xuống đúng tài liệu; hoặc nhấn Ctrl+A rồi F9 để cập nhật các trường."],"note":"Nếu trong danh sách Numbered item không có mục nào thì do danh mục tài liệu chưa được đánh số tự động (xem Bước 7)."},{"title":"Bước 9. Kiểm tra và lưu","forRequirement":"Tất cả","actions":["Nhấn Ctrl+A, kiểm tra ô Font hiển thị Times New Roman và cỡ 13 (bảng và Heading cũng vậy; công thức dùng Cambria Math là chấp nhận được).","Xem File > Print để kiểm tra bố cục: nội dung nên gọn trong 1 đến 2 trang A4, không bị cắt bảng.","Nhấn Ctrl+S để lưu tệp xyz_cau1.docx."],"note":""}],"formulas":[],"result":"Văn bản gồm tiêu đề căn giữa 'BMI - CHỈ SỐ KHỐI CƠ THỂ', Mục A (Heading 1) với hai mục con 1) Cách tính và 2) Phân loại theo WHO (Heading 2), có công thức BMI(kg/m2) = W/H2 ở giữa dòng và bảng phân loại WHO có ô gộp, Mục B (Heading 1) với hai mục con Kiểu 1 và Kiểu 2 (Heading 2) cùng các dấu đầu dòng, cuối cùng là Tài liệu tham khảo đánh số [1] [2] [3]. Ba chỗ '(xem [1])', '(xem [2])', '(xem [3])' là trường cross-reference (Ctrl+click nhảy đến tài liệu). Tự kiểm tra: Page Setup đúng thông số, Navigation Pane hiện đúng cấu trúc Heading, click vào công thức thấy khung Equation, click vào [1] trong văn bản thấy nền xám của field."},"checklist":["Giấy A4, hướng Portrait","Lề Top 2.5 cm, Bottom 2 cm, Left 3.5 cm, Right 1.5 cm","Toàn bộ văn bản dùng font Times New Roman cỡ 13 (kể cả Heading và bảng)","Đủ nội dung như trang 2: tiêu đề, mục A, B, bảng, các gạch đầu dòng, tài liệu tham khảo","A. Giới thiệu và B. Phân loại chung người lớn hơn 20 tuổi dùng Heading 1","1) Cách tính, 2) Phân loại theo WHO, 1) Kiểu 1, 2) Kiểu 2 (với Nam) dùng Heading 2","Công thức BMI chèn bằng Insert > Equation, hiển thị dạng phân số W trên H bình phương","Bảng phân loại WHO có ô gộp 'Phân loại', 'BMI (kg/m2)', 'BMI nguyên tố' và đủ khung viền","Danh mục tài liệu tham khảo đánh số tự động [1] [2] [3]","Ba chỗ (xem [1]), (xem [2]), (xem [3]) là Cross-reference, Ctrl+click nhảy đúng tài liệu","Lưu đúng tên xyz_cau1.docx"],"commonMistakes":["Đặt font Times New Roman 13 cho Normal nhưng quên chỉnh style Heading nên tiêu đề vẫn là font mặc định, màu xanh.","Áp Heading 1 cho cả tiêu đề lớn hoặc cho mục 1), 2) (đề chỉ yêu cầu H1 cho A, B và H2 cho các mục 1, 2).","Gõ tay [1] [2] [3] ở danh mục tài liệu nên không tạo được cross-reference.","Gõ tay chữ [1] trong câu (xem [1]) thay vì chèn bằng Insert > Cross-reference.","Công thức chèn bằng ảnh hoặc gõ dạng chữ W/H^2 thay vì dùng Insert > Equation.","Quên chọn Whole document khi thiết lập lề hoặc chọn nhầm Orientation.","Máy dùng đơn vị inch nên nhập 2.5 cm bị chuyển đổi sai.","Quên số mũ ở 'kg/m2' và 'H2' (phải là số mũ nhỏ phía trên).","Bảng không gộp ô tiêu đề nên không giống mẫu."],"uncertain":["Ảnh trang 2 hơi mờ nhưng đọc được toàn bộ; dòng 'Phân loại theo WHO' và vài chữ trong bảng hơi nhòe. Đã chép theo hình, sửa lỗi chính tả hiển nhiên.","Đề (hình) ghi Kiểu 2: '20 <= BMI < 25: người bình thường'. File mẫu 234_câu 1.docx ghi khác ('20 <= BMI < 30: người thừa cân'); đã làm theo hình trong đề.","File mẫu không dùng style Heading thật (dùng List Paragraph); hướng dẫn ở đây làm theo yêu cầu của đề (Heading 1, Heading 2).","Các ô trống trong bảng WHO (Từ của Thiếu cân, Đến của Béo phì) để trống đúng như hình.","Đề không nói rõ có áp Heading cho 'Tài liệu tham khảo' hay không; giả định không áp Heading."]},{"no":2,"app":"powerpoint","title":"Câu 2. Tạo các trang trình chiếu (Microsoft PowerPoint)","statement":{"intro":"Sử dụng công cụ MS PowerPoint hãy thiết kế slides trình bày nội dung về \"BMI - chỉ số khối cơ thể\" (đã soạn thảo trong Câu 1) với các yêu cầu sau:","requirements":["1) Thể hiện được toàn bộ nội dung về chỉ số BMI.","2) Slide đầu, slide cuối có bố cục (layout) giống nhau và khác với bố cục các slide còn lại.","3) Trong footer có các thông tin: số slide - tên của thí sinh.","4) Sử dụng 02 hiệu ứng chuyển slide (Transition)","5) Sử dụng 03 hiệu ứng hoạt hình (Animation)."],"material":[{"kind":"text","caption":"Gợi ý bố cục các slide (đề chỉ yêu cầu thể hiện toàn bộ nội dung chỉ số BMI trong Câu 1; thư mục không có file PowerPoint mẫu)","lines":["Slide 1 (layout Title Slide): tiêu đề 'BMI - Chỉ số khối cơ thể'; phụ đề: họ tên và lớp của thí sinh","Slide 2 (layout Title and Content): Giới thiệu - định nghĩa BMI, tác giả Adolphe Quetelet năm 1832, dùng đánh giá mức độ gầy hay béo","Slide 3 (layout Title and Content): Cách tính - W là khối lượng (kg), H là chiều cao (m), công thức BMI(kg/m2) = W / H2 (dạng Equation)","Slide 4 (layout Title and Content): Phân loại theo WHO - bảng phân loại (Thiếu cân, Bình thường, Thừa cân, Béo phì)","Slide 5 (layout Title and Content): Phân loại chung người lớn hơn 20 tuổi - Kiểu 1 và Kiểu 2 (với Nam)","Slide 6 (layout Title and Content): Tài liệu tham khảo [1] [2] [3]","Slide 7 (layout Title Slide, giống slide 1): Cảm ơn / Kết thúc"]}]},"solution":{"summary":"Tạo khoảng 7 slide: slide đầu và slide cuối dùng layout Title Slide, các slide giữa dùng Title and Content, nội dung lấy từ văn bản Câu 1. Sau đó chèn footer (Slide number + tên thí sinh) bằng Insert > Header & Footer, áp dụng đúng 2 kiểu Transition và 3 kiểu Animation.","steps":[{"title":"Bước 0. Tạo file và lưu","forRequirement":"Chung","actions":["Mở PowerPoint, chọn Blank Presentation. Nhấn Ctrl+S, lưu vào E:\\ThiCC với tên xyz_cau3.pptx (xyz là số báo danh) theo ghi chú trong đề.","Lưu ý: ghi chú đề ghi 'Câu 2: xyz_cau2.xlsx' và 'Câu 3: xyz_cau3.pptx' nhưng nội dung đề lại đánh số Câu 2 = PowerPoint và Câu 3 = Excel. Hãy hỏi giám thị khi thi thật."],"note":""},{"title":"Bước 1. Dùng Slide Master để tạo hai loại bố cục khác nhau","forRequirement":"2","actions":["Slide đầu và slide cuối dùng layout Title Slide; các slide còn lại dùng layout khác (Title and Content).","Để thấy khác biệt rõ: tab View > Slide Master. Chọn Title Slide Layout (slide thứ hai bên trái), tab Slide Master > Background Styles chọn nền màu đậm (ví dụ xanh đậm) và đổi màu chữ tiêu đề sang trắng.","Chọn Title and Content Layout, đặt nền khác (trắng hoặc xanh nhạt) và thêm hình chữ nhật dải màu ở đầu slide nếu muốn.","Tab Slide Master > Close Master View để quay lại."],"note":"Mục tiêu: nhìn vào là thấy slide đầu và slide cuối có layout giống nhau và khác hẳn các slide giữa."},{"title":"Bước 2. Tạo slide đầu (Title Slide)","forRequirement":"2, 1","actions":["Slide 1 mặc định là layout Title Slide. Nhập tiêu đề 'BMI - Chỉ số khối cơ thể', phụ đề là họ tên, lớp của bạn.","Nếu không đúng layout: tab Home > Layout > chọn Title Slide."],"note":""},{"title":"Bước 3. Tạo các slide nội dung (Title and Content)","forRequirement":"1, 2","actions":["Tab Home > New Slide > chọn Title and Content, lặp lại để có 5 slide nội dung (slide 2 đến slide 6).","Slide 2 'Giới thiệu': 3 gạch đầu dòng: BMI là viết tắt của Body Mass Index; dùng để đánh giá mức độ gầy hay béo của một người; do nhà bác học Bỉ Adolphe Quetelet đưa ra năm 1832.","Slide 3 'Cách tính': gõ 'W là khối lượng (kg), H là chiều cao (m)'. Chèn công thức: tab Insert > Equation > Fraction Stacked, gõ BMI(kg/m^2)=W/H^2 như bên Word (hoặc copy công thức từ Word bằng Ctrl+C rồi dán vào slide).","Slide 4 'Phân loại theo WHO': ghi 'Người lớn có BMI từ 18,50 đến 24,99 là người bình thường; dưới 18,5 là gầy, từ 25 đến 29,99 là người béo, trên 30 là béo phì'. Chèn bảng bằng Insert > Table (5 cột x 6 hàng) hoặc dán bảng từ Word, nhập dữ liệu như Câu 1; cỡ chữ bảng nên từ 18pt trở lên.","Slide 5 'Phân loại chung người lớn hơn 20 tuổi': Kiểu 1 (BMI < 18: gầy; BMI = 18,5 - 25: bình thường; BMI = 25 - 30: béo phì độ I) và Kiểu 2 (với Nam): BMI < 20: dưới cân; 20 <= BMI < 25: bình thường; 25 <= BMI < 30: quá cân. Có thể dùng layout Two Content để chia hai cột.","Slide 6 'Tài liệu tham khảo': nhập 3 tài liệu [1] [2] [3] như Câu 1.","Slide cuối (slide 7): Home > New Slide > chọn Title Slide (cùng layout slide 1), nhập 'Cảm ơn đã theo dõi'."],"note":"Đề yêu cầu thể hiện toàn bộ nội dung về chỉ số BMI, vì vậy không bỏ sót: giới thiệu, công thức, bảng WHO, phân loại chung (hai kiểu) và tài liệu tham khảo."},{"title":"Bước 4. Footer: số slide và tên thí sinh","forRequirement":"3","actions":["Tab Insert > nhóm Text > Header & Footer. Trong hộp thoại, tab Slide: tick Slide number.","Tick Footer và gõ tên của thí sinh (ví dụ 'Nguyễn Văn A') vào ô trống. Bỏ tick Date and time nếu không cần.","Bấm Apply to All để áp dụng cho mọi slide. Không tick 'Don't show on title slide' để slide đầu và cuối cũng có footer."],"note":"Footer phải có cả số slide và tên. Nếu không thấy trên slide, kiểm tra Slide Master: khung Footer và Slide Number phải còn trong layout."},{"title":"Bước 5. Hai hiệu ứng chuyển slide (Transition)","forRequirement":"4","actions":["Chọn slide 1: tab Transitions > nhóm Transition to This Slide > chọn Fade.","Giữ Ctrl click chọn slide 2 đến slide 6 trong ngăn trái, tab Transitions > chọn Push.","Chọn slide 7 và áp dụng Fade (giống slide 1). Như vậy toàn bài chỉ dùng đúng hai hiệu ứng: Fade và Push.","Nhóm Timing: Duration 1 giây; Advance Slide giữ On Mouse Click."],"note":"Đề yêu cầu '02 hiệu ứng chuyển slide': dùng đúng hai loại khác nhau cho toàn bài, không dùng loại thứ ba."},{"title":"Bước 6. Ba hiệu ứng hoạt hình (Animation)","forRequirement":"5","actions":["Slide 2: bấm chọn khung nội dung (các gạch đầu dòng) > tab Animations > nhóm Animation > chọn Fade (Entrance). Effect Options > By Paragraph để từng dòng hiện lần lượt.","Slide 3: bấm chọn công thức (Equation) > Animations > chọn Wipe > Effect Options > From Left.","Slide 4: bấm chọn bảng > Animations > chọn Zoom. Như vậy có 3 hiệu ứng khác nhau: Fade, Wipe, Zoom.","Kiểm tra bằng Animations > Animation Pane: hiện danh sách hiệu ứng của slide; bấm Preview để xem thử.","Mục Start chọn On Click (hoặc After Previous) tùy ý."],"note":"Đề yêu cầu '03 hiệu ứng hoạt hình': dùng 3 hiệu ứng khác loại trên 3 đối tượng. Không cần gán cho mọi slide."},{"title":"Bước 7. Xem trình chiếu và lưu","forRequirement":"Tất cả","actions":["Nhấn F5 để trình chiếu từ đầu, kiểm tra từng slide: footer, transition, animation, nội dung.","Nhấn Esc để thoát, Ctrl+S để lưu file."],"note":""}],"formulas":[],"result":"Bài gồm 7 slide: slide 1 và slide 7 cùng layout Title Slide (nền khác các slide giữa), slide 2 đến 6 dùng Title and Content trình bày Giới thiệu, Cách tính (công thức), Phân loại theo WHO (bảng), Phân loại chung người lớn (Kiểu 1, Kiểu 2) và Tài liệu tham khảo. Chân mỗi slide có số slide và tên thí sinh. Tab Transitions chỉ có hai hiệu ứng khác nhau, Animation Pane có 3 hiệu ứng. Tự kiểm tra bằng F5 và View > Slide Sorter (slide có hiệu ứng chuyển có biểu tượng ngôi sao nhỏ)."},"checklist":["Nội dung gồm đủ: giới thiệu, công thức tính, phân loại theo WHO, phân loại chung, tài liệu tham khảo","Slide đầu và slide cuối cùng layout (ví dụ Title Slide)","Các slide giữa dùng layout khác slide đầu, cuối (ví dụ Title and Content)","Footer có số slide và tên thí sinh trên các slide","Dùng đúng 2 loại hiệu ứng chuyển slide (Transition)","Dùng 3 hiệu ứng hoạt hình (Animation), kiểm tra trong Animation Pane","Lưu file đúng tên theo đề (xyz_cau3.pptx hoặc theo hướng dẫn phòng thi)"],"commonMistakes":["Slide cuối dùng layout Title and Content giống slide giữa nên vi phạm yêu cầu 'giống slide đầu'.","Footer chỉ có số slide mà quên nhập tên, hoặc quên bấm Apply to All nên chỉ một slide có footer.","Tick 'Don't show on title slide' nên slide đầu không có footer.","Dùng nhiều hơn hoặc ít hơn số hiệu ứng yêu cầu (ví dụ 3 loại transition thay vì 2).","Gán cùng một loại animation cho nhiều đối tượng rồi tưởng là nhiều hiệu ứng; nên dùng 3 loại khác nhau.","Nhồi quá nhiều chữ vào một slide, cỡ chữ quá nhỏ, bảng tràn ra ngoài slide.","Quên lưu file hoặc lưu sai tên, sai thư mục."],"uncertain":["Ghi chú tên file trong đề ghi 'Câu 2: xyz_cau2.xlsx' và 'Câu 3: xyz_cau3.pptx', nhưng nội dung đề lại ghi Câu 2 là PowerPoint và Câu 3 là Excel. Đã giữ nguyên số câu theo nội dung đề và nêu mâu thuẫn trong hướng dẫn.","Thư mục không có file PowerPoint mẫu nên số slide, tiêu đề slide và các hiệu ứng cụ thể (Fade, Push, Wipe, Zoom) là gợi ý của người soạn hướng dẫn; đề chỉ yêu cầu số lượng (02 transition, 03 animation).","Đề viết 'số slide - tên của thí sinh'; đã hiểu là hiện cả số slide và tên thí sinh trong footer.","Đề không nói rõ '02 hiệu ứng chuyển slide' là 2 loại khác nhau; đã chọn cách an toàn là đúng 2 loại khác nhau."]},{"no":3,"app":"excel","title":"Câu 3. Tạo bảng tính (Microsoft Excel)","statement":{"intro":"Quá trình học tập môn Thực tập CSDL của học viên lớp CNTT51 thể hiện như bảng sau: (bảng mẫu bên dưới). Sử dụng phần mềm Microsoft Excel tạo bảng tính thể hiện quá trình học tập môn Thực tập CSDL của học viên lớp CNTT51 với các yêu cầu sau:","requirements":["1) Nhập dữ liệu (giả định) cho 05 học viên trên các cột: TT (thứ tự), Mã HV (Mã học viên), Họ tên, THI (điểm thi), T1 (điểm danh lần 1), T2 (điểm danh lần 2), T3 (điểm danh lần 3), T4 (điểm danh lần 4), B1 (điểm bài tập 1), B2 (điểm bài tập 2); các cột điểm THI, B1, B2 dùng thang điểm 10; các cột T1, T2, T3, T4 nhận 2 giá trị 1 hoặc 0: 1 nếu đi học và 0 nếu nghỉ học.","2) Kẻ khung, căn chỉnh, định dạng các kiểu dữ liệu cho phù hợp; Font: Times New Roman, cỡ 13pt.","3) Định dạng trang: Khổ giấy A4, Landscape; Top: 2.5, Bottom: 2.5; Left: 2.5, right: 1.5.","4) Nhập công thức tính điểm chuyên cần vào cột CC; điểm chuyên cần được tính theo công thức: CC = (T1+T2+T3+T4)x2.5; làm tròn với 1 chữ số sau dấu phẩy.","5) Nhập công thức tính điểm thường xuyên vào cột TX; điểm thường xuyên được tính theo công thức: TX = (B1+B2)/2; làm tròn với 1 chữ số sau dấu phẩy.","6) Nhập công thức tính điểm môn Thực tập CSDL vào cột HP; điểm được tính như sau: nếu điểm thi (THI) lớn hơn 3 thì HP = (0.1*CC+0.3*TX+0.6*THI), ngược lại thì HP = THI; làm tròn với 1 chữ số sau dấu phẩy."],"material":[{"kind":"table","caption":"Bảng mẫu trong đề (tiêu đề cột và dòng ví dụ)","rows":[["TT","Mã HV","Họ tên","CC","TX","THI","HP","T1","T2","T3","T4","B1","B2"],["1","K001","Nguyễn Văn A","","","","","","","","","",""],["...","...","","","","","","","","","","",""]]},{"kind":"table","caption":"Dữ liệu giả định gợi ý cho 05 học viên (lấy từ khối thứ hai của file mẫu; đề cho phép tự giả định). Các cột CC, TX, HP để trống vì tính bằng công thức","rows":[["TT","Mã HV","Họ tên","CC","TX","THI","HP","T1","T2","T3","T4","B1","B2"],["1","K001","Nguyễn Văn A","","","8","","1","1","0","1","8","9"],["2","K002","Đỗ Văn B","","","9","","1","1","1","1","7","9"],["3","K003","Ngô Thị C","","","5","","1","1","1","1","9","7"],["4","K004","Vũ Văn D","","","7","","0","1","1","1","6","6"],["5","K005","Hà Thị E","","","6","","1","1","0","1","7","8"]]}]},"solution":{"summary":"Nhập đủ tiêu đề cột và dữ liệu giả định cho 5 học viên, dùng ROUND kết hợp công thức để tính CC, TX và dùng IF để tính HP; sau đó định dạng khung viền, font Times New Roman 13, kiểu số và cấu hình trang A4 Landscape với lề 2.5 / 2.5 / 2.5 / 1.5 cm.","steps":[{"title":"Bước 0. Tạo file và đặt tên","forRequirement":"Chung","actions":["Mở Excel, chọn Blank workbook. Nhấn Ctrl+S, lưu vào E:\\ThiCC với tên xyz_cau2.xlsx theo ghi chú trong đề (xem mục uncertain: đề đánh số Excel là Câu 3 nhưng ghi chú đặt tên là cau2).","Có thể đổi tên sheet (chuột phải vào tab Sheet1 > Rename), không bắt buộc."],"note":""},{"title":"Bước 1. Nhập tiêu đề cột và dữ liệu 05 học viên","forRequirement":"1","actions":["Tại ô A1 đến M1 nhập lần lượt: TT, Mã HV, Họ tên, CC, TX, THI, HP, T1, T2, T3, T4, B1, B2 (đúng thứ tự cột như bảng trong đề, mỗi tên một ô).","Từ dòng 2 đến dòng 6 (5 học viên): nhập TT là 1 đến 5; Mã HV K001 đến K005; Họ tên; điểm THI, B1, B2 (thang điểm 10, số từ 0 đến 10).","Các cột T1, T2, T3, T4 chỉ nhập 1 (đi học) hoặc 0 (nghỉ học).","Để trống các ô cột CC, TX, HP vì sẽ tính bằng công thức ở các bước sau.","Mẹo: gõ 1 và 2 ở A2, A3, bôi đen cả hai rồi kéo ô vuông nhỏ (fill handle) ở góc dưới phải xuống để điền TT; tương tự với K001, K002 (Excel tự tăng thành K003...)."],"note":"Họ tên có dấu cần Unikey bật Unicode. Điểm THI, B1, B2 phải là số (căn phải) chứ không phải chữ."},{"title":"Bước 2. Công thức điểm chuyên cần CC","forRequirement":"4","actions":["Chọn ô D2, gõ công thức: =ROUND((H2+I2+J2+K2)*2.5,1) rồi nhấn Enter (hoặc dùng =ROUND(SUM(H2:K2)*2.5,1)).","Chọn lại D2, kéo ô vuông nhỏ ở góc dưới phải xuống đến D6 (hoặc nhấp đúp vào ô vuông đó) để điền các dòng còn lại.","Lưu ý dấu phân cách: nếu máy dùng cài đặt khu vực tiếng Việt thì dấu ngăn cách đối số trong hàm là dấu chấm phẩy (;) và dấu thập phân là dấu phẩy (,), khi đó phải gõ 0,1 thay vì 0.1 và ROUND(...;1) thay vì ROUND(...,1). Nếu máy dùng cài đặt tiếng Anh thì dùng dấu phẩy (,) ngăn cách đối số và dấu chấm (.) làm dấu thập phân."],"note":"Mỗi buổi đi học (1) quy ra 2.5 điểm, đi đủ 4 buổi thì CC = 10."},{"title":"Bước 3. Công thức điểm thường xuyên TX","forRequirement":"5","actions":["Chọn ô E2, gõ: =ROUND((L2+M2)/2,1) rồi nhấn Enter (hoặc =ROUND(AVERAGE(L2:M2),1)).","Điền xuống E6 bằng cách kéo ô vuông nhỏ ở góc dưới phải của E2."],"note":"TX là trung bình cộng của hai điểm bài tập B1 và B2, làm tròn một chữ số thập phân."},{"title":"Bước 4. Công thức điểm môn HP","forRequirement":"6","actions":["Chọn ô G2, gõ: =ROUND(IF(F2>3,0.1*D2+0.3*E2+0.6*F2,F2),1) rồi nhấn Enter.","Giải thích: nếu điểm thi F2 lớn hơn 3 thì HP = 0.1*CC + 0.3*TX + 0.6*THI, ngược lại HP = THI; sau cùng làm tròn một chữ số thập phân.","Điền xuống G6 bằng cách kéo ô vuông nhỏ ở góc dưới phải của G2.","Chú ý điều kiện so sánh là điểm THI (cột F), không phải CC (cột D)."],"note":"Điều kiện là 'lớn hơn 3' (F2>3). Điểm thi đúng bằng 3 rơi vào nhánh 'ngược lại', tức HP = THI."},{"title":"Bước 5. Kẻ khung, căn chỉnh, định dạng kiểu dữ liệu, font","forRequirement":"2","actions":["Bôi đen vùng A1:M6. Tab Home > nhóm Font > chọn font Times New Roman, cỡ 13.","Kẻ khung: tab Home > nhóm Font > Borders (nút ô vuông) > All Borders.","Căn chỉnh: bôi đen hàng tiêu đề A1:M1 > Bold (Ctrl+B), Center (Ctrl+E), tô nền nhạt bằng Fill Color; các cột TT, Mã HV và các cột điểm căn giữa; cột Họ tên căn trái.","Kiểu dữ liệu: bôi đen cột D, E, G (CC, TX, HP) > chuột phải > Format Cells... > tab Number > Category: Number, Decimal places = 1.","Các cột THI, B1, B2, T1 đến T4: Category Number, Decimal places = 0 (hoặc General).","Chỉnh độ rộng cột: bôi đen cả bảng > Home > Format > AutoFit Column Width."],"note":"Đề ghi 'định dạng các kiểu dữ liệu cho phù hợp': số dùng dạng Number, văn bản dùng General; điểm tính toán hiển thị 1 chữ số thập phân. Tùy chọn: Data > Data Validation cho T1:T4 (Allow: List, Source: 0,1) để chỉ nhận 0 hoặc 1."},{"title":"Bước 6. Định dạng trang in","forRequirement":"3","actions":["Tab Page Layout > nhóm Page Setup > Margins > Custom Margins...","Tab Margins: Top = 2.5, Bottom = 2.5, Left = 2.5, Right = 1.5 (cm).","Chuyển sang tab Page: Orientation chọn Landscape; Paper size chọn A4. Bấm OK.","Nếu bảng không vừa chiều rộng giấy: trong tab Page chọn Fit to 1 page(s) wide by 1 tall.","Kiểm tra bằng File > Print (xem trước) rằng bảng nằm gọn trên một trang ngang."],"note":"Chú ý lề trái 2.5 và lề phải 1.5 khác nhau, đừng nhập đảo."},{"title":"Bước 7. Kiểm tra và lưu","forRequirement":"Tất cả","actions":["Đối chiếu với dữ liệu gợi ý: Nguyễn Văn A có CC 7.5, TX 8.5, HP 8.1; Đỗ Văn B có CC 10.0, TX 8.0, HP 8.8; Ngô Thị C có CC 10.0, TX 8.0, HP 6.4; Vũ Văn D có CC 7.5, TX 6.0, HP 6.8; Hà Thị E có CC 7.5, TX 7.5, HP 6.6.","Nhấn Ctrl+S để lưu."],"note":"Nếu dùng dữ liệu khác thì tự tính tay một dòng để đối chiếu."}],"formulas":[{"cell":"D2","formula":"=ROUND((H2+I2+J2+K2)*2.5,1)","meaning":"Điểm chuyên cần CC = (T1+T2+T3+T4) x 2.5, làm tròn 1 chữ số thập phân. Điền xuống D3:D6. Tương đương =ROUND(SUM(H2:K2)*2.5,1)."},{"cell":"E2","formula":"=ROUND((L2+M2)/2,1)","meaning":"Điểm thường xuyên TX = (B1+B2)/2, làm tròn 1 chữ số thập phân. Điền xuống E3:E6. Tương đương =ROUND(AVERAGE(L2:M2),1)."},{"cell":"G2","formula":"=ROUND(IF(F2>3,0.1*D2+0.3*E2+0.6*F2,F2),1)","meaning":"Điểm môn HP: nếu điểm thi (F2) lớn hơn 3 thì HP = 0.1*CC + 0.3*TX + 0.6*THI, ngược lại HP = THI; sau cùng làm tròn 1 chữ số thập phân. Điền xuống G3:G6."}],"result":"Bảng gồm 13 cột từ TT đến B2, 5 dòng học viên, kẻ khung đầy đủ, tiêu đề đậm căn giữa, font Times New Roman 13. Các cột CC, TX, HP hiển thị 1 chữ số thập phân và đổi giá trị khi sửa T1 đến T4, B1, B2, THI. Với dữ liệu gợi ý, HP lần lượt là 8.1, 8.8, 6.4, 6.8, 6.6. Page Setup là A4, Landscape, lề Top 2.5, Bottom 2.5, Left 2.5, Right 1.5."},"checklist":["Có đủ 13 cột: TT, Mã HV, Họ tên, CC, TX, THI, HP, T1, T2, T3, T4, B1, B2","Nhập dữ liệu giả định cho đúng 05 học viên","THI, B1, B2 trong thang 0 đến 10; T1 đến T4 chỉ là 0 hoặc 1","Bảng có kẻ khung, tiêu đề căn giữa, các kiểu dữ liệu phù hợp","Font Times New Roman, cỡ 13pt toàn bảng","Page Setup: A4, Landscape; Top 2.5, Bottom 2.5, Left 2.5, Right 1.5","Cột CC dùng công thức (T1+T2+T3+T4)*2.5 làm tròn 1 chữ số thập phân","Cột TX dùng công thức (B1+B2)/2 làm tròn 1 chữ số thập phân","Cột HP dùng IF với điều kiện THI>3, làm tròn 1 chữ số thập phân","Công thức đã điền xuống đủ 5 dòng"],"commonMistakes":["Quên hàm ROUND nên giá trị hiển thị làm tròn nhưng giá trị thật vẫn dài.","Quên nhân 2.5 trong CC hoặc thiếu dấu ngoặc quanh (T1+T2+T3+T4).","Trong HP so sánh nhầm cột (D2>3 thay vì F2>3).","Dùng sai dấu phân cách hàm: máy cài tiếng Việt cần dấu chấm phẩy (;) và dấu thập phân là dấu phẩy.","Gõ 0.1, 0.3, 0.6 trên máy dùng dấu thập phân là dấu phẩy khiến Excel coi là chữ và báo lỗi #VALUE!.","Nhập điểm danh bằng chữ ('có', 'x') thay vì 1 hoặc 0 nên không tính được CC.","Định dạng trang nhầm Portrait hoặc nhập đảo lề trái và phải.","Chỉ chỉnh font cho vùng có dữ liệu mà bỏ sót hàng tiêu đề.","Kéo công thức xuống thiếu dòng cuối nên có học viên chưa được tính điểm."],"uncertain":["Ảnh trang 1 hơi mờ: hệ số '0.6*THI' trong công thức HP đọc là 0.6 (0.1 + 0.3 + 0.6 = 1, hợp lý).","Trong ảnh, ô CC của dòng ví dụ có nét gạch viết tay, không ảnh hưởng đến yêu cầu.","Đề cho phép dữ liệu giả định nên dữ liệu trong 'material' chỉ là gợi ý (lấy từ khối thứ hai của file mẫu 234_Câu 3.xlsx). Khối này trong file mẫu có công thức HP so sánh D>3 (sai so với đề), còn khối đầu dùng đúng F>3; hướng dẫn làm theo đề (THI>3).","File mẫu có 3 bảng ở 3 vùng khác nhau; hướng dẫn chỉ dùng một bảng ở A1:M6.","Ghi chú tên file trong đề ghi Câu 2 là xyz_cau2.xlsx nhưng nội dung đánh số Excel là Câu 3 (PowerPoint là Câu 2); đã giữ số câu theo nội dung đề."]}]},{"id":4,"title":"Đề thực hành số 4","source":"de co ban 4","timeLimitMinutes":60,"generalNotes":["Đề thi cấp chứng chỉ UDCNTT cơ bản, Học viện Kỹ thuật Quân sự, Khoa Công nghệ thông tin. Đợt thi: B191214013. Thời gian: 60 phút.","Đề thi gồm 3 trang; không được sử dụng tài liệu, USB và các thiết bị lưu trữ khác.","Các file bài làm để trong thư mục D:\\ThiCC, cách đặt tên file: Câu 1: sbd_cau1.docx; Câu 2: sbd_cau2.xlsx; Câu 3: sbd_cau3.pptx. Trong đó sbd là số báo danh của thí sinh."],"tasks":[{"no":1,"app":"word","title":"Câu 1. Soạn thảo văn bản (Microsoft Word)","statement":{"intro":"Sử dụng phần mềm Microsoft Word soạn thảo nội dung tài liệu trên trang 3 với các yêu cầu sau:","requirements":["1) Soạn và định dạng đầy đủ nội dung văn bản như trang 3.","2) Định dạng trang: Cỡ giấy: A4; Chiều: Portrait; Lề trên (Top): 2.5 cm, Lề dưới (Bottom): 2 cm, Lề trái (Left): 3.5 cm, Lề phải (Right): 1.5 cm; Font: Times New Roman, cỡ 13.","3) Sử dụng tab để thể hiện các vị trí cần điền vào chỗ trống.","4) Sử dụng công cụ insert để thêm ô có nội dung đối với ảnh người làm đơn.","5) Sử dụng bảng 1 dòng, 2 cột, không đường viền để thể hiện thông tin của phần xác nhận của đơn vị và phần người viết đơn."],"material":[{"kind":"text","caption":"Nội dung văn bản (trang 3 của đề). [Tab] là chỗ nhấn phím Tab để ra dãy dấu chấm; ô ảnh nằm ở góc trên trái.","lines":["CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM","Độc lập - Tự do - Hạnh phúc","(ô góc trên trái, trong ô ghi: ẢNH 4x6)","ĐƠN XIN CHUYỂN ĐỊA ĐIỂM HỌC TẬP","Kính gửi: [Tab]","Tên tôi là: [Tab] Ngày sinh: [Tab]","Số điện thoại liên hệ: [Tab]","Mã SV: [Tab] Ngành: [Tab] Lớp [Tab]","Địa điểm học [Tab]","Nay tôi làm đơn này xin chuyển sang địa điểm:","Địa điểm học tại: [Tab]","cho phù hợp với hoàn cảnh công tác và nguyện vọng cá nhân của mình.","Kính mong lãnh đạo Khoa xem xét cho tôi được chuyển địa điểm học để tôi có điều kiện học tập tốt hơn.","Tôi xin chân thành cảm ơn!","..........., ngày ...... tháng ..... năm 20....","XÁC NHẬN LÃNH ĐẠO KHOA | NGƯỜI VIẾT ĐƠN (bảng 1 dòng 2 cột, không viền)"]}]},"solution":{"summary":"Đặt trang A4 Portrait với lề đúng yêu cầu và font Times New Roman 13 trước, rồi gõ nội dung; các chỗ trống làm bằng tab stop có leader dấu chấm, ô ảnh làm bằng Insert > Text Box, phần ký tên làm bằng bảng 1 dòng 2 cột bỏ viền.","steps":[{"title":"Bước 1. Tạo file và lưu đúng tên","forRequirement":"Ghi chú chung","actions":["Mở Microsoft Word, chọn Blank document.","Nhấn Ctrl+S (hoặc File > Save As > Browse). Chọn thư mục D:\\ThiCC, ở ô File name gõ sbd_cau1 (thay sbd bằng số báo danh của bạn, ví dụ 123_cau1), ở ô Save as type chọn Word Document (*.docx), nhấn Save.","Trong lúc làm bài nhấn Ctrl+S thường xuyên."],"note":"Tên file phải đúng dạng sbd_cau1.docx và nằm trong D:\\ThiCC."},{"title":"Bước 2. Định dạng trang (làm trước khi gõ nội dung)","forRequirement":"2","actions":["Tab Layout (Word 2007/2010 là Page Layout) > nhóm Page Setup, bấm mũi tên nhỏ ở góc dưới bên phải để mở hộp thoại Page Setup.","Thẻ Margins: Top nhập 2.5 cm, Bottom nhập 2 cm, Left nhập 3.5 cm, Right nhập 1.5 cm. Gutter để 0. Mục Orientation chọn Portrait. Mục Apply to chọn Whole document.","Thẻ Paper: ở Paper size chọn A4 (21 cm x 29.7 cm).","Bấm OK. Nếu Word cảnh báo lề nằm ngoài vùng in của máy in thì chọn Ignore để giữ đúng số đo đề yêu cầu."],"note":"Nếu ô hiển thị inch thì cứ gõ '2.5 cm', Word tự đổi đơn vị."},{"title":"Bước 3. Đặt font Times New Roman cỡ 13 cho toàn bài","forRequirement":"2","actions":["Ngay khi còn trang trắng: Home > bấm mũi tên góc nhóm Font (hoặc Ctrl+D) > chọn Font: Times New Roman, Size: 13 > bấm Set As Default > chọn 'This document only' > OK. Khi đó mọi đoạn mới gõ đều là Times New Roman 13.","Hoặc làm sau khi gõ xong: nhấn Ctrl+A, rồi Home > nhóm Font: chọn Times New Roman ở ô font và 13 ở ô cỡ chữ.","Cuối bài, nhấn Ctrl+A một lần nữa và kiểm tra ô font vẫn là Times New Roman, cỡ 13 (ô font trống nghĩa là còn đoạn khác font)."],"note":"Chữ trong Text Box (ô ảnh) và trong bảng cũng phải là Times New Roman 13; kiểm tra riêng từng nơi."},{"title":"Bước 4. Gõ phần tiêu đề (quốc hiệu, tiêu ngữ, tên đơn)","forRequirement":"1","actions":["Dòng 1: gõ CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM, nhấn Ctrl+E để căn giữa, Ctrl+B để in đậm. Nhấn Enter.","Dòng 2: gõ Độc lập - Tự do - Hạnh phúc, Ctrl+E căn giữa, Ctrl+B in đậm. Nhấn Enter.","Gạch dưới tiêu ngữ giống mẫu: Insert > Shapes > chọn Line, giữ phím Shift và kéo chuột ngay dưới dòng 2 một đoạn bằng độ dài chữ tiêu ngữ. (Có thể thay bằng bôi đen dòng 2 và nhấn Ctrl+U, nhưng đường Line giống mẫu hơn.)","Nhấn Enter, để một dòng trống, rồi gõ ĐƠN XIN CHUYỂN ĐỊA ĐIỂM HỌC TẬP, căn giữa (Ctrl+E), in đậm (Ctrl+B).","Nhấn Enter thêm 1 dòng trống trước khi sang phần nội dung đơn."],"note":"Dùng Unikey bật tiếng Việt và soát lại dấu thanh, dấu mũ của từng dòng trước khi sang dòng sau."},{"title":"Bước 5. Dùng Tab để tạo chỗ trống điền thông tin (dấu chấm dẫn)","forRequirement":"3","actions":["Ý tưởng: mỗi dòng cần điền được đặt điểm dừng Tab (tab stop) có Leader là dãy dấu chấm. Khi nhấn phím Tab, Word tự vẽ dãy chấm tới điểm dừng, không phải gõ tay dấu chấm.","Cách đặt: để con trỏ trong dòng cần làm (hoặc bôi đen nhiều dòng cùng kiểu). Home > nhóm Paragraph > bấm mũi tên góc dưới phải > bấm nút Tabs... ở góc dưới bên trái hộp thoại.","Trong hộp Tabs: ở 'Tab stop position' nhập vị trí (cm), Alignment chọn Left, Leader chọn 2 (....), bấm Set. Lặp lại cho từng điểm dừng rồi bấm OK. Vị trí đo từ lề trái; vùng soạn thảo rộng 21 - 3.5 - 1.5 = 16 cm nên điểm dừng cuối đặt khoảng 15.5 cm, không đặt quá 16 cm.","Dòng 'Kính gửi': gõ Tab (điểm dừng 3.5 cm, Leader 1 None để thụt vào), gõ Kính gửi: (in đậm), nhấn Tab (điểm dừng 12.5 cm, Leader 2).","Dòng 'Tên tôi là': gõ Tên tôi là:, Tab (điểm dừng 8.5 cm), gõ Ngày sinh:, Tab (điểm dừng 15.5 cm). Cả hai Leader 2.","Dòng 'Số điện thoại liên hệ': gõ Số điện thoại liên hệ:, Tab (điểm dừng 15.5 cm, Leader 2).","Dòng 'Mã SV': gõ Mã SV:, Tab (7 cm), gõ Ngành:, Tab (12 cm), gõ Lớp:, Tab (15.5 cm). Cả ba Leader 2.","Dòng 'Địa điểm học': gõ Địa điểm học:, Tab (15.5 cm, Leader 2).","Dòng 'Nay tôi làm đơn này xin chuyển sang địa điểm:' gõ bình thường.","Dòng 'Địa điểm học tại': gõ Địa điểm học tại:, Tab (15.5 cm, Leader 2).","Dòng 'cho phù hợp với hoàn cảnh công tác và nguyện vọng cá nhân của mình.' gõ bình thường.","Hai đoạn 'Kính mong lãnh đạo Khoa xem xét cho tôi được chuyển địa điểm học để tôi có điều kiện học tập tốt hơn.' và 'Tôi xin chân thành cảm ơn!': thụt đầu dòng bằng Paragraph > Indentation > Special: First line 1.25 cm (hoặc nhấn Tab đầu đoạn). Chữ 'Tôi xin chân thành cảm ơn!' in nghiêng (Ctrl+I).","Dòng ngày tháng: căn phải (Ctrl+R) rồi gõ ........, ngày ...... tháng ..... năm 20.... hoặc dùng Tab (điểm dừng có leader chấm) để tạo các chỗ trống, giống mẫu.","Kiểm tra: bật Home > nút Show/Hide (Ctrl+Shift+8) sẽ thấy ký hiệu mũi tên Tab ở mỗi chỗ trống thay vì dấu chấm gõ tay."],"note":"Điểm chấm của yêu cầu 3 là các chỗ trống dùng phím Tab. Không gõ liền tay dãy dấu chấm và không dùng nhiều dấu cách để căn."},{"title":"Bước 6. Chèn ô ảnh bằng công cụ Insert (Text Box)","forRequirement":"4","actions":["Tab Insert > nhóm Text > Text Box > chọn Draw Text Box.","Kéo chuột ở góc trên trái, ngang tầm các dòng quốc hiệu, vẽ ô chữ nhật khoảng 2.5 cm x 3.5 cm. Chỉnh chính xác: tab Format (Drawing Tools) > nhóm Size > nhập Height và Width.","Gõ trong ô: dòng 1 ẢNH, dòng 2 4x6. Bôi đen, căn giữa (Ctrl+E), in đậm (Ctrl+B), font Times New Roman 13.","Giữ đường viền đen (Format > Shape Outline > Black) và không tô nền (Shape Fill > No Fill).","Nhấp chọn ô > Format > Wrap Text > chọn In Front of Text hoặc Square để ô không làm xô lệch dòng chữ, rồi kéo ô vào góc trên trái như mẫu."],"note":"Phải tạo bằng Insert (Text Box hoặc Shapes), không dùng bảng hay gõ ký tự để vẽ khung."},{"title":"Bước 7. Tạo bảng 1 dòng 2 cột không đường viền cho phần xác nhận và người viết đơn","forRequirement":"5","actions":["Đặt con trỏ ở dòng mới sau dòng ngày tháng.","Insert > nhóm Tables > Table > Insert Table..., nhập Number of columns: 2, Number of rows: 1 > OK.","Ô trái gõ XÁC NHẬN LÃNH ĐẠO KHOA, ô phải gõ NGƯỜI VIẾT ĐƠN. Bôi đen cả bảng, nhấn Ctrl+B để in đậm và Ctrl+E để căn giữa từng ô.","Bỏ đường viền: bấm vào biểu tượng chọn bảng (dấu thập ở góc trên trái bảng) để chọn cả bảng > Home > nhóm Paragraph > mũi tên của nút Borders > chọn No Border (hoặc Table Tools > Design > Borders > No Border).","Tùy chọn: Table Tools > Layout > Distribute Columns để hai cột bằng nhau; tăng chiều cao hàng hoặc nhấn Enter thêm trong ô để có chỗ ký tên."],"note":"Phải đúng 1 dòng và 2 cột, không còn đường viền nào. Nếu vẫn thấy khung thì chưa chọn cả bảng khi bấm No Border (đường lưới xám hiện trên màn hình là View Gridlines, không in ra)."},{"title":"Bước 8. Kiểm tra và lưu","forRequirement":"1, 2, 3, 4, 5","actions":["Ctrl+A, kiểm tra font là Times New Roman, cỡ 13.","Mở lại Page Setup kiểm tra A4, Portrait, Top 2.5, Bottom 2, Left 3.5, Right 1.5.","File > Print (Ctrl+P) xem trước: toàn bộ đơn gọn trong 1 trang, các dãy dấu chấm kết thúc cùng một mép phải, bảng không viền ở cuối trang.","Ctrl+S lưu lần cuối."],"note":""}],"formulas":[],"result":"Một trang A4 giống trang 3 của đề: quốc hiệu và tiêu ngữ căn giữa in đậm (có đường kẻ dưới tiêu ngữ), ô 'ẢNH 4x6' có viền ở góc trên trái, tiêu đề đơn căn giữa in đậm, các dòng điền thông tin có dấu chấm chạy đều tới gần lề phải nhờ dùng Tab, cuối đơn là dòng ngày tháng và bảng không viền gồm 'XÁC NHẬN LÃNH ĐẠO KHOA' và 'NGƯỜI VIẾT ĐƠN'. Tự kiểm tra: bật Show/Hide thấy ký hiệu Tab ở các chỗ trống; Page Setup đúng số đo; Ctrl+A thấy Times New Roman 13; bấm vào bảng thấy 1 hàng 2 cột và không có đường viền."},"checklist":["Đã lưu file tên sbd_cau1.docx trong D:\\ThiCC","Khổ giấy A4, hướng Portrait","Lề Top 2.5 cm, Bottom 2 cm, Left 3.5 cm, Right 1.5 cm","Toàn bộ văn bản font Times New Roman cỡ 13","Đủ nội dung văn bản như trang 3, tiêu đề căn giữa, in đậm đúng chỗ","Các chỗ trống điền thông tin được tạo bằng phím Tab với leader dấu chấm (không gõ tay dấu chấm)","Có ô ảnh tạo bằng Insert (Text Box) chứa chữ ẢNH 4x6","Có bảng 1 dòng 2 cột, không đường viền, chứa XÁC NHẬN LÃNH ĐẠO KHOA và NGƯỜI VIẾT ĐƠN","Văn bản vừa trong 1 trang"],"commonMistakes":["Gõ tay dãy dấu chấm hoặc dùng dấu cách để căn thay vì dùng Tab và tab stop có leader","Nhầm lề: đặt lề trái 2.5 thay vì 3.5, hoặc lề dưới 2.5 thay vì 2","Chỉ đổi font cho một phần văn bản, quên font trong Text Box và bảng","Vẽ ô ảnh bằng cách gõ ký tự hoặc dùng bảng thay vì Insert > Text Box/Shapes","Bảng vẫn còn đường viền vì chỉ chọn một ô khi bấm No Border; hoặc tạo bảng 2 dòng 1 cột thay vì 1 dòng 2 cột","Đặt điểm dừng tab vượt quá chiều rộng vùng soạn thảo (16 cm) làm dòng bị xuống hàng","Lưu sai tên hoặc sai thư mục"],"uncertain":["Ảnh chụp trang 3 khá rõ nên nội dung được chép đầy đủ. Dòng ngày tháng trong ảnh là '...........,ngày ...... tháng ....năm 20....'; số lượng dấu chấm chỉ là gần đúng.","Đề không nêu kích thước ô ảnh; trong mẫu ô cao khoảng 3 đến 4 cm. Hướng dẫn dùng khoảng 2.5 cm x 3.5 cm làm ví dụ.","File mẫu 234_CÂU1.docx dùng Text Box và một đường Line dưới tiêu ngữ nhưng KHÔNG dùng bảng 1 dòng 2 cột cho phần ký tên (dùng tab); đề yêu cầu bảng nên hướng dẫn làm theo đề. File mẫu cũng ghi 'nguyện vọng cá nhân mình' và 'lien hệ' (sai chính tả); hướng dẫn chép theo ảnh đề: 'nguyện vọng cá nhân của mình' và 'liên hệ'.","Các vị trí tab stop (3.5, 8.5, 12.5, 15.5 cm...) lấy từ file mẫu để dòng chấm gọn; đề không quy định số đo cụ thể."]},{"no":2,"app":"excel","title":"Câu 2. Tạo bảng tính (Microsoft Excel)","statement":{"intro":"Danh sách điểm danh sinh viên của Lớp 12057623 thể hiện như bảng sau (bảng mẫu có các cột TT, Mã SV, Họ tên, Buổi 1 đến Buổi 10, KP, CP, CC; dòng ví dụ: 1 | 1619001 | Nguyễn Văn A | x, 0, x, 1, x, x, x, 0, x, x). Sử dụng phần mềm Microsoft Excel tạo bảng theo dõi học tập với các yêu cầu sau:","requirements":["1) Nhập dữ liệu (giả định) cho 05 sinh viên trên các cột: TT (thứ tự), Mã SV (Mã sinh viên), Họ tên, Buổi 1, Buổi 2,..., Buổi 10: các cột Buổi 1, Buổi 2,..., Buổi 10 nhận một trong các giá trị: x nếu đi học, 0 nếu nghỉ học không phép và 1 nếu nghỉ học có phép. Kẻ khung, căn chỉnh, định dạng các kiểu dữ liệu cho phù hợp; Font: Times New Roman, cỡ 13pt.","2) Định dạng trang: Khổ giấy A4, Landscape; Top: 2.5 cm, Bottom: 2.5 cm; Left: 2.5 cm, Right: 1.5 cm. Căn chỉnh bảng tính ra giữa trang in (Horizontally).","3) Nhập công thức tính Số ngày nghỉ học không phép vào cột KP.","4) Nhập công thức tính Số ngày nghỉ học có phép vào cột CP.","5) Nhập công thức tính Điểm chuyên cần vào cột CC; Biết rằng nếu KP < 3 và CP < 5 thì CC = 10 - KP - 0.5*CP ngược lại CC = 0."],"material":[{"kind":"table","caption":"Dữ liệu gợi ý cho 5 sinh viên (đề cho tự nhập giả định; dữ liệu và kết quả KP, CP, CC lấy theo file mẫu để đối chiếu)","rows":[["TT","Mã SV","Họ tên","Buổi 1","Buổi 2","Buổi 3","Buổi 4","Buổi 5","Buổi 6","Buổi 7","Buổi 8","Buổi 9","Buổi 10","KP","CP","CC"],["1","1619001","Nguyễn Văn A","x","x","x","0","1","x","x","1","x","x","1","2","8"],["2","1619002","Trần Đức Đạt","x","x","x","0","x","x","0","x","x","x","2","0","8"],["3","1619003","Nguyễn Văn Thiện","x","x","x","x","x","1","x","x","x","1","0","2","9"],["4","1619004","Hà Tuấn Dũng","x","0","x","0","x","x","x","x","x","x","2","0","8"],["5","1619005","Nguyễn Đức Hải","x","x","0","1","x","1","0","1","0","x","3","3","0"]]}]},"solution":{"summary":"Nhập bảng A1:P6, kẻ khung và đặt font Times New Roman 13, đặt trang A4 ngang với lề và căn giữa theo chiều ngang, rồi dùng COUNTIF cho KP và CP, IF kết hợp AND cho CC và kéo công thức xuống.","steps":[{"title":"Bước 1. Tạo file và lưu","forRequirement":"Ghi chú chung","actions":["Mở Microsoft Excel, chọn Blank workbook.","Nhấn Ctrl+S, chọn thư mục D:\\ThiCC, đặt tên sbd_cau2 (ví dụ 123_cau2), kiểu Excel Workbook (*.xlsx), nhấn Save."],"note":"sbd là số báo danh của thí sinh."},{"title":"Bước 2. Nhập tiêu đề cột và dữ liệu cho 05 sinh viên","forRequirement":"1","actions":["Ô A1 gõ TT, B1 gõ Mã SV, C1 gõ Họ tên. Từ D1 đến M1 gõ lần lượt Buổi 1, Buổi 2, ..., Buổi 10. Ô N1 gõ KP, O1 gõ CP, P1 gõ CC. Dùng phím Tab để sang ô bên phải.","Hàng 2 đến hàng 6 nhập 5 sinh viên (dữ liệu giả định): TT gõ 1 đến 5; Mã SV gõ 1619001 đến 1619005; Họ tên gõ tên bất kỳ.","Các cột Buổi 1 đến Buổi 10 chỉ nhập một trong các giá trị: x (đi học), 0 (nghỉ không phép), 1 (nghỉ có phép).","Nên cho ít nhất một sinh viên có KP từ 3 trở lên (hoặc CP từ 5 trở lên) để kiểm tra trường hợp CC = 0."],"note":"Chữ x gõ chữ thường; nếu Excel tự đổi thành X cũng không ảnh hưởng vì công thức chỉ đếm số 0 và số 1."},{"title":"Bước 3. Kẻ khung, căn chỉnh, định dạng kiểu dữ liệu và font","forRequirement":"1","actions":["Bôi đen cả bảng A1:P6. Tab Home > nhóm Font: chọn font Times New Roman, cỡ 13.","Kẻ khung: giữ vùng đang chọn, Home > nhóm Font > nút Borders (mũi tên) > All Borders. Hoặc Ctrl+1 > thẻ Border > Outline và Inside > OK.","Hàng tiêu đề A1:P1: bôi đen, Home > nhóm Alignment > Center và Middle Align, nhấn Ctrl+B để in đậm; bật Wrap Text nếu chữ dài.","Căn giữa các cột TT, Mã SV, Buổi 1 đến Buổi 10, KP, CP, CC (Home > Alignment > Center). Cột Họ tên căn trái (Align Left).","Định dạng kiểu dữ liệu: cột TT, KP, CP là Number (0 chữ số thập phân); cột CC là Number với 1 chữ số thập phân vì có thể có 0.5 (chọn cột CC > Ctrl+1 > Number > Decimal places 1); cột Mã SV và Họ tên là Text hoặc General.","Chỉnh độ rộng cột: chọn các cột A đến P, nhấp đúp vào ranh giới giữa hai tiêu đề cột để tự khít (AutoFit), hoặc Home > Format > AutoFit Column Width. Cột Buổi nên hẹp để bảng vừa một trang."],"note":"Nếu muốn giữ Mã SV đúng dạng văn bản thì đặt ô là Text (Format Cells > Text) trước khi nhập."},{"title":"Bước 4. Định dạng trang in","forRequirement":"2","actions":["Tab Page Layout > nhóm Page Setup > bấm mũi tên góc dưới bên phải để mở hộp thoại Page Setup.","Thẻ Page: Orientation chọn Landscape; Paper size chọn A4.","Thẻ Margins: Top nhập 2.5, Bottom nhập 2.5, Left nhập 2.5, Right nhập 1.5 (cm). Ở mục 'Center on page' đánh dấu chọn Horizontally để căn bảng giữa trang theo chiều ngang.","Nhấn OK. Xem trước bằng File > Print (Ctrl+P) để chắc chắn bảng nằm giữa trang."],"note":"Nếu máy hiển thị inch thì gõ '2.5 cm' vào ô, Excel tự đổi (0.98 inch). Nếu bảng tràn sang trang 2 thì thu hẹp độ rộng các cột."},{"title":"Bước 5. Công thức cột KP (số ngày nghỉ học không phép)","forRequirement":"3","actions":["Chọn ô N2 và gõ: =COUNTIF(D2:M2,0) rồi nhấn Enter.","Công thức đếm số ô trong khoảng D2:M2 có giá trị bằng 0 (nghỉ không phép).","Sao chép xuống: nhấp ô N2, đưa chuột vào chấm vuông nhỏ ở góc dưới bên phải ô cho thành dấu cộng đen, nhấp đúp (hoặc kéo xuống tới hàng 6)."],"note":"Nếu máy dùng dấu chấm phẩy làm phân cách đối số thì gõ =COUNTIF(D2:M2;0). Nếu gõ dấu phẩy mà Excel báo lỗi thì đổi sang dấu chấm phẩy, và ngược lại."},{"title":"Bước 6. Công thức cột CP (số ngày nghỉ học có phép)","forRequirement":"4","actions":["Chọn ô O2 và gõ: =COUNTIF(D2:M2,1) rồi nhấn Enter.","Công thức đếm số ô trong khoảng D2:M2 có giá trị bằng 1 (nghỉ có phép).","Sao chép xuống các hàng 3 đến 6 bằng cách nhấp đúp vào chấm vuông ở góc dưới phải ô O2."],"note":""},{"title":"Bước 7. Công thức cột CC (điểm chuyên cần)","forRequirement":"5","actions":["Chọn ô P2 và gõ: =IF(AND(N2<3,O2<5),10-N2-0.5*O2,0) rồi nhấn Enter.","Giải thích: AND(N2<3,O2<5) kiểm tra đồng thời KP nhỏ hơn 3 và CP nhỏ hơn 5. Nếu đúng thì CC = 10 - KP - 0.5*CP, nếu sai thì CC = 0.","Sao chép xuống các hàng 3 đến 6.","Chọn cột CC, Ctrl+1 > Number > Decimal places 1 để số hiển thị đồng đều (ví dụ 8.0, 9.0, 0.0)."],"note":"Không viết số 0 trong dấu ngoặc kép vì kết quả sẽ là chữ chứ không phải số. Nếu máy dùng dấu phẩy thập phân thì hệ số viết 0,5 và các đối số ngăn cách bằng dấu chấm phẩy."},{"title":"Bước 8. Kiểm tra và lưu","forRequirement":"1 đến 5","actions":["Đối chiếu tay vài hàng: đếm số 0 và số 1 trong hàng rồi so với KP và CP.","Xem trước in (Ctrl+P): hướng ngang, bảng nằm giữa trang theo chiều ngang.","Nhấn Ctrl+S lưu file."],"note":""}],"formulas":[{"cell":"N2","formula":"=COUNTIF(D2:M2,0)","meaning":"Đếm số buổi nghỉ không phép (ô có giá trị 0) trong 10 buổi của sinh viên ở hàng 2. Kéo xuống cho N3:N6. Nếu máy dùng dấu ; thì viết =COUNTIF(D2:M2;0)."},{"cell":"O2","formula":"=COUNTIF(D2:M2,1)","meaning":"Đếm số buổi nghỉ có phép (ô có giá trị 1). Kéo xuống cho O3:O6."},{"cell":"P2","formula":"=IF(AND(N2<3,O2<5),10-N2-0.5*O2,0)","meaning":"Nếu KP < 3 và CP < 5 thì điểm chuyên cần = 10 - KP - 0.5*CP, ngược lại bằng 0. Kéo xuống cho P3:P6."}],"result":"Bảng 6 hàng (1 hàng tiêu đề, 5 sinh viên) x 16 cột có khung, font Times New Roman 13. Với dữ liệu gợi ý: KP lần lượt 1, 2, 0, 2, 3; CP lần lượt 2, 0, 2, 0, 3; CC lần lượt 8, 8, 9, 8, 0 (sinh viên thứ 5 có KP = 3 nên CC = 0). Xem trước in thấy trang A4 ngang, bảng nằm giữa trang theo chiều ngang. Tự kiểm tra bằng cách chọn ô N2, O2, P2 và xem thanh công thức."},"checklist":["Đã lưu file tên sbd_cau2.xlsx trong D:\\ThiCC","Có đủ cột TT, Mã SV, Họ tên, Buổi 1 đến Buổi 10, KP, CP, CC và 5 dòng sinh viên","Các cột Buổi chỉ chứa x, 0 hoặc 1","Bảng có kẻ khung, căn chỉnh hợp lý; font Times New Roman cỡ 13","Khổ giấy A4, Landscape; lề Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 cm","Đã bật căn giữa theo chiều ngang (Center on page: Horizontally)","Cột KP dùng công thức COUNTIF đếm số 0","Cột CP dùng công thức COUNTIF đếm số 1","Cột CC dùng IF và AND đúng điều kiện KP < 3 và CP < 5, trường hợp ngược lại kết quả là số 0"],"commonMistakes":["Dùng dấu phẩy thay cho dấu chấm phẩy (hoặc ngược lại) nên Excel báo lỗi công thức","Đếm sai vùng: phải đếm trong D:M của đúng hàng, không phải cả cột","Viết điều kiện CC bằng OR thay vì AND, hoặc dùng <= thay cho <","Viết \"0\" trong ngoặc kép làm CC thành chữ","Khóa nhầm bằng dấu $ (ví dụ $D$2:$M$2) nên kéo xuống các hàng đều ra kết quả của hàng 2","Quên bật Horizontally, chọn nhầm Portrait hoặc ghi lề Right là 2.5","Nhập chữ O thay cho số 0 (số 0 phải là chữ số 0)","Bảng quá rộng nên tràn sang trang thứ hai khi in"],"uncertain":["Trang 2 của đề và toàn bộ Câu 3 KHÔNG có trong ảnh. Ảnh 4.1.jpg chỉ chụp trang 1 (Câu 1 và Câu 2 yêu cầu 1 đến 5; yêu cầu 5 kết thúc ở cuối trang bằng 'ngược lại CC = 0.'). Có thể còn yêu cầu khác của Câu 2 nằm ở trang 2 mà không thể biết.","Dữ liệu 5 sinh viên trong đề là 'giả định'; bảng gợi ý lấy từ file mẫu 234_câu 2.xlsx (vùng A29:P34, Mã SV 1619001 đến 1619005); họ tên chỉ để tham khảo.","Số liệu dòng ví dụ (x 0 x 1 x x x 0 x x) và số lớp 12057623 đọc được rõ từ ảnh.","File mẫu có vùng dùng COUNTIF(D30:M30,\"0\") và vùng khác dùng COUNTIF(D2:M2,0), đều cho kết quả đúng; hướng dẫn chọn dạng số 0 và 1 không có ngoặc kép. Một vùng của file mẫu còn dùng \"0\" trong ngoặc kép ở nhánh sai của IF, hướng dẫn dùng số 0 thật."]},{"no":3,"app":"powerpoint","title":"Câu 3. Trình chiếu (Microsoft PowerPoint)","statement":{"intro":"Không có trong ảnh. Hai ảnh được cung cấp (4.1.jpg và 4.3.jpg) chỉ gồm trang 1 và trang 3 của đề; Câu 3 PowerPoint nằm ở trang 2 chưa được chụp, và thư mục cũng không có file mẫu PowerPoint.","requirements":[],"material":[]},"solution":{"summary":"Chưa có đề nên không thể viết lời giải cụ thể. Dưới đây chỉ là bước chung về lưu file, cần bổ sung khi có ảnh trang 2.","steps":[{"title":"Bước chung. Tạo và lưu file","forRequirement":"Ghi chú chung","actions":["Mở PowerPoint, chọn Blank Presentation.","Nhấn Ctrl+S, chọn thư mục D:\\ThiCC, đặt tên sbd_cau3 (ví dụ 123_cau3), kiểu PowerPoint Presentation (*.pptx), nhấn Save.","Sau đó làm theo từng yêu cầu của đề khi có nội dung (Slide Master, bố cục, Animations, Transitions, đánh số slide qua Insert > Slide Number...)."],"note":"Cần bổ sung hướng dẫn chi tiết sau khi có ảnh trang 2 của đề."}],"formulas":[],"result":"Chưa xác định vì chưa có đề. Chỉ biết file phải lưu tên sbd_cau3.pptx trong D:\\ThiCC."},"checklist":["Đã lưu file tên sbd_cau3.pptx trong D:\\ThiCC","Thực hiện đầy đủ các yêu cầu ở trang 2 của đề (cần bổ sung)"],"commonMistakes":["Lưu sai tên hoặc sai thư mục","Bỏ sót yêu cầu vì chưa đọc hết trang 2 của đề"],"uncertain":["Toàn bộ nội dung Câu 3 (PowerPoint) nằm ở trang 2 của đề, không có trong ảnh; không có file PowerPoint mẫu trong thư mục. Cần chụp bổ sung trang 2 để hoàn thiện."]}]},{"id":5,"title":"Đề thực hành số 5","source":"de co ban 5","timeLimitMinutes":60,"generalNotes":["Đề thi cấp chứng chỉ Ứng dụng CNTT cơ bản, Học viện Kỹ thuật Quân sự, Khoa Công nghệ thông tin. Đợt thi B191101009. Thời gian làm bài: 60 phút.","Đề thi gồm 2 trang (trang 1 là đề bài 3 câu, trang 2 là tài liệu mẫu 'Sơ yếu lý lịch' để soạn thảo ở Câu 1).","Không được sử dụng tài liệu, USB và các thiết bị lưu trữ khác.","Các file bài làm để trong thư mục D:\\ThiCC. Câu 1: xyz_cau1.docx. Câu 2: xyz_cau2.xlsx. Câu 3: xyz_cau3.pptx. Trong đó xyz là số báo danh của thí sinh (ví dụ số báo danh 015 thì đặt tên 015_cau1.docx, 015_cau2.xlsx, 015_cau3.pptx).","Gợi ý phân bổ thời gian cho 60 phút: Câu 1 (Word) khoảng 20 phút, Câu 2 (Excel) khoảng 20 phút, Câu 3 (PowerPoint) khoảng 20 phút. Nên lưu file ngay sau khi tạo (Ctrl+S) và lưu lại thường xuyên.","Mở thư mục D:\\ThiCC bằng hộp thoại Save As (File > Save As), gõ đúng tên file kèm phần mở rộng đúng loại (.docx, .xlsx, .pptx). Kiểm tra lại tên file và vị trí lưu trước khi hết giờ.","Trong Câu 3, các slide tuyệt đối không được ghi thông tin liên quan đến thí sinh (họ tên, số báo danh, lớp, đơn vị...).","Hướng dẫn dưới đây viết cho Microsoft Office 2010 trở lên (giao diện tiếng Anh). Nếu máy dùng giao diện tiếng Việt, tên tab và nút tương ứng được ghi kèm gợi ý tiếng Việt."],"tasks":[{"no":1,"app":"word","title":"Câu 1. Soạn thảo văn bản (Microsoft Word)","statement":{"intro":"Sử dụng phần mềm Microsoft Word soạn thảo nội dung tài liệu trên trang 2 với các yêu cầu sau:","requirements":["1) Soạn và định dạng đầy đủ nội dung văn bản như trang 2.","2) Định dạng trang: Cỡ giấy: A4; Chiều: Portrait; Lề trên (Top): 2.5 cm, Lề dưới (Bottom): 2 cm, Lề trái (Left): 3.5 cm, Lề phải (Right): 1.5 cm; Font: Times New Roman, cỡ 13.","3) Sử dụng tab để thể hiện các vị trí cần điền vào chỗ trống.","4) Sử dụng bảng để thể hiện thông tin về quá trình học tập và làm việc. Sử dụng nét đứt cho dòng kẻ ngang bên trong của bảng.","5) Sử dụng công cụ chèn để chèn thêm ảnh vào góc trái của Sơ yếu lý lịch."],"material":[{"kind":"text","caption":"Nội dung trang 2 của đề (mẫu Sơ yếu lý lịch) mà thí sinh phải soạn, theo thứ tự từ trên xuống","lines":["[Khung ảnh ở góc trái phía trên, trong đề ghi:] ẢNH","[Khung ảnh] 4X6","[Khung ảnh] (Đóng dấu giáp lai của cơ quan xác nhận lý lịch)","CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM","Độc lập - Tự do - Hạnh phúc","----------0o0----------","SƠ YẾU LÝ LỊCH","I- PHẦN BẢN THÂN","Họ và tên khai sinh: ................ (Nam, Nữ): ................","Tên thường gọi: ................ Bí danh: ................","Ngày sinh: ................","Nơi sinh: ................","Hộ khẩu thường trú: ................","II- QUÁ TRÌNH HỌC TẬP VÀ LÀM VIỆC","[Bảng 4 cột, xem mục bảng bên dưới]","Tôi xin cam đoan những nội dung khai trên đây là đúng sự thật, nếu sai tôi xin chịu hoàn toàn trách nhiệm trước pháp luật.","............. , ngày ... tháng ....năm ............","Người khai","(Ký và ghi rõ họ tên)","[Dòng ghi chú chìm ở cuối trang 2 của đề: '(không soạn thảo nội dung này)  Trang 2'. Dòng này KHÔNG phải soạn.]"]},{"kind":"table","caption":"Bảng Quá trình học tập và làm việc (dòng đầu là tiêu đề, kèm 4 dòng trống để điền)","rows":[["Ngày, tháng, năm","Học tập hoặc làm việc gì","Ở đâu","Thành tích học và làm việc"],["","","",""],["","","",""],["","","",""],["","","",""]]}]},"solution":{"summary":"Thiết lập trang và font trước, gõ từng khối nội dung theo đúng thứ tự trang 2, dùng Tab có leader chấm cho các chỗ điền, tạo bảng 4 cột 5 dòng với đường ngang bên trong dạng nét đứt, rồi chèn ảnh ở góc trái trên cùng.","steps":[{"title":"Bước 1. Tạo file và lưu đúng tên, đúng thư mục","forRequirement":"Chung (tên file)","actions":["Mở Microsoft Word, chọn Blank document (Tài liệu trống).","Nhấn Ctrl+S (hoặc File > Save As). Trong hộp thoại, đi tới ổ D:, chọn thư mục ThiCC (D:\\ThiCC).","Ở ô File name gõ xyz_cau1 (thay xyz bằng số báo danh), ở ô Save as type chọn Word Document (*.docx), bấm Save."],"note":"Nên lưu ngay từ đầu, sau đó cứ vài phút nhấn Ctrl+S một lần."},{"title":"Bước 2. Định dạng trang: A4, Portrait, lề trên 2.5, dưới 2, trái 3.5, phải 1.5","forRequirement":"2) Định dạng trang","actions":["Chọn tab Page Layout (Bố cục trang) > nhóm Page Setup > bấm mũi tên nhỏ ở góc dưới bên phải nhóm (Dialog Launcher) để mở hộp thoại Page Setup.","Tab Margins: gõ Top = 2.5 cm, Bottom = 2 cm, Left = 3.5 cm, Right = 1.5 cm. Mục Gutter để 0. Mục Orientation chọn Portrait (khổ đứng).","Tab Paper: mục Paper size chọn A4 (hiển thị 21 cm x 29.7 cm).","Mục Apply to chọn Whole document, bấm OK."],"note":"Nếu ô nhập hiển thị đơn vị inch thì gõ kèm đơn vị, ví dụ 3.5 cm, Word sẽ tự quy đổi. Có thể đổi đơn vị mặc định ở File > Options > Advanced > mục Display > Show measurements in units of: Centimeters."},{"title":"Bước 3. Đặt font Times New Roman, cỡ 13 và khoảng cách dòng gọn cho toàn bài","forRequirement":"2) Font Times New Roman cỡ 13","actions":["Cách chắc chắn nhất: trong tab Home > nhóm Styles, bấm chuột phải vào kiểu Normal > Modify... Trong hộp thoại Modify Style đặt Font = Times New Roman, Size = 13, bấm nút Format > Paragraph... đặt Line spacing = Single, Spacing Before = 0 pt, After = 0 pt, bấm OK hai lần. Như vậy mọi đoạn văn và nội dung trong bảng đều dùng Times New Roman 13.","Cách nhanh khác: khi văn bản còn trống, nhấn Ctrl+A, rồi tab Home > nhóm Font chọn Times New Roman và cỡ (Font Size) 13; hoặc nhấn Ctrl+D mở hộp thoại Font và chọn Times New Roman, Size 13. Sau đó nhớ kiểm tra lại các đoạn gõ mới có đúng font không.","Việc đặt Spacing After = 0 pt giúp cả tài liệu (gồm ảnh, bảng và phần ký tên) vừa gọn trong một trang A4 như đề."],"note":"Tiêu đề 'SƠ YẾU LÝ LỊCH' trong đề có chữ lớn hơn các dòng khác, sẽ tăng riêng ở Bước 4. Toàn bộ phần nội dung còn lại để cỡ 13."},{"title":"Bước 4. Soạn phần quốc hiệu, tiêu ngữ và tiêu đề","forRequirement":"1) Soạn và định dạng đầy đủ nội dung","actions":["Gõ dòng 1: CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM. Nhấn Enter.","Gõ dòng 2: Độc lập - Tự do - Hạnh phúc. Nhấn Enter. Gõ dòng 3: ----------0o0---------- (10 dấu gạch nối, 0o0, 10 dấu gạch nối). Nhấn Enter.","Gõ dòng 4: SƠ YẾU LÝ LỊCH. Nhấn Enter.","Bôi đen 4 dòng vừa gõ. Nhấn Ctrl+E để căn giữa (Center) và Ctrl+B để in đậm. Bôi riêng dòng 'SƠ YẾU LÝ LỊCH', đặt cỡ chữ 18 (Home > Font Size).","Tạo khoảng cách bằng Paragraph chứ không nhấn Enter nhiều lần: bôi dòng 'SƠ YẾU LÝ LỊCH' > Home > nhóm Paragraph > Dialog Launcher > đặt Spacing Before = 12 pt, After = 12 pt.","Gõ tiếp dòng: I- PHẦN BẢN THÂN, nhấn Ctrl+L để căn trái, Ctrl+B để in đậm, đặt Spacing After = 6 pt. Nhấn Enter rồi tắt in đậm (Ctrl+B)."],"note":"Dòng 'Độc lập - Tự do - Hạnh phúc' gõ bằng dấu gạch nối thường (-), có khoảng trắng hai bên."},{"title":"Bước 5a. Dòng 'Họ và tên khai sinh' dùng Tab có đường dẫn chấm (leader)","forRequirement":"3) Sử dụng tab để thể hiện các chỗ cần điền","actions":["Bấm vào dòng trống mới (căn trái, không in đậm). Nhấn Ctrl+L. Mở tab Home > nhóm Paragraph > Dialog Launcher > nút Tabs... (ở góc dưới bên trái hộp thoại Paragraph) để mở hộp thoại Tabs.","Trong hộp thoại Tabs: ô Tab stop position gõ 9.5 cm; mục Alignment chọn Left; mục Leader chọn 2 (........ đường chấm); bấm Set.","Tiếp tục: ô Tab stop position gõ 16 cm; mục Alignment chọn Right; mục Leader chọn 2 (đường chấm); bấm Set. Bấm OK.","Gõ: Họ và tên khai sinh: (có khoảng trắng sau dấu hai chấm), nhấn phím Tab một lần. Đường chấm tự điền tới vị trí 9.5 cm. Gõ: (Nam, Nữ): rồi nhấn phím Tab lần nữa. Đường chấm tự điền tới sát lề phải. Nhấn Enter."],"note":"Vị trí tab đo từ mép lề trái. Vùng chữ rộng 21 - 3.5 - 1.5 = 16 cm nên tab phải ở 16 cm là sát lề phải. Không được gõ tay dấu chấm bằng phím, vì đề yêu cầu dùng tab."},{"title":"Bước 5b. Dòng 'Tên thường gọi' và 'Bí danh'","forRequirement":"3) Sử dụng tab","actions":["Đoạn mới thừa hưởng tab của dòng trước. Mở lại hộp thoại Tabs (Home > Paragraph > Dialog Launcher > Tabs...), bấm Clear All để xóa tab cũ.","Đặt tab 1: Tab stop position = 8.5 cm, Alignment = Left, Leader = 2, bấm Set. Đặt tab 2: Tab stop position = 16 cm, Alignment = Right, Leader = 2, bấm Set. Bấm OK.","Gõ: Tên thường gọi: rồi nhấn Tab, gõ Bí danh: rồi nhấn Tab. Nhấn Enter."],"note":""},{"title":"Bước 5c. Các dòng 'Ngày sinh', 'Nơi sinh', 'Hộ khẩu thường trú'","forRequirement":"3) Sử dụng tab","actions":["Mở hộp thoại Tabs, bấm Clear All. Đặt một tab duy nhất: Tab stop position = 16 cm, Alignment = Right, Leader = 2, bấm Set, OK.","Gõ: Ngày sinh: rồi nhấn Tab. Nhấn Enter. Gõ: Nơi sinh: rồi nhấn Tab. Nhấn Enter. Gõ: Hộ khẩu thường trú: rồi nhấn Tab. Nhấn Enter.","Để nhanh: sau khi gõ xong dòng 'Ngày sinh', các dòng sau tự giữ tab 16 cm, chỉ cần gõ nhãn và nhấn Tab."],"note":"Nếu đường chấm bị xuống dòng, kiểm tra tab phải có nằm trong vùng chữ (không lớn hơn 16 cm) và nhãn không quá dài."},{"title":"Bước 6. Gõ tiêu đề phần II và tạo bảng","forRequirement":"4) Sử dụng bảng để thể hiện quá trình học tập và làm việc","actions":["Ở đoạn mới, mở Tabs > Clear All > OK để xóa tab thừa. Gõ: II- QUÁ TRÌNH HỌC TẬP VÀ LÀM VIỆC. Bôi đen dòng này, nhấn Ctrl+B in đậm. Home > Paragraph > đặt Spacing Before = 12 pt, After = 6 pt. Nhấn Enter, tắt in đậm.","Tab Insert > nhóm Tables > Table > Insert Table... Nhập Number of columns = 4, Number of rows = 5 (1 dòng tiêu đề + 4 dòng trống). Chọn Fixed column width: Auto. Bấm OK.","Gõ tiêu đề 4 ô của dòng đầu: ô 1 'Ngày, tháng, năm'; ô 2 'Học tập' rồi nhấn Shift+Enter (xuống dòng mềm) rồi gõ 'hoặc làm việc gì'; ô 3 'Ở đâu'; ô 4 'Thành tích học' Shift+Enter 'và làm việc'. Dùng phím Tab để chuyển ô.","Bôi đen dòng tiêu đề: nhấn Ctrl+B in đậm; tab Table Tools > Layout > nhóm Alignment > Align Center (căn giữa theo cả chiều ngang và dọc).","Chỉnh độ rộng cột: bấm vào bảng > Table Tools > Layout > nhóm Cell Size. Đặt Table Column Width lần lượt: cột 1 = 2.5 cm, cột 2 = 5.5 cm, cột 3 = 4 cm, cột 4 = 4 cm (tổng 16 cm bằng vùng chữ). Chọn các dòng và đặt Table Row Height khoảng 0.8 cm cho dòng trống.","Kẻ khung: bấm vào bảng > Table Tools > Design > nhóm Table Styles > chọn Table Grid (khung đơn toàn bộ) nếu bảng chưa có khung."],"note":"Bảng gồm 4 cột với tiêu đề đúng như đề: 'Ngày, tháng, năm' / 'Học tập hoặc làm việc gì' / 'Ở đâu' / 'Thành tích học và làm việc'."},{"title":"Bước 7. Đặt nét đứt cho các đường kẻ ngang bên trong bảng","forRequirement":"4) Nét đứt cho dòng kẻ ngang bên trong của bảng","actions":["Quét chọn 4 dòng trống của bảng (rê chuột từ ô đầu của dòng trống thứ nhất tới ô cuối của dòng trống thứ tư). Không chọn dòng tiêu đề.","Bấm chuột phải vào vùng chọn > Borders and Shading... (hoặc tab Table Tools > Design > nhóm Table Styles > mũi tên của nút Borders > Borders and Shading...) để mở hộp thoại Borders and Shading.","Tab Borders: ở cột Setting chọn Custom. Ở danh sách Style cuộn chọn kiểu nét đứt (dấu gạch ngắn hoặc chấm vuông, ví dụ - - - - hoặc ......). Color để Automatic, Width để 1/2 pt.","Trong khung Preview, bấm vào đường ngang ở giữa (hoặc bấm nút Inside Horizontal Border ở bên cạnh khung Preview) để áp nét đứt cho đường kẻ ngang bên trong. Mục Apply to chọn Cell. Bấm OK.","Cách khác nhanh hơn: chọn 4 dòng trống > tab Design > nhóm Draw Borders > Pen Style (hoặc Line Style) chọn nét đứt > bấm mũi tên nút Borders > chọn Inside Horizontal Border.","Kiểm tra: đường viền ngoài và đường dưới dòng tiêu đề vẫn là nét liền; các đường ngang giữa 4 dòng trống là nét đứt; các đường dọc vẫn là nét liền."],"note":"Nếu đường ngang dưới dòng tiêu đề cũng bị đứt, chọn dòng tiêu đề > Design > Pen Style chọn nét liền > Borders > Bottom Border để làm liền lại."},{"title":"Bước 8. Soạn lời cam đoan và phần ngày tháng, người khai","forRequirement":"1) Soạn và định dạng đầy đủ nội dung","actions":["Bấm vào đoạn trống dưới bảng (nếu bảng nằm cuối văn bản, Word luôn để sẵn một đoạn trống sau bảng). Home > Paragraph > Dialog Launcher > Tabs... > Clear All, rồi OK.","Gõ: Tôi xin cam đoan những nội dung khai trên đây là đúng sự thật, nếu sai tôi xin chịu hoàn toàn trách nhiệm trước pháp luật. Nhấn Ctrl+J để căn đều hai bên (Justify). Đặt Spacing Before = 12 pt. Nhấn Enter.","Đoạn tiếp theo (dòng ngày tháng): Home > Paragraph > Indentation > Left = 8 cm. Mở Tabs, Clear All rồi đặt 4 tab: 9.7 cm (Left, Leader 2), 12 cm (Left, Leader 2), 14.3 cm (Left, Leader 2), 16 cm (Right, Leader 2). Bấm OK.","Gõ theo thứ tự: nhấn Tab, gõ ', ngày ' , nhấn Tab, gõ ' tháng ', nhấn Tab, gõ 'năm ', nhấn Tab. Bôi đen cả dòng, nhấn Ctrl+I để in nghiêng. Nhấn Enter.","Dòng tiếp theo: Mở Tabs > Clear All > OK. Gõ: Người khai, nhấn Ctrl+E (căn giữa) và Ctrl+B (in đậm); thụt lề trái 8 cm (Left = 8 cm), Right = 0. Nhấn Enter. Tắt in đậm.","Dòng cuối: gõ (Ký và ghi rõ họ tên), nhấn Ctrl+E căn giữa, Ctrl+I in nghiêng, thụt lề trái 8 cm. Không gõ thêm gì phía dưới.","Không gõ dòng '(không soạn thảo nội dung này)  Trang 2' vì đó là ghi chú của đề, không thuộc nội dung phải soạn."],"note":"Khối ngày tháng và ký tên thụt vào bên phải khoảng 8 cm. Vị trí tab ở đây chỉ gần đúng, có thể kéo lệch vài mm cho cân đối với thước kẻ (View > Ruler)."},{"title":"Bước 9. Chèn ảnh vào góc trái của Sơ yếu lý lịch","forRequirement":"5) Dùng công cụ chèn để chèn ảnh vào góc trái","actions":["Bấm vào đầu tài liệu. Tab Insert > nhóm Illustrations > Picture. Chọn một file ảnh có sẵn trên máy (ví dụ trong thư mục Pictures/Sample Pictures hoặc ảnh chân dung bất kỳ) rồi bấm Insert. Nếu máy có Clip Art thì có thể dùng Insert > Clip Art.","Bấm vào ảnh để chọn. Tab Picture Tools > Format > nhóm Size: bỏ chọn Lock aspect ratio nếu cần và đặt kích thước khoảng Width = 2.5 cm, Height = 3.5 cm (cỡ ảnh thẻ trong đề).","Tab Picture Tools > Format > nhóm Arrange > Wrap Text > chọn In Front of Text (hoặc Square). Nếu dùng Square, chữ dòng đầu sẽ dạt sang phải ảnh, vẫn chấp nhận được.","Tab Picture Tools > Format > Arrange > Position > More Layout Options... > tab Position: Horizontal Alignment = Left relative to Margin; Vertical Absolute position = 0 cm below Margin (hoặc Position > 'Position in Top Left with Square Text Wrapping'). Bấm OK.","Ảnh nằm ở góc trái phía trên, ngang hàng với dòng quốc hiệu, không đè lên chữ.","Tùy chọn (nếu còn thời gian): giống đề, vẽ khung chữ chứa các dòng 'ẢNH', '4X6', '(Đóng dấu giáp lai của cơ quan xác nhận lý lịch)': Insert > Text Box > Draw Text Box, gõ nội dung, chữ in đậm cỡ 9 đến 10, căn giữa. Có thể đặt khung này vào đúng vị trí ảnh, hoặc đặt ảnh chồng lên khung."],"note":"Yêu cầu 5 chỉ nói 'chèn thêm ảnh vào góc trái' nên cần chèn bằng Insert > Picture, không dán ảnh chụp màn hình hoặc vẽ hình thay thế."},{"title":"Bước 10. Kiểm tra bố cục và lưu bài","forRequirement":"1) đến 5)","actions":["Mở File > Print để xem trang in (Print Preview). Toàn bộ nội dung phải nằm trong 1 trang A4 và giống trang 2 của đề: ảnh ở góc trái, quốc hiệu và tiêu đề căn giữa, 5 dòng chấm điền, bảng, lời cam đoan, khối ký tên.","Bật View > Ruler, nhấn vào từng dòng chấm điền để kiểm tra dấu tab trên thước (có các dấu chữ L hoặc ngược L tại các vị trí đã đặt).","Nhấn Ctrl+S để lưu. Kiểm tra file đã nằm trong D:\\ThiCC với tên xyz_cau1.docx."],"note":""}],"formulas":[],"result":"File xyz_cau1.docx là một trang A4 đứng, lề 2.5 / 2 / 3.5 / 1.5 cm, toàn bộ chữ Times New Roman cỡ 13 (riêng tiêu đề SƠ YẾU LÝ LỊCH có thể lớn hơn). Có ảnh ở góc trái phía trên. Quốc hiệu, tiêu ngữ, tiêu đề căn giữa. Năm dòng thông tin bản thân có đường chấm kéo dài tới sát lề phải do Tab tạo ra. Bảng 4 cột có tiêu đề in đậm căn giữa và 4 dòng trống, viền ngoài nét liền, các đường ngang bên trong nét đứt. Lời cam đoan căn đều hai bên, khối ngày tháng và ký tên ở bên phải. Tự kiểm tra: Page Layout > Margins xem số liệu; bấm vào từng dòng chấm điền xem dấu tab trên thước; File > Print xem toàn bộ nằm gọn 1 trang."},"checklist":["File lưu tại D:\\ThiCC với tên xyz_cau1.docx","Khổ giấy A4, hướng Portrait","Lề: Top 2.5 cm, Bottom 2 cm, Left 3.5 cm, Right 1.5 cm","Toàn bộ văn bản dùng font Times New Roman cỡ 13 (tiêu đề lớn hơn được chấp nhận)","Có đủ các dòng quốc hiệu, tiêu ngữ, ----------0o0----------, SƠ YẾU LÝ LỊCH, I- PHẦN BẢN THÂN, II- QUÁ TRÌNH HỌC TẬP VÀ LÀM VIỆC","Các chỗ điền (Họ và tên khai sinh, Nam/Nữ, Tên thường gọi, Bí danh, Ngày sinh, Nơi sinh, Hộ khẩu thường trú) có đường chấm tạo bằng Tab và leader, không gõ tay dấu chấm","Bảng có 4 cột đúng tiêu đề và 4 dòng trống","Đường kẻ ngang bên trong bảng là nét đứt, viền ngoài vẫn nét liền","Lời cam đoan được căn đều hai bên","Có dòng ngày tháng năm, 'Người khai', '(Ký và ghi rõ họ tên)' ở bên phải","Có ảnh chèn bằng Insert > Picture ở góc trái phía trên","Không có dòng '(không soạn thảo nội dung này)' trong file","Toàn bộ nội dung nằm trong 1 trang"],"commonMistakes":["Gõ dấu chấm bằng bàn phím hoặc nhấn dấu cách nhiều lần thay vì dùng Tab với Leader chấm.","Đặt lề trái 3 cm (mặc định của nhiều mẫu) thay vì 3.5 cm theo đề. File mẫu tuan05.docx có lề trái 3.0 cm nên không dùng làm chuẩn.","Quên đặt font Times New Roman cỡ 13 cho phần bảng hoặc các đoạn mới; quên đổi Spacing After khiến nội dung tràn sang trang 2.","Chọn Custom nhưng áp nét đứt cho toàn bộ khung (Box) khiến cả viền ngoài và đường dọc cũng đứt; chỉ được đứt các đường ngang bên trong.","Quên chọn Apply to: Cell hoặc chọn nhầm dòng tiêu đề nên đường ngang dưới tiêu đề cũng thành nét đứt.","Chèn ảnh nhưng để dạng In Line with Text nên ảnh nằm giữa dòng, đẩy chữ lệch, không ở góc trái.","Dùng Enter nhiều lần để tạo khoảng trống thay vì đặt Spacing Before/After.","Gõ cả dòng chú thích '(không soạn thảo nội dung này) Trang 2' của đề vào file.","Đặt tab phải vượt quá 16 cm làm đường chấm xuống dòng, hoặc quên Clear All tab cũ khiến dòng sau bị tab thừa.","Lưu nhầm tên (cau1.docx, thiếu số báo danh) hoặc nhầm thư mục."],"uncertain":["Đề ghi 'Font: Times New Roman, cỡ 13' cho toàn bài, nhưng bản mẫu trang 2 có tiêu đề 'SƠ YẾU LÝ LỊCH' chữ to hơn. Đã giả định đặt riêng tiêu đề 18 pt, phần còn lại 13 pt.","Khung 'ẢNH 4X6 (Đóng dấu giáp lai của cơ quan xác nhận lý lịch)' trong bản mẫu là một khung chữ nhỏ ở góc trái. Yêu cầu chỉ ghi 'chèn thêm ảnh vào góc trái', nên đã hướng dẫn chèn ảnh và để khung chữ làm tùy chọn.","Đường chấm trong file PDF xuất hiện lẫn dấu chấm và ký tự '…', đã chép thành '................' để thể hiện leader. Các vị trí tab cụ thể (9.5, 8.5, 16 cm, v.v.) do đo gần đúng từ hình trang 2, không phải số liệu chính thức của đề.","Dòng ghi chú chìm '(không soạn thảo nội dung này)  Trang 2' ở cuối trang 2 của đề được hiểu là chú thích, không phải nội dung soạn.","Bản mẫu tuan05.docx có lề trái 3.0 cm (khác đề 3.5 cm) và gõ sai chính tả một vài chỗ; đã làm theo đề bài (PDF), không theo bản mẫu."]},{"no":2,"app":"excel","title":"Câu 2. Tạo bảng tính (Microsoft Excel)","statement":{"intro":"Quá trình học tập môn Lập trình cơ bản của Lớp 12057623 thể hiện như bảng sau (xem bảng mẫu ở phần tài liệu). Sử dụng phần mềm Microsoft Excel tạo bảng theo dõi học tập với các yêu cầu sau:","requirements":["1) Nhập dữ liệu (giả định) cho 10 sinh viên trên các cột: TT (thứ tự), Mã SV (Mã sinh viên), Họ tên, B1 (bài tập 1), B2 (bài tập 2), B3 (Bài tập 3), L1 (Lần 1), L2 (Lần 2) , L3 (Lần 3); các cột B1, B2, B3, L1, L2, L3 nhận giá trị nguyên từ 0 đến 10. Kẻ khung, căn chỉnh, định dạng các kiểu dữ liệu cho phù hợp; Font: Times New Roman, cỡ 13pt.","2) Định dạng trang: Khổ giấy A4, Landscape; Top: 2.5, Bottom: 2.5; Left: 2.5, Right: 1.5. Căn chỉnh bảng tính ra giữa trang in (Horizontally).","3) Nhập công thức tính Điểm bài tập vào cột Đ1; Biết rằng Điểm bài tập là trung bình cộng của 3 cột B1, B2, B3. Đ1 được làm tròn 1 chữ số sau dấu phẩy.","4) Nhập công thức tính Điểm lý thuyết vào cột Đ2; Biết rằng Điểm lý thuyết là trung bình cộng của 2 lần có điểm cao nhất trong 3 lần làm bài lý thuyết. Đ2 được làm tròn 1 chữ số sau dấu phẩy.","5) Nhập công thức tính Điểm quá trình vào cột QT; Biết rằng nếu Đ1 >= 5.5 và giá trị của B1, B2, B3 không có cột nào dưới 5 thì QT = Đ1 ngược lại QT = Đ2."],"material":[{"kind":"table","caption":"Bảng mẫu theo dõi học tập môn Lập trình cơ bản, Lớp 12057623 (hai dòng tiêu đề; 'Điểm Bài tập' gộp trên B1 B2 B3, 'Điểm Lý thuyết' gộp trên L1 L2 L3; các cột TT, Mã SV, Họ tên, Đ1, Đ2, QT đều nằm trên cả hai dòng tiêu đề)","rows":[["TT","Mã SV","Họ tên","Điểm Bài tập","","","Điểm Lý thuyết","","","Đ1","Đ2","QT"],["","","","B1","B2","B3","L1","L2","L3","","",""],["1","1619001","Nguyễn Văn A","5","10","7","8","7","9","","",""],["…","…","","","","","","","","","",""]]}]},"solution":{"summary":"Dựng bảng 12 cột (A đến L) với hai dòng tiêu đề, nhập 10 dòng dữ liệu bắt đầu từ dòng 3, đặt Data Validation cho vùng điểm, định dạng font 13, kẻ khung, đặt trang in A4 ngang rồi nhập ba công thức Đ1, Đ2, QT ở dòng 3 và kéo xuống dòng 12.","steps":[{"title":"Bước 1. Tạo file và lưu đúng tên","forRequirement":"Chung (tên file)","actions":["Mở Microsoft Excel, chọn Blank workbook (Sổ làm việc trống).","Nhấn Ctrl+S, chọn D:\\ThiCC, đặt tên xyz_cau2 (xyz là số báo danh), kiểu Excel Workbook (*.xlsx), bấm Save."],"note":""},{"title":"Bước 2. Tạo cấu trúc tiêu đề bảng (hai dòng tiêu đề)","forRequirement":"1) Nhập dữ liệu, kẻ khung, căn chỉnh","actions":["Ở dòng 1 nhập: A1 = TT, B1 = Mã SV, C1 = Họ tên, D1 = Điểm Bài tập, G1 = Điểm Lý thuyết, J1 = Đ1, K1 = Đ2, L1 = QT.","Ở dòng 2 nhập: D2 = B1, E2 = B2, F2 = B3, G2 = L1, H2 = L2, I2 = L3.","Gộp ô: chọn A1:A2 > tab Home > nhóm Alignment > Merge & Center. Làm tương tự cho B1:B2, C1:C2, J1:J2, K1:K2, L1:L2 (gộp theo chiều dọc).","Gộp ô: chọn D1:F1 > Merge & Center (tiêu đề 'Điểm Bài tập'). Chọn G1:I1 > Merge & Center (tiêu đề 'Điểm Lý thuyết').","Chọn A1:L2 > Home > Alignment > Center (căn giữa ngang) và Middle Align (căn giữa dọc). Bấm Bold (Ctrl+B) cho hai dòng tiêu đề."],"note":"Dữ liệu 10 sinh viên nằm ở các dòng 3 đến 12. Bảng dùng các cột A đến L: A=TT, B=Mã SV, C=Họ tên, D:F=B1 đến B3, G:I=L1 đến L3, J=Đ1, K=Đ2, L=QT."},{"title":"Bước 3. Cài đặt kiểm tra dữ liệu: B1 đến L3 chỉ nhận số nguyên từ 0 đến 10","forRequirement":"1) các cột B1, B2, B3, L1, L2, L3 nhận giá trị nguyên từ 0 đến 10","actions":["Chọn vùng D3:I12 (10 dòng, 6 cột điểm). Tab Data > nhóm Data Tools > Data Validation > Data Validation...","Tab Settings: mục Allow chọn Whole number; mục Data chọn between; Minimum = 0; Maximum = 10.","Tab Error Alert: tích Show error alert after invalid data is entered; Style = Stop; Title = Lỗi; Error message = Chỉ nhập số nguyên từ 0 đến 10. Bấm OK.","Kiểm thử: gõ 11 hoặc 5.5 vào một ô điểm sẽ có hộp thoại báo lỗi, nhấn Cancel để bỏ."],"note":"Đề yêu cầu cột điểm nhận giá trị nguyên từ 0 đến 10; Data Validation là cách chuẩn để ràng buộc điều đó. Nếu quên làm trước khi nhập, vẫn có thể làm sau, nhưng cần tự kiểm tra các số đã nhập."},{"title":"Bước 4. Nhập dữ liệu giả định cho 10 sinh viên","forRequirement":"1) Nhập dữ liệu (giả định) cho 10 sinh viên","actions":["Nhập TT = 1 đến 10 ở A3:A12 (gõ 1, 2 rồi chọn hai ô kéo ô điều khiển Fill Handle xuống, hoặc gõ từng số).","Nhập Mã SV, Họ tên và các cột điểm theo gợi ý (có thể thay bằng dữ liệu khác, miễn là điểm nguyên từ 0 đến 10):","Dòng 3: 1 | 1619001 | Nguyễn Văn A | B1=5, B2=10, B3=7 | L1=8, L2=7, L3=9 (dòng mẫu của đề)","Dòng 4: 2 | 1619002 | Hà Xuân Định | 7, 9, 6 | 8, 6, 8","Dòng 5: 3 | 1619003 | Đỗ Đức Huy | 9, 6, 8 | 6, 7, 6","Dòng 6: 4 | 1619004 | Nguyễn Văn An | 8, 4, 9 | 9, 8, 5","Dòng 7: 5 | 1619005 | Hồ Thị Thoa | 5, 8, 4 | 6, 9, 8","Dòng 8: 6 | 1619006 | Lý Văn Nhị | 7, 5, 6 | 4, 5, 6","Dòng 9: 7 | 1619007 | Hoa Văn Thái | 8, 9, 3 | 9, 7, 4","Dòng 10: 8 | 1619008 | Cao Ngọc Tuấn | 6, 6, 7 | 8, 9, 9","Dòng 11: 9 | 1619009 | Thái Cao Văn | 8, 7, 8 | 6, 5, 8","Dòng 12: 10 | 1619010 | Ngô Tất Đoàn | 9, 8, 5 | 6, 7, 7","Mã SV 1619001... gõ như số bình thường. Nếu muốn giữ nguyên dạng mã, có thể định dạng cột B là Text trước khi nhập."],"note":"Các giá trị gợi ý trên khớp với dòng mẫu của đề (dòng 1: 5, 10, 7, 8, 7, 9) và có đủ trường hợp để kiểm thử cả hai nhánh của công thức QT."},{"title":"Bước 5. Định dạng font, căn chỉnh, định dạng kiểu số, kẻ khung","forRequirement":"1) Kẻ khung, căn chỉnh, định dạng các kiểu dữ liệu, Font Times New Roman 13pt","actions":["Nhấn Ctrl+A (chọn toàn bộ sheet). Tab Home > nhóm Font: chọn font Times New Roman, cỡ 13.","Chọn A3:B12 và D3:I12 > Home > Alignment > Center (căn giữa) cho TT, Mã SV và các cột điểm. Cột Họ tên (C3:C12) để căn trái (Align Left).","Chọn J3:L12 > nhấn Ctrl+1 (Format Cells) > tab Number > Category = Number, Decimal places = 1 > OK. Căn giữa J3:L12. Nhờ vậy 7.3, 6.0, 8.5 hiển thị đều 1 chữ số thập phân.","Chọn D3:I12 > Ctrl+1 > Number > Category = Number, Decimal places = 0 để điểm là số nguyên.","Chỉnh độ rộng cột: chọn cả cột A:L > Home > Cells > Format > AutoFit Column Width, sau đó kéo rộng cột C (Họ tên) thêm cho vừa họ tên dài nhất. Tăng chiều cao dòng tiêu đề (Format > Row Height = 22).","Kẻ khung: chọn A1:L12 > Home > nhóm Font > nút Borders (hình ô vuông chia 4) > All Borders. Có thể chọn thêm Thick Outside Borders để khung ngoài đậm hơn."],"note":"Dữ liệu kiểu số (điểm, TT) nên căn giữa hoặc phải; dữ liệu chữ (họ tên) căn trái."},{"title":"Bước 6. Định dạng trang in: A4, Landscape, lề, căn giữa trang theo chiều ngang","forRequirement":"2) Định dạng trang","actions":["Tab Page Layout > nhóm Page Setup > bấm Dialog Launcher (mũi tên nhỏ góc dưới phải) để mở hộp thoại Page Setup.","Tab Page: mục Orientation chọn Landscape (nằm ngang); mục Paper size chọn A4.","Tab Margins: Top = 2.5, Bottom = 2.5, Left = 2.5, Right = 1.5 (đơn vị cm). Trong mục Center on page tích chọn Horizontally. Giữ nguyên Header/Footer.","Bấm OK. Nhấn Ctrl+F2 (hoặc File > Print) xem trước: bảng nằm giữa trang theo chiều ngang, nằm trọn trên một trang."],"note":"Nếu hộp thoại hiển thị inch, gõ kèm 'cm' (ví dụ 2.5 cm) hoặc đổi đơn vị ở File > Options > Advanced > Display > Ruler units. Bảng 12 cột cần vừa trong một trang ngang; nếu bị tràn, giảm độ rộng cột chứ không giảm cỡ chữ."},{"title":"Bước 7. Nhập công thức cột Đ1 (điểm bài tập)","forRequirement":"3) Công thức tính Điểm bài tập vào cột Đ1","actions":["Bấm vào ô J3. Gõ: =ROUND(AVERAGE(D3:F3),1) rồi nhấn Enter.","AVERAGE(D3:F3) tính trung bình cộng 3 điểm B1, B2, B3. ROUND(...,1) làm tròn kết quả 1 chữ số sau dấu phẩy.","Chọn lại ô J3, rê chuột vào ô vuông nhỏ ở góc dưới bên phải ô (Fill Handle), kéo xuống J12 (hoặc nháy đúp) để sao chép công thức cho 10 dòng."],"note":"Nếu máy báo lỗi công thức khi dùng dấu phẩy, đổi dấu ngăn cách tham số thành dấu chấm phẩy (;). Dấu ngăn cách phụ thuộc vào Region của Windows: máy cài kiểu Việt Nam/Châu Âu thường dùng ; còn kiểu Mỹ dùng ,. Quy ước này áp dụng cho mọi công thức bên dưới."},{"title":"Bước 8. Nhập công thức cột Đ2 (điểm lý thuyết)","forRequirement":"4) Công thức tính Điểm lý thuyết vào cột Đ2","actions":["Bấm vào ô K3. Cách 1 (dùng hàm LARGE với mảng hằng): =ROUND(AVERAGE(LARGE(G3:I3,{1,2})),1) rồi Enter.","Giải thích: LARGE(G3:I3,{1,2}) trả về hai giá trị lớn nhất (lớn nhất và lớn nhì) của 3 lần thi lý thuyết L1, L2, L3. AVERAGE lấy trung bình cộng của hai giá trị đó, ROUND làm tròn 1 chữ số thập phân.","Cách 2 (không dùng mảng hằng, dễ gõ và không phụ thuộc dấu ngăn cách): =ROUND((SUM(G3:I3)-MIN(G3:I3))/2,1). Giải thích: lấy tổng 3 điểm trừ điểm thấp nhất còn lại hai điểm cao nhất, chia 2 được trung bình của hai điểm cao nhất.","Cách 3: =ROUND((LARGE(G3:I3,1)+LARGE(G3:I3,2))/2,1). Giải thích: cộng điểm cao nhất và điểm cao nhì rồi chia 2.","Chỉ cần dùng một trong ba cách. Sao chép công thức xuống K12 bằng Fill Handle."],"note":"Trên máy dùng dấu ; làm dấu ngăn cách tham số, mảng hằng có thể phải viết {1;2} thay cho {1,2}. Cách 2 và cách 3 không có vấn đề này nên khuyến nghị dùng khi đi thi."},{"title":"Bước 9. Nhập công thức cột QT (điểm quá trình)","forRequirement":"5) Công thức tính Điểm quá trình vào cột QT","actions":["Bấm vào ô L3. Gõ: =IF(AND(J3>=5.5,MIN(D3:F3)>=5),J3,K3) rồi Enter.","Giải thích: điều kiện đề cho là 'Đ1 >= 5.5 và B1, B2, B3 không có cột nào dưới 5'. J3>=5.5 kiểm tra Đ1. MIN(D3:F3)>=5 nghĩa là điểm nhỏ nhất trong B1, B2, B3 vẫn không dưới 5, tức là cả ba đều không dưới 5. AND(...) đòi cả hai điều kiện cùng đúng. Nếu đúng thì QT = Đ1 (J3), ngược lại QT = Đ2 (K3).","Cách viết khác tương đương: =IF(AND(J3>=5.5,D3>=5,E3>=5,F3>=5),J3,K3).","Sao chép công thức xuống L12 bằng Fill Handle. Các ô J3:L12 phải đã định dạng 1 chữ số thập phân (Bước 5)."],"note":""},{"title":"Bước 10. Kiểm tra kết quả và lưu bài","forRequirement":"1) đến 5)","actions":["Đối chiếu dòng mẫu của đề (5, 10, 7 | 8, 7, 9): Đ1 = 7.3, Đ2 = 8.5, QT = 7.3.","Đối chiếu với dữ liệu gợi ý: dòng 'Nguyễn Văn An' (8, 4, 9 | 9, 8, 5) có Đ1 = 7.0 nhưng B2 = 4 dưới 5 nên QT lấy Đ2 = 8.5. Dòng 'Hà Xuân Định' (7, 9, 6 | 8, 6, 8) có Đ1 = 7.3, Đ2 = 8.0, QT = 7.3.","Nhấn Ctrl+F2 xem trước khi in: bảng nằm giữa trang, 1 trang ngang A4. Lưu bằng Ctrl+S. Kiểm tra file D:\\ThiCC\\xyz_cau2.xlsx."],"note":""}],"formulas":[{"cell":"J3","formula":"=ROUND(AVERAGE(D3:F3),1)","meaning":"Đ1 = trung bình cộng của B1, B2, B3 (D3:F3), làm tròn 1 chữ số thập phân. Kéo xuống J12."},{"cell":"K3 (cách 1)","formula":"=ROUND(AVERAGE(LARGE(G3:I3,{1,2})),1)","meaning":"Đ2 = trung bình của hai điểm lý thuyết cao nhất trong L1, L2, L3. LARGE với {1,2} lấy giá trị lớn nhất và lớn nhì. Trên máy dùng ; làm dấu ngăn cách có thể phải viết {1;2}."},{"cell":"K3 (cách 2, khuyến nghị)","formula":"=ROUND((SUM(G3:I3)-MIN(G3:I3))/2,1)","meaning":"Đ2 = (tổng 3 điểm trừ điểm thấp nhất) chia 2, tức trung bình hai điểm cao nhất, không dùng mảng hằng."},{"cell":"K3 (cách 3)","formula":"=ROUND((LARGE(G3:I3,1)+LARGE(G3:I3,2))/2,1)","meaning":"Đ2 = (điểm cao nhất + điểm cao nhì) chia 2, làm tròn 1 chữ số."},{"cell":"L3","formula":"=IF(AND(J3>=5.5,MIN(D3:F3)>=5),J3,K3)","meaning":"QT = Đ1 nếu Đ1 từ 5.5 trở lên và điểm nhỏ nhất trong B1, B2, B3 không dưới 5; ngược lại QT = Đ2."},{"cell":"L3 (cách viết khác)","formula":"=IF(AND(J3>=5.5,D3>=5,E3>=5,F3>=5),J3,K3)","meaning":"Tương đương công thức trên, kiểm tra riêng từng cột B1, B2, B3 không dưới 5."}],"result":"Bảng 12 cột có hai dòng tiêu đề đã gộp ô, 10 dòng dữ liệu (dòng 3 đến 12) có khung đầy đủ, chữ Times New Roman 13. Các cột điểm B1 đến L3 là số nguyên từ 0 đến 10 (có Data Validation). Cột Đ1, Đ2, QT hiển thị 1 chữ số thập phân. Dòng mẫu của đề cho Đ1 = 7.3, Đ2 = 8.5, QT = 7.3. Với bộ dữ liệu gợi ý: Hà Xuân Định Đ1 7.3, Đ2 8.0, QT 7.3; Đỗ Đức Huy Đ1 7.7, Đ2 6.5, QT 7.7; Nguyễn Văn An Đ1 7.0, Đ2 8.5, QT 8.5 (vì B2 = 4); Hồ Thị Thoa Đ1 5.7, Đ2 8.5, QT 8.5 (vì B3 = 4); Lý Văn Nhị Đ1 6.0, Đ2 5.5, QT 6.0; Hoa Văn Thái Đ1 6.7, Đ2 8.0, QT 8.0 (vì B3 = 3). Trang in A4 ngang, lề 2.5/2.5/2.5/1.5 cm, bảng nằm giữa trang theo chiều ngang. Tự kiểm tra bằng cách bấm vào ô công thức xem tham chiếu đúng dòng và xem Ctrl+F2."},"checklist":["File lưu tại D:\\ThiCC với tên xyz_cau2.xlsx","Có đủ các cột TT, Mã SV, Họ tên, B1, B2, B3, L1, L2, L3, Đ1, Đ2, QT; tiêu đề 'Điểm Bài tập' và 'Điểm Lý thuyết' gộp ô phía trên","Có dữ liệu cho 10 sinh viên","Các cột B1, B2, B3, L1, L2, L3 chỉ chứa số nguyên từ 0 đến 10 (có Data Validation)","Toàn bảng có khung, căn chỉnh hợp lý, font Times New Roman cỡ 13","Giấy A4, Landscape, lề Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 cm","Đã tích Horizontally trong Center on page","Đ1 dùng ROUND(AVERAGE(...),1) trên D:F","Đ2 là trung bình của hai điểm cao nhất trong G:I và làm tròn 1 chữ số","QT dùng IF + AND + MIN đúng điều kiện Đ1 >= 5.5 và B1, B2, B3 không dưới 5","Ba cột Đ1, Đ2, QT có công thức ở cả 10 dòng, hiển thị 1 chữ số thập phân","Dòng mẫu 5, 10, 7 | 8, 7, 9 cho Đ1 = 7.3, Đ2 = 8.5, QT = 7.3"],"commonMistakes":["Quên ROUND mà chỉ giảm số chữ số thập phân hiển thị (giá trị thực vẫn dài, sẽ sai khi so sánh Đ1 >= 5.5).","Làm tròn nhầm 0 hoặc 2 chữ số thay vì 1.","Tính Đ2 bằng trung bình của cả ba lần thi hoặc lấy lần thi cuối, thay vì trung bình hai lần cao nhất.","Dùng mảng hằng {1,2} trên máy dùng dấu ; làm dấu ngăn cách nên báo lỗi công thức; nên dùng cách (SUM-MIN)/2 hoặc LARGE(...,1)+LARGE(...,2).","Viết sai điều kiện QT: dùng Đ1 > 5.5 thay vì >= 5.5, hoặc dùng MIN(D3:F3)>5 thay vì >=5 (đề nói 'không dưới 5').","Dùng OR thay cho AND làm QT lấy Đ1 sai ở những sinh viên có một bài dưới 5.","Tham chiếu sai dòng khi kéo công thức (ví dụ sao chép công thức dòng 3 sang bảng khác khiến tham chiếu D1 lệch). File mẫu tuan05.xlsx (Sheet2, bảng thứ hai) có lỗi này: công thức QT tham chiếu D1, D2... thay vì D18, D19...","Dùng ngưỡng 5 cho Đ1 thay vì 5.5 (file mẫu Book2.xlsx dùng J3>=5, khác với đề).","Nhập điểm có phần thập phân hoặc ngoài khoảng 0 đến 10, hoặc nhập điểm dưới dạng text (ô hiện dấu tam giác xanh).","Quên đặt Landscape, nhập sai lề, hoặc quên tích Horizontally; bảng bị tràn sang trang thứ hai.","Quên đặt font Times New Roman 13 cho toàn sheet, chỉ đặt cho vùng dữ liệu."],"uncertain":["Đề cho dữ liệu 'giả định' cho 10 sinh viên nên bộ dữ liệu trong hướng dẫn chỉ là gợi ý, riêng dòng 1 lấy theo dòng mẫu của đề (1619001, Nguyễn Văn A, 5 10 7 8 7 9).","Đề yêu cầu 'Top: 2.5, Bottom: 2.5; Left: 2.5, Right: 1.5' không ghi đơn vị; giả định là cm.","Cấu trúc hai dòng tiêu đề (gộp ô 'Điểm Bài tập' trên B1 B2 B3 và 'Điểm Lý thuyết' trên L1 L2 L3) lấy theo bảng mẫu trong đề và theo file mẫu tuan05.xlsx; cột Đ1, Đ2, QT đặt sau L3.","Công thức Đ2 bằng cách trừ điểm nhỏ nhất rồi chia 2 cho kết quả giống 'trung bình hai lần cao nhất' kể cả khi có hai điểm bằng nhau.","File mẫu Book2.xlsx dùng điều kiện J3>=5 (không phải 5.5) và dòng tiêu đề có thêm cột; đã làm theo đề bài (>= 5.5), không theo Book2.xlsx. Sheet2 của tuan05.xlsx có bảng thứ hai với công thức QT tham chiếu sai ô, không dùng làm chuẩn.","Việc dùng Data Validation (0 đến 10, số nguyên) là cách đề xuất để thỏa 'nhận giá trị nguyên từ 0 đến 10'; đề không nêu rõ phải dùng công cụ nào."]},{"no":3,"app":"powerpoint","title":"Câu 3. Tạo các trang trình chiếu (Microsoft PowerPoint)","statement":{"intro":"Sử dụng phần mềm Microsoft PowerPoint hãy thiết kế 05 slides trình bày về Danh lam thắng cảnh Hà Nội. Trong các slide không được chứa thông tin liên quan đến thí sinh:","requirements":["1) Đánh số trang cho các slide (trừ slide đầu tiên).","2) Trong Master Slide, điều chỉnh tất cả font chữ về Arial, nội dung căn chỉnh 2 bên.","3) Tạo mới và sử dụng ít nhất 02 layout cho bài trình chiếu.","4) Sử dụng ít nhất 02 hiệu ứng hoạt hình (Animation).","5) Sử dụng ít nhất 02 hiệu ứng chuyển slide (Transition)."],"material":[]},"solution":{"summary":"Làm Slide Master trước (đổi font Arial, căn đều hai bên, tạo 2 layout mới), sau đó tạo 5 slide dùng các layout đó, bật đánh số trang với 'Don't show on title slide', rồi gán animation và transition.","steps":[{"title":"Bước 1. Tạo file, lập 5 slide và lưu đúng tên","forRequirement":"Chung; Yêu cầu '05 slides'","actions":["Mở Microsoft PowerPoint, chọn Blank Presentation. Nhấn Ctrl+S, chọn D:\\ThiCC, đặt tên xyz_cau3, kiểu PowerPoint Presentation (*.pptx), bấm Save.","Tab Home > nhóm Slides > New Slide để thêm slide cho đủ đúng 5 slide (slide đầu là Title Slide).","Lưu ý: trong cả 5 slide tuyệt đối không gõ họ tên, số báo danh, lớp hoặc bất kỳ thông tin thí sinh nào (kể cả trong Footer)."],"note":"Nên làm Bước 2 đến Bước 4 (Slide Master và layout) trước khi nhập nội dung để các slide kế thừa đúng font và căn chỉnh."},{"title":"Bước 2. Slide Master: đổi toàn bộ font chữ về Arial","forRequirement":"2) Trong Master Slide, điều chỉnh tất cả font chữ về Arial","actions":["Tab View > nhóm Master Views > Slide Master để vào chế độ chỉnh Slide Master. Ở khung bên trái, bấm vào slide to nhất trên cùng (Slide Master, các slide con phía dưới là layout).","Tab Slide Master > nhóm Edit Theme > Fonts (hộp thả xuống có chữ Aa) > kéo xuống chọn Customize Fonts...","Trong hộp thoại Create New Theme Fonts: Heading font = Arial, Body font = Arial. Ở ô Name gõ 'Arial' > bấm Save. Từ lúc này font chủ đề (Heading và Body) đều là Arial cho toàn bộ master và mọi layout.","Kiểm tra: bấm vào từng khung trên Slide Master (tiêu đề, nội dung, ngày tháng, chân trang, số trang). Hộp Font ở Home hiển thị 'Arial (Headings)' hoặc 'Arial (Body)', không còn Calibri hay font khác. Nếu có chữ nào đặt font riêng (không phải font chủ đề), chọn khung đó và chọn lại Arial."],"note":"Đề yêu cầu 'tất cả font chữ về Arial', nên đổi ở Slide Master chứ không đổi tay từng slide. Hộp văn bản (Text Box) tự thêm sau này cũng dùng font Body của chủ đề nên là Arial."},{"title":"Bước 3. Slide Master: căn đều hai bên (Justify) cho nội dung","forRequirement":"2) nội dung căn chỉnh 2 bên","actions":["Vẫn ở Slide Master (bấm vào slide master trên cùng). Bấm vào đường viền của khung nội dung 'Click to edit Master text styles' để chọn cả khung (không chọn chữ bên trong).","Tab Home > nhóm Paragraph > bấm Justify (hoặc nhấn Ctrl+J). Nút Justify nằm cạnh nút Align Text Right. Thao tác này áp dụng cho cả 5 cấp gạch đầu dòng của khung.","Bấm vào từng layout con sẽ dùng (Title Slide, Title and Content và các layout mới tạo ở Bước 4), chọn khung nội dung/văn bản của layout đó và kiểm tra nút Justify sáng. Nếu layout bị ghi đè căn trái, chọn khung > Ctrl+J.","Tiêu đề (Title) có thể để căn giữa hoặc căn trái như mặc định; phần 'nội dung' mới cần căn đều hai bên."],"note":"Layout Title Slide có phụ đề (subtitle) căn giữa theo mặc định; nếu muốn chắc chắn, chọn khung phụ đề trên layout Title Slide và đặt Justify. Hộp văn bản chèn thủ công (Insert > Text Box) không theo master nên nhớ nhấn Ctrl+J cho từng hộp."},{"title":"Bước 4. Tạo mới ít nhất 02 layout trong Slide Master","forRequirement":"3) Tạo mới và sử dụng ít nhất 02 layout","actions":["Ở Slide Master view, bấm vào layout cuối cùng trong khung trái (hoặc bấm vào Slide Master). Tab Slide Master > nhóm Edit Master > Insert Layout. Một layout mới xuất hiện.","Đổi tên layout: bấm chuột phải vào layout mới > Rename Layout... > gõ 'Hình và mô tả' > Rename. Trong tab Slide Master > nhóm Master Layout > Insert Placeholder, bấm vào mũi tên để thêm khung: chọn Picture (kéo vẽ khung bên trái slide) và Text (kéo vẽ khung bên phải slide). Tiêu đề (Title) có sẵn ở trên.","Chèn thêm layout thứ hai: Insert Layout lần nữa. Đổi tên 'Tiêu đề và nội dung 2 cột'. Thêm Insert Placeholder > Content (hai khung nội dung bên trái và bên phải), hoặc Content và Text. Chỉnh kích thước các khung bằng cách kéo viền.","Với mỗi layout mới: chọn khung văn bản và nhấn Ctrl+J (Justify) nếu chưa có. Đảm bảo tab Slide Master > nhóm Master Layout có tích chọn Footers (Date, Footer, Slide Number) để layout có khung đánh số trang.","Bấm Close Master View (tab Slide Master > nhóm Close) để thoát về chế độ thường."],"note":"Đề ghi 'Tạo mới và sử dụng ít nhất 02 layout'. Để an toàn: vừa tạo 2 layout mới trong Slide Master, vừa dùng ít nhất 2 layout khác nhau trong bài (xem Bước 5). Ở file mẫu tuan05.pptx chỉ dùng layout có sẵn (Title Slide, Title and Content, Content with Caption)."},{"title":"Bước 5. Áp dụng layout cho các slide và soạn nội dung","forRequirement":"3) sử dụng ít nhất 02 layout; yêu cầu 05 slide về Danh lam thắng cảnh Hà Nội","actions":["Slide 1: chọn slide 1 > Home > Layout > Title Slide. Tiêu đề: 'Danh lam thắng cảnh Hà Nội'. Phụ đề gợi ý: 'Thủ đô nghìn năm văn hiến'. Không ghi tên thí sinh.","Slide 2 (Hồ Hoàn Kiếm): Home > Layout > chọn layout mới 'Hình và mô tả'. Tiêu đề 'Hồ Hoàn Kiếm'. Gợi ý nội dung: nằm ở trung tâm Hà Nội; Tháp Rùa trên đảo nhỏ giữa hồ; cầu Thê Húc dẫn vào đền Ngọc Sơn; gắn với truyền thuyết vua Lê Lợi trả gươm thần. Chèn ảnh vào khung Picture (bấm biểu tượng ảnh trong khung hoặc Insert > Picture).","Slide 3 (Văn Miếu - Quốc Tử Giám): layout 'Hình và mô tả'. Gợi ý: xây dựng năm 1070 dưới thời vua Lý Thánh Tông; Quốc Tử Giám lập năm 1076, được xem là trường đại học đầu tiên của Việt Nam.","Slide 4 (Chùa Một Cột): layout 'Tiêu đề và nội dung 2 cột'. Gợi ý: xây dựng năm 1049 dưới thời vua Lý Thái Tông; kiến trúc giống đóa sen nở trên mặt nước; là biểu tượng của Thủ đô.","Slide 5 (Lăng Chủ tịch Hồ Chí Minh): layout 'Tiêu đề và nội dung 2 cột'. Gợi ý: nằm ở Quảng trường Ba Đình; khánh thành năm 1975; nơi đặt thi hài Chủ tịch Hồ Chí Minh.","Cách đổi layout cho slide đã tạo: chọn slide ở khung bên trái, bấm chuột phải > Layout > chọn layout, hoặc Home > Layout.","Chèn ảnh minh họa nếu có sẵn trên máy (Insert > Picture). Nếu không có ảnh, có thể dùng Insert > Shapes hoặc Clip Art; ảnh không phải là yêu cầu bắt buộc của đề."],"note":"Nội dung 5 slide về danh lam thắng cảnh là gợi ý để tham khảo; đề chỉ yêu cầu 5 slide về chủ đề Danh lam thắng cảnh Hà Nội, có thể chọn địa danh khác (Hồ Tây, Hoàng thành Thăng Long, Nhà thờ Lớn...). Không đưa thông tin thí sinh vào bất cứ slide nào."},{"title":"Bước 6. Đánh số trang cho các slide, trừ slide đầu tiên","forRequirement":"1) Đánh số trang cho các slide (trừ slide đầu tiên)","actions":["Tab Insert > nhóm Text > Header & Footer. Trong hộp thoại, chọn tab Slide.","Tích chọn Slide number. Tích chọn Don't show on title slide (không hiển thị trên slide tiêu đề).","Bấm Apply to All (không bấm Apply). Slide 1 (dùng layout Title Slide) sẽ không hiện số; slide 2 hiện số 2, slide 3 hiện 3, và tiếp tục.","Kiểm tra từng slide: slide 1 không có số trang; slide 2 đến 5 có số trang ở góc dưới bên phải.","Nếu slide 1 vẫn hiện số (do không dùng layout Title Slide): chọn slide 1 > Insert > Header & Footer > bỏ tích Slide number > bấm Apply (không bấm Apply to All).","Nếu slide dùng layout mới không hiện số: vào Slide Master view, chọn layout đó, tab Slide Master > tích chọn Footers hoặc bấm Insert Placeholder > Slide Number rồi đặt khung này cùng vị trí như các layout khác."],"note":"Hộp 'Don't show on title slide' chỉ có tác dụng với slide dùng layout Title Slide. Trong phần Footer đừng gõ tên hoặc số báo danh."},{"title":"Bước 7. Thêm ít nhất 02 hiệu ứng hoạt hình (Animation)","forRequirement":"4) Sử dụng ít nhất 02 hiệu ứng hoạt hình","actions":["Chọn slide 2. Bấm chọn khung tiêu đề (hoặc hình ảnh). Tab Animations > nhóm Animation > chọn hiệu ứng Fade (hoặc Fly In, Appear). Đây là hiệu ứng thứ nhất.","Chọn đối tượng thứ hai (ví dụ khung nội dung hoặc ảnh) trong cùng slide. Tab Animations > chọn hiệu ứng khác như Wipe, Zoom hoặc Fly In. Đây là hiệu ứng thứ hai.","Nếu muốn hiệu ứng thứ hai chạy tự động: tab Animations > nhóm Timing > Start = After Previous (hoặc With Previous), Duration khoảng 0.50 đến 1.00 giây.","Làm thêm tương tự cho các slide 3 hoặc 4 (ví dụ chọn ảnh > Zoom, chọn khung chữ > Fly In) để chắc chắn có từ 2 hiệu ứng trở lên.","Kiểm tra: tab Animations > Animation Pane, danh sách hiện các hiệu ứng đã gán. Trên slide, các đối tượng có hiệu ứng có số thứ tự nhỏ ở bên trái. Nhấn Preview để xem thử."],"note":"Mỗi đối tượng có hiệu ứng riêng thì mới được tính là đã gán hiệu ứng. Để hai hiệu ứng trên hai đối tượng khác nhau thì dễ kiểm tra hơn."},{"title":"Bước 8. Thêm ít nhất 02 hiệu ứng chuyển slide (Transition)","forRequirement":"5) Sử dụng ít nhất 02 hiệu ứng chuyển slide","actions":["Chọn slide 2 ở khung trái. Tab Transitions > nhóm Transition to This Slide > chọn Fade.","Chọn slide 3 > Transitions > chọn Push (hoặc Wipe). Chọn slide 4 > Transitions > chọn Cover hoặc Split.","Nên dùng ít nhất 2 kiểu khác nhau (ví dụ Fade, Push, Wipe) trên các slide khác nhau; không dùng Apply To All nếu muốn các kiểu khác nhau.","Kiểm tra: ở khung trái các slide có chuyển trang sẽ có ngôi sao nhỏ phía dưới số thứ tự slide. Bấm Preview hoặc F5 để xem."],"note":"Có thể đặt thêm Transition cho slide 1 (ví dụ Fade). Mục Duration ở nhóm Timing để mặc định hoặc 1 giây."},{"title":"Bước 9. Kiểm tra toàn bộ và lưu bài","forRequirement":"1) đến 5)","actions":["Nhấn F5 để chạy trình chiếu từ slide 1: kiểm tra có đủ 5 slide, hiệu ứng, chuyển trang, số trang (không có trên slide 1) và không có thông tin thí sinh.","Vào View > Slide Sorter để thấy cả 5 slide cùng lúc; kiểm tra biểu tượng chuyển trang và số thứ tự.","Vào View > Slide Master một lần nữa kiểm tra: font Arial, các layout mới tạo vẫn còn trong danh sách. Close Master View.","Nhấn Ctrl+S để lưu. Kiểm tra file D:\\ThiCC\\xyz_cau3.pptx."],"note":"Có thể xóa thông tin tác giả trong file: File > Info > Properties, xóa tên tác giả, để file cũng không chứa thông tin thí sinh (tùy chọn)."}],"formulas":[],"result":"File xyz_cau3.pptx có đúng 5 slide về danh lam thắng cảnh Hà Nội: slide 1 là tiêu đề (không có số trang), slide 2 đến 5 có số trang 2 đến 5 ở góc. Trong Slide Master font chủ đề là Arial và khung nội dung căn đều hai bên; có ít nhất 2 layout mới (ví dụ 'Hình và mô tả', 'Tiêu đề và nội dung 2 cột') đang được các slide sử dụng. Có ít nhất 2 hiệu ứng Animation (xem trong Animation Pane) và ít nhất 2 hiệu ứng Transition khác nhau (có biểu tượng ngôi sao ở khung trái). Không slide nào chứa tên hay số báo danh thí sinh. Tự kiểm tra bằng F5 và View > Slide Sorter."},"checklist":["File lưu tại D:\\ThiCC với tên xyz_cau3.pptx","Bài có đúng 5 slide về Danh lam thắng cảnh Hà Nội","Không slide nào chứa thông tin thí sinh (họ tên, số báo danh, lớp...)","Slide 1 không có số trang; các slide 2 đến 5 có số trang","Font chủ đề trong Slide Master (Heading và Body) là Arial; không còn font khác trên master","Khung nội dung trong Slide Master (và các layout dùng) được căn đều hai bên (Justify)","Có ít nhất 2 layout mới tạo qua Insert Layout trong Slide Master","Các slide thực sự dùng ít nhất 2 layout khác nhau","Có ít nhất 2 hiệu ứng Animation (Animation Pane liệt kê)","Có ít nhất 2 hiệu ứng Transition (khuyến nghị kiểu khác nhau)"],"commonMistakes":["Đổi font từng slide thay vì đổi ở Slide Master; hoặc chỉ đổi font tiêu đề mà quên font nội dung.","Áp dụng Justify cho một đoạn văn bản trên slide chứ không phải trong Slide Master.","Chọn 'Apply' thay vì 'Apply to All' khi đánh số trang nên chỉ một slide có số; hoặc quên tích 'Don't show on title slide' nên slide 1 vẫn hiện số 1.","Slide 1 không dùng layout Title Slide nên 'Don't show on title slide' không có tác dụng.","Layout tự tạo không có khung Slide Number nên slide dùng layout đó không hiện số trang.","Chỉ chọn layout có sẵn (Title and Content...) mà không tạo layout mới (Insert Layout) trong Slide Master.","Chỉ có một hiệu ứng hoặc chỉ dùng Transition 'Apply To All' cùng một kiểu rồi tưởng là hai hiệu ứng.","Ghi tên, số báo danh hoặc lớp vào slide đầu hoặc vào Footer.","Gõ sai chính tả các địa danh (ví dụ 'Chùa Một Cột', 'Văn Miếu - Quốc Tử Giám'); file mẫu tuan05.pptx có nhiều lỗi chính tả nên cần soát lại.","Lưu nhầm định dạng (.ppt hoặc .pptm) hoặc nhầm tên, nhầm thư mục."],"uncertain":["Đề không nêu danh lam thắng cảnh cụ thể nào, nên nội dung các slide trong hướng dẫn chỉ là gợi ý (Hồ Hoàn Kiếm, Văn Miếu - Quốc Tử Giám, Chùa Một Cột, Lăng Chủ tịch Hồ Chí Minh). File mẫu tuan05.pptx dùng Bảo tàng Hà Nội, Chùa Một Cột, Lăng Chủ tịch Hồ Chí Minh.","Câu 'Tạo mới và sử dụng ít nhất 02 layout' có thể hiểu là tạo layout mới trong Slide Master hoặc dùng ít nhất 2 layout khác nhau; hướng dẫn thực hiện cả hai để đảm bảo. File mẫu tuan05.pptx chỉ dùng layout có sẵn (Title Slide, Title and Content, Content with Caption).","'Nội dung căn chỉnh 2 bên' được hiểu là căn đều hai bên (Justify) cho khung nội dung/văn bản trong Slide Master; không áp dụng cho tiêu đề.","'Đánh số trang (trừ slide đầu tiên)': hiểu là slide 1 không hiển thị số, các slide sau hiển thị số thứ tự thật của slide (2, 3, 4, 5). File mẫu tuan05.pptx đánh số slide 2 là 1 (số gõ tay) nên không dùng làm chuẩn.","Đề yêu cầu 'ít nhất 02 hiệu ứng hoạt hình' và 'ít nhất 02 hiệu ứng chuyển slide' nhưng không nêu loại hiệu ứng cụ thể; các hiệu ứng nêu trong hướng dẫn (Fade, Wipe, Zoom, Push...) chỉ là gợi ý."]}]},{"id":6,"title":"Đề thực hành số 6","source":"de co ban 6","timeLimitMinutes":null,"generalNotes":["Đề thi thực hành (Học viện Kỹ thuật Quân sự), trưởng ban đề thi TS Hoa Tất Thắng, giáo viên ra đề TS Nguyễn Văn Giang.","Đề thi gồm 2 trang; không được sử dụng tài liệu, USB và các thiết bị lưu trữ khác.","Các file bài làm để trong thư mục E:\\ThiCC với cách đặt tên: Câu 1: xyz_cau1.docx; Câu 2: xyz_cau2.xlsx; Câu 3: xyz_cau3.pptx.","Trong đó xyz là số báo danh của thí sinh.","Thời gian làm bài không ghi trên đề."],"tasks":[{"no":1,"app":"word","title":"Câu 1. Soạn thảo văn bản (Microsoft Word)","statement":{"intro":"Sử dụng phần mềm Microsoft Word soạn thảo một tài liệu (khoảng 5 trang) gồm các nội dung sau:","requirements":["Nội dung tài liệu: 1) Trang đầu: Phần Mục lục (01 trang). 2) Từ trang 2 trở đi, trình bày các chương và đề mục, các chương đứng đầu trang. 3) Trang cuối: Tài liệu tham khảo (khoảng 4 tài liệu, bố trí trên 01 trang).","Yêu cầu 1) Đánh số trang ở chính giữa phía trên.","Yêu cầu 2) Các đầu mục, tính cả đầu chương được phân cấp tới Heading 3.","Yêu cầu 3) Mục lục: Dùng mục lục tự động. Mục lục căn chỉnh theo hai bên.","Yêu cầu 4) Tham chiếu đến tài liệu tham khảo: Tự động cập nhật khi có thay đổi.","Yêu cầu 5) Định dạng trang: Giấy A4 Portrait; Header: 1.3cm; Footer: 1.3cm; Top: 2.5 cm, Bottom: 2.2 cm; Left: 3.5 cm; Right: 1.5 cm. Font chữ Times New Roman, cỡ 13pt.","Chú ý: Phần nội dung, tên chương, mục có thể tự chọn nội dung tùy ý."],"material":[]},"solution":{"summary":"Thiết lập trang và style (Normal, Heading 1-3) trước, rồi soạn nội dung theo cấu trúc Mục lục, các chương (mỗi chương bắt đầu một trang mới), Tài liệu tham khảo. Sau đó chèn số trang trên giữa, tạo mục lục tự động tới Heading 3, tạo danh sách tài liệu tham khảo có đánh số tự động và dùng Cross-reference để trích dẫn.","steps":[{"title":"Bước 0: Mở file mới và đặt đơn vị đo là cm","forRequirement":"Chuẩn bị","actions":["Mở Word, chọn Blank document (Ctrl+N).","Nếu thước và hộp thoại đang dùng Inches: File > Options > Advanced > kéo xuống mục Display > ô 'Show measurements in units of' chọn Centimeters > OK.","Lưu ngay: File > Save As > chọn thư mục E:\\ThiCC > đặt tên xyz_cau1.docx (xyz là số báo danh) > Save. Trong lúc làm nhớ bấm Ctrl+S thường xuyên."],"note":"Nếu thư mục E:\\ThiCC chưa có thì tạo mới thư mục ThiCC trong ổ E rồi lưu vào đó."},{"title":"Bước 1: Định dạng trang (khổ giấy, lề, Header/Footer)","forRequirement":"Yêu cầu 5","actions":["Tab Layout (Word 2010 là Page Layout) > nhóm Page Setup > bấm nút mũi tên nhỏ ở góc dưới bên phải nhóm (Dialog Launcher) để mở hộp thoại Page Setup.","Thẻ Margins: nhập Top = 2.5 cm; Bottom = 2.2 cm; Left = 3.5 cm; Right = 1.5 cm; Gutter = 0 cm; Orientation chọn Portrait; Apply to: Whole document.","Thẻ Paper: ô Paper size chọn A4 (21 cm x 29.7 cm).","Thẻ Layout: mục From edge nhập Header = 1.3 cm và Footer = 1.3 cm. Không tick Different first page (để trang 1 cũng có số trang).","Bấm OK."],"note":"Nếu máy hiện số kiểu 0.98\" thì chưa đổi sang cm (xem Bước 0). Nên làm bước này đầu tiên để số trang không bị lệch về sau."},{"title":"Bước 2: Đặt font Times New Roman 13pt cho toàn tài liệu qua style Normal","forRequirement":"Yêu cầu 5","actions":["Tab Home > nhóm Styles > bấm chuột phải vào style Normal > Modify...","Trong hộp thoại Modify Style: ô font chọn Times New Roman, ô cỡ chọn 13 > OK.","Khi đó mọi đoạn văn bản thường sẽ là Times New Roman 13pt. Có thể chỉnh thêm cho đẹp: Format > Paragraph... > Line spacing: 1.5 lines, Special: First line 1 cm, Alignment: Justified.","Với từng style tiêu đề (bước tiếp theo) cũng phải đổi font sang Times New Roman vì mặc định là Calibri Light hoặc Cambria."],"note":"Đề yêu cầu cỡ 13pt cho toàn bộ chữ. Để chắc điểm, giữ cả tiêu đề ở 13pt và phân biệt bằng In đậm, IN HOA, in nghiêng chứ không tăng cỡ."},{"title":"Bước 3: Chỉnh style Heading 1, Heading 2, Heading 3 (phân cấp tới Heading 3)","forRequirement":"Yêu cầu 2","actions":["Tab Home > nhóm Styles > bấm chuột phải Heading 1 > Modify... > Font: Times New Roman, 13, Bold, màu Black (Automatic) > Format > Paragraph...: Alignment Left, Spacing Before 12 pt, After 6 pt; thẻ Line and Page Breaks tick Page break before (để mỗi chương luôn đứng đầu trang mới) > OK > OK.","Làm tương tự với Heading 2: Times New Roman, 13, Bold; không tick Page break before.","Làm tương tự với Heading 3: Times New Roman, 13, Bold + Italic (hoặc chỉ Italic); không tick Page break before.","Nếu bảng Styles không hiện Heading 2, Heading 3 thì bấm Dialog Launcher của nhóm Styles (hoặc Ctrl+Alt+Shift+S) > Options > Select styles to show: All styles."],"note":"Heading 1 là cấp chương, Heading 2 là mục (1.1), Heading 3 là tiểu mục (1.1.1). Dùng Page break before cho Heading 1 là cách chuẩn hơn gõ Ctrl+Enter vì nó tự áp dụng cho chương mới sau này."},{"title":"Bước 4: Đánh số tự động cho chương và mục (Multilevel List nối với Heading)","forRequirement":"Yêu cầu 2 (bước nên làm)","actions":["Đặt con trỏ vào một đoạn bất kỳ. Tab Home > nhóm Paragraph > nút Multilevel List > Define New Multilevel List...","Bấm nút More >> ở góc dưới trái để mở rộng hộp thoại.","Chọn Level 1 bên trái: ô 'Enter formatting for number' gõ 'Chương ' trước số 1 (có nền xám, giữ nguyên) để thành Chương 1; ô 'Link level to style' chọn Heading 1; Number style chọn 1, 2, 3.","Chọn Level 2: 'Link level to style' chọn Heading 2; nội dung ô formatting là 1.1 (Word tự lấy số cấp 1, dấu chấm, số cấp 2). Chọn Level 3: link tới Heading 3, hiển thị 1.1.1.","Bấm OK. Từ nay mỗi khi áp dụng Heading 1, 2, 3 sẽ tự có số Chương 1, 1.1, 1.1.1."],"note":"Nếu thấy phức tạp, trong phòng thi có thể gõ tay số thứ tự vào tiêu đề (ví dụ 'Chương 1. TỔNG QUAN', '1.1. Khái niệm'). Cách tự động vẫn tốt hơn."},{"title":"Bước 5: Soạn bố cục tài liệu (trang Mục lục, các chương, trang Tài liệu tham khảo)","forRequirement":"Nội dung 1, 2, 3","actions":["Trang 1: gõ dòng 'MỤC LỤC' (căn giữa, in đậm, KHÔNG áp dụng style Heading để không tự lọt vào mục lục), nhấn Enter vài lần để chừa chỗ cho mục lục (sẽ chèn ở Bước 9).","Tạo Chương 1: nhấn Enter để xuống dòng mới, gõ tên chương, ví dụ 'TỔNG QUAN VỀ ỨNG DỤNG CÔNG NGHỆ THÔNG TIN', bôi đen dòng này rồi Home > Styles > bấm Heading 1 (hoặc Ctrl+Alt+1). Do Heading 1 đã bật Page break before nên chương tự nhảy sang trang 2.","Gõ đề mục con, ví dụ 'Khái niệm cơ bản' > áp Heading 2 (Ctrl+Alt+2); gõ 'Vai trò' > áp Heading 3 (Ctrl+Alt+3). Dưới mỗi đề mục gõ 2 đến 3 đoạn văn thường (style Normal). Muốn có văn bản mẫu nhanh, gõ =lorem(3,5) rồi Enter để Word tự sinh 3 đoạn, mỗi đoạn 5 câu.","Tạo Chương 2, Chương 3 theo cách tương tự (mỗi chương có ít nhất một Heading 2 và một Heading 3, chiếm khoảng 1 trang mỗi chương). Gợi ý cấu trúc: Chương 1 Tổng quan (1.1, 1.1.1, 1.2); Chương 2 Nội dung chính (2.1, 2.1.1, 2.2); Chương 3 Ứng dụng và kết luận (3.1, 3.2).","Cuối cùng gõ tiêu đề 'TÀI LIỆU THAM KHẢO' và áp Heading 1 để lọt vào mục lục. Nếu đã bật đánh số Chương tự động thì đặt con trỏ vào tiêu đề này > Home > Paragraph > Multilevel List > None để bỏ chữ 'Chương' (hoặc bấm nút Numbering để tắt số).","Tổng cộng khoảng 5 trang: trang 1 Mục lục, trang 2 đến 4 là 3 chương, trang 5 Tài liệu tham khảo."],"note":"Mỗi chương phải bắt đầu ở đầu một trang mới. Nếu chương dài hơn một trang thì tổng số trang vượt 5, không sao nhưng nên giữ khoảng 5 trang."},{"title":"Bước 6: Soạn danh sách Tài liệu tham khảo (đánh số tự động [1], [2], ...)","forRequirement":"Yêu cầu 4 (chuẩn bị)","actions":["Dưới tiêu đề TÀI LIỆU THAM KHẢO, gõ 4 tài liệu, mỗi tài liệu một dòng (Enter giữa các dòng), ví dụ: Nguyễn Văn A, Giáo trình Tin học cơ bản, NXB Giáo dục, 2020. / Trần Thị B, Microsoft Office 2016, NXB Thống kê, 2018. / Lê Văn C, Ứng dụng công nghệ thông tin, NXB Khoa học và Kỹ thuật, 2019. / Phạm Văn D, Kỹ năng sử dụng máy tính, NXB Đại học Quốc gia, 2021.","Bôi đen 4 dòng đó. Tab Home > nhóm Paragraph > bấm mũi tên cạnh nút Numbering > Define New Number Format... > ô 'Number style' chọn 1, 2, 3; ô 'Number format' sửa thành [1] (giữ số 1 có nền xám, thêm hai dấu ngoặc vuông quanh nó) > Alignment Left > OK.","Khi đó bốn dòng có số [1], [2], [3], [4] là danh sách đánh số tự động. Đảm bảo cả 4 tài liệu nằm gọn trên 1 trang (trang 5)."],"note":""},{"title":"Bước 7: Tạo tham chiếu tự động đến tài liệu tham khảo (Cross-reference)","forRequirement":"Yêu cầu 4","actions":["Trong phần nội dung một chương (ví dụ Chương 1), đặt con trỏ ngay sau câu cần trích dẫn, ví dụ sau cụm 'Theo giáo trình tin học cơ bản ' (gõ một dấu cách).","Tab Insert > nhóm Links > Cross-reference.","Trong hộp thoại Cross-reference: ô Reference type chọn Numbered item; ô Insert reference to chọn Paragraph number (hoặc Paragraph number (no context)); tick Insert as hyperlink; ở danh sách bên dưới chọn tài liệu [1] > bấm Insert > Close.","Kết quả hiện số [1] trong câu văn, nền xám khi click vào (đó là một trường tham chiếu). Lặp lại để chèn thêm [2], [3] ở vài vị trí khác trong các chương.","Kiểm tra tự động cập nhật: thêm hoặc xóa một tài liệu trong danh sách tham khảo, rồi bấm Ctrl+A (chọn tất cả) > F9 (Update Field). Các số tham chiếu trong bài thay đổi theo. Có thể bật thêm: File > Options > Display > tick 'Update fields before printing'."],"note":"Cách khác cũng chấp nhận: dùng References > Insert Citation và Bibliography. Nhưng Cross-reference tới Numbered item là cách đơn giản và hay dùng nhất. Không gõ tay [1] vì khi danh sách đổi thì số không cập nhật."},{"title":"Bước 8: Đánh số trang ở chính giữa phía trên","forRequirement":"Yêu cầu 1","actions":["Tab Insert > nhóm Header & Footer > Page Number > Top of Page > chọn kiểu Plain Number 2 (số ở giữa).","Word chuyển sang chế độ chỉnh Header. Kiểm tra số trang nằm chính giữa, font Times New Roman 13 (nếu không, bôi đen số và đặt lại font).","Bấm Close Header and Footer (hoặc nháy đúp vào vùng thân văn bản) để thoát.","Nếu ở Bước 1 đã tick Different first page thì bỏ tick đó để trang đầu cũng có số."],"note":"Nếu không muốn số trang xuất hiện trên trang Mục lục thì tick Different First Page, nhưng đề không yêu cầu nên để tất cả các trang đều có số trang."},{"title":"Bước 9: Chèn mục lục tự động (tới Heading 3) và căn chỉnh theo hai bên","forRequirement":"Yêu cầu 3 (và Yêu cầu 2)","actions":["Đặt con trỏ dưới dòng 'MỤC LỤC' ở trang 1 (dòng trống đã chừa sẵn).","Tab References > nhóm Table of Contents > Table of Contents > Custom Table of Contents...","Trong hộp thoại Table of Contents: tick Show page numbers; tick Right align page numbers; Tab leader chọn dòng chấm (......); Formats chọn From template; Show levels = 3 > OK.","Mục lục xuất hiện với số trang canh phải, nối bằng dấu chấm, như vậy hai mép trái và phải của mục lục thẳng hàng. Để chắc chắn căn đều hai bên: bôi đen toàn bộ mục lục > Home > Paragraph > Justify (Ctrl+J).","Nếu mục lục không đúng font: Home > Styles > Dialog Launcher > chọn lần lượt TOC 1, TOC 2, TOC 3 > Modify > đặt Times New Roman 13.","Khi sửa tên chương, thêm mục hoặc đổi số trang: bấm vào mục lục > Update Table (hoặc F9) > chọn Update entire table > OK."],"note":"Mục lục phải chiếm đúng 1 trang (trang 1). Vì Heading 1 có Page break before nên chương 1 không dính vào trang mục lục. Dòng 'MỤC LỤC' không dùng style Heading nên không tự đưa vào mục lục."},{"title":"Bước 10: Kiểm tra lần cuối và lưu","forRequirement":"Tất cả","actions":["Cập nhật toàn bộ trường: Ctrl+A > F9 > chọn Update entire table nếu có hỏi.","Dùng View > Navigation Pane (tick) để xem cây Heading 1/2/3; kiểm tra có đủ 3 cấp.","Xem File > Print (Ctrl+P) để duyệt từng trang: trang 1 mục lục, các chương bắt đầu đầu trang, trang cuối là Tài liệu tham khảo, số trang ở giữa trên.","Bấm Ctrl+S để lưu file xyz_cau1.docx trong E:\\ThiCC."],"note":""}],"formulas":[],"result":"File xyz_cau1.docx dài khoảng 5 trang A4 dọc: trang 1 là MỤC LỤC tự động có 3 cấp, số trang canh phải kèm dấu chấm dẫn; từ trang 2 mỗi Chương nằm ở đầu một trang mới; trang cuối là TÀI LIỆU THAM KHẢO gồm 4 tài liệu đánh số [1] đến [4]; trong nội dung có các tham chiếu [1], [2] dạng Cross-reference; số trang hiển thị chính giữa phía trên mọi trang; toàn bộ chữ Times New Roman 13pt. Tự kiểm tra: mở Page Setup xem đủ thông số lề và Header/Footer; Navigation Pane hiện đủ Heading 1, 2, 3; bấm F9 thì mục lục và tham chiếu cập nhật."},"checklist":["Giấy A4, Portrait (Page Setup > Paper và Margins).","Top 2.5 cm, Bottom 2.2 cm, Left 3.5 cm, Right 1.5 cm.","Header 1.3 cm, Footer 1.3 cm (Page Setup > Layout > From edge).","Font toàn văn bản Times New Roman, cỡ 13pt (kể cả tiêu đề, mục lục, số trang).","Trang 1 chỉ có Mục lục (1 trang).","Mỗi chương bắt đầu ở đầu một trang mới (từ trang 2).","Có đề mục dùng đủ Heading 1, Heading 2, Heading 3.","Trang cuối là Tài liệu tham khảo với khoảng 4 tài liệu, nằm trọn 1 trang.","Số trang đặt chính giữa phía trên (Header, Plain Number 2).","Mục lục tạo bằng References > Table of Contents, hiển thị tới 3 cấp, số trang canh phải, mục lục căn đều hai bên.","Có ít nhất một tham chiếu tới tài liệu tham khảo dạng Cross-reference (không gõ tay).","Sau khi thêm bớt tài liệu tham khảo rồi nhấn F9 thì tham chiếu cập nhật theo."],"commonMistakes":["Gõ tay mục lục và số trang thay vì dùng mục lục tự động, hoặc dùng cỡ chữ/in đậm thủ công thay vì style Heading nên mục lục không tạo được.","Đặt font Times New Roman 13 bằng cách bôi đen rồi sửa tay; các style Heading, TOC, Header vẫn giữ font cũ (Calibri) nên một số chỗ sai font. Cần Modify style Normal và các Heading.","Dùng nhiều lần Enter hoặc Ctrl+Enter để nhảy sang trang chương mới; khi sửa nội dung bị lệch trang. Nên dùng Page break before cho Heading 1.","Gõ tay [1] trong văn bản thay vì Cross-reference nên không tự cập nhật khi đổi danh sách tham khảo.","Quên bật Show levels = 3 khi chèn mục lục nên Heading 3 không hiện.","Đưa dòng 'MỤC LỤC' vào style Heading 1 khiến mục lục tự liệt kê chính nó.","Nhập lề khi Word đang để Inches; hoặc quên chỉnh Header/Footer 1.3 cm trong thẻ Layout của Page Setup.","Chèn số trang ở Footer (cuối trang) thay vì ở Header chính giữa (Top of Page).","Không cập nhật mục lục (F9) trước khi lưu nên số trang lệch với thực tế.","Tài liệu tham khảo bị tràn sang trang thứ 2 do khoảng cách dòng quá lớn."],"uncertain":["Đề không nêu rõ 'căn chỉnh theo hai bên' của mục lục là Justify hay là số trang canh phải. Hướng dẫn thực hiện cả hai: Right align page numbers kèm dấu chấm dẫn và Justify (Ctrl+J).","Đề yêu cầu font Times New Roman cỡ 13pt cho cả văn bản; hướng dẫn giữ cả các tiêu đề ở 13pt (phân biệt bằng in đậm, in hoa, in nghiêng).","Đề không yêu cầu cụ thể cách tham chiếu tài liệu tham khảo; hướng dẫn dùng Cross-reference tới danh sách đánh số vì đây là cách phổ biến. File mẫu xyz-Cau 1.doc (định dạng .doc cũ) chỉ đọc được một phần văn bản (tài liệu mẫu có Mục lục, Lời nói đầu, các chương về cơ học), không dùng để đối chiếu chi tiết."]},{"no":2,"app":"excel","title":"Câu 2. Tạo bảng tính (Microsoft Excel)","statement":{"intro":"Bảng điểm tổng kết một kỳ thi thể hiện như bảng sau (hai dòng đầu là dữ liệu mẫu trong đề, các dòng sau là '...'). Sử dụng phần mềm Microsoft Excel tạo bảng tổng kết với các yêu cầu sau:","requirements":["1) Nhập dữ liệu (giả định) cho 10 thí sinh trên các cột: TT (thứ tự), Họ tên, Ngày sinh, GT (giới tính), Toán, Anh; Kẻ khung, căn chỉnh, định dạng các kiểu dữ liệu cho phù hợp; Font: Times New Roman, cỡ 13pt.","2) Định dạng trang: Khổ giấy A4, Landscape; Top: 2.5, Bottom: 2.5; Left: 2.5, right: 1.5. Căn chỉnh bảng tính ra giữa trang in (Horizontally).","3) Nhập công thức tính giá trị cột Tuổi, biết tuổi tính đến ngày hiện tại.","4) Nhập công thức tính Điểm trung bình của hai môn thi Toán và Anh vào cột Điểm TB biết rằng điểm Toán hệ số 3 và điểm Anh hệ số 2. Điểm TB được làm tròn với 1 chữ số sau dấu phẩy.","5) Nhập công thức cho cột Xếp loại và cột Học bổng theo thang điểm sau: Dưới 5: Kém, không học bổng; Từ 5 đến cận 7: Trung bình, không học bổng; Từ 7 đến cận 8: Khá, học bổng 500 000; Từ 8 đến cận 9.5: Giỏi, học bổng 1 000 000; Từ 9.5 đến 10: Xuất sắc, học bổng 2 000 000."],"material":[{"kind":"table","caption":"Bảng điểm tổng kết (mẫu trong đề; các ô Tuổi, Điểm TB, Xếp loại, Học bổng để trống chờ công thức)","rows":[["TT","Họ tên","Ngày sinh","Tuổi","GT","Toán","Anh","Điểm TB","Xếp loại","Học bổng"],["1","Nguyễn Văn A","30/01/1978","","Nam","4","7","","",""],["2","Trần Thị B","08/02/1974","","Nữ","6","8","","",""],["...","...","","","","","","","",""]]},{"kind":"table","caption":"Thang điểm xếp loại và học bổng","rows":[["Điểm TB","Xếp loại","Học bổng"],["Dưới 5","Kém",""],["Từ 5 đến cận 7","Trung bình",""],["Từ 7 đến cận 8","Khá","500 000"],["Từ 8 đến cận 9.5","Giỏi","1 000 000"],["Từ 9.5 đến 10","Xuất sắc","2 000 000"]]},{"kind":"table","caption":"Gợi ý dữ liệu giả định cho 10 thí sinh (thí sinh có thể tự bịa; bộ này để thử đủ các mức xếp loại)","rows":[["TT","Họ tên","Ngày sinh","GT","Toán","Anh"],["1","Nguyễn Văn A","30/01/1978","Nam","4","7"],["2","Trần Thị B","08/02/1974","Nữ","6","8"],["3","Lê Văn C","12/05/1990","Nam","7","5"],["4","Phạm Thị D","23/09/1985","Nữ","8","7"],["5","Hoàng Văn E","15/03/1992","Nam","9","8"],["6","Đỗ Thị G","07/11/1988","Nữ","10","9"],["7","Vũ Văn H","19/06/1983","Nam","3","4"],["8","Ngô Thị K","01/12/1995","Nữ","8","8"],["9","Bùi Văn L","25/08/1980","Nam","9","10"],["10","Đặng Thị M","30/04/1991","Nữ","7","7"]]}]},"solution":{"summary":"Nhập 10 dòng dữ liệu, định dạng font Times New Roman 13, kẻ khung và căn chỉnh; thiết lập trang A4 ngang với lề và căn giữa ngang; sau đó nhập công thức Tuổi, Điểm TB (làm tròn 1 chữ số, hệ số 3 và 2), Xếp loại và Học bổng bằng hàm IF lồng nhau rồi kéo xuống cho 10 dòng.","steps":[{"title":"Bước 1: Tạo bảng và nhập dữ liệu","forRequirement":"Yêu cầu 1","actions":["Mở Excel, dùng Sheet1. Lưu ngay vào E:\\ThiCC với tên xyz_cau2.xlsx (File > Save As > Excel Workbook).","Nhập dòng tiêu đề vào A1:J1 lần lượt: TT, Họ tên, Ngày sinh, Tuổi, GT, Toán, Anh, Điểm TB, Xếp loại, Học bổng (đúng thứ tự cột của đề).","Nhập 10 dòng dữ liệu vào các cột A, B, C, E, F, G (cột D, H, I, J để trống, sẽ nhập công thức). Hai dòng đầu theo đề: 1 | Nguyễn Văn A | 30/01/1978 | Nam | 4 | 7 và 2 | Trần Thị B | 08/02/1974 | Nữ | 6 | 8. Các dòng 3 đến 10 nhập dữ liệu giả định, ví dụ theo bảng gợi ý ở phần đề.","Gõ Ngày sinh theo dạng dd/mm/yyyy (30/01/1978). Phải kiểm tra Excel nhận là ngày chứ không phải chữ: ngày hợp lệ tự căn phải trong ô, nếu bị căn trái nghĩa là Excel hiểu là text (xem phần lỗi thường gặp).","Nhập cột TT bằng cách gõ 1 và 2 rồi bôi đen hai ô, kéo núm điền (Fill handle, ô vuông nhỏ góc dưới phải) xuống tới số 10."],"note":"Điểm Toán và Anh nhập là số (căn phải), không gõ thêm chữ."},{"title":"Bước 2: Font Times New Roman 13, kẻ khung, căn chỉnh và định dạng kiểu dữ liệu","forRequirement":"Yêu cầu 1","actions":["Bôi đen A1:J11 (hoặc click ô A1 rồi Ctrl+Shift+End). Tab Home > nhóm Font > ô font chọn Times New Roman, ô cỡ chọn 13.","Kẻ khung: giữ nguyên vùng chọn A1:J11 > Home > nhóm Font > mũi tên nút Borders > All Borders.","Hàng tiêu đề A1:J1: Home > Bold (Ctrl+B), nhóm Alignment bấm Center và Middle Align; tô nền nhẹ (Fill Color) nếu muốn; bật Wrap Text nếu cột hẹp.","Căn chỉnh nội dung: cột TT (A), Ngày sinh (C), Tuổi (D), GT (E) chọn Center; cột Họ tên (B) Align Left; các cột Toán, Anh, Điểm TB căn giữa hoặc phải; cột Xếp loại (I) Center; Học bổng (J) Align Right.","Định dạng kiểu dữ liệu: bôi đen C2:C11 > chuột phải > Format Cells... (Ctrl+1) > thẻ Number > Category: Custom > Type: dd/mm/yyyy > OK. Bôi đen D2:D11 > Format Cells > Number > Category Number, Decimal places = 0. Bôi đen H2:H11 > Number, Decimal places = 1. Bôi đen J2:J11 > Number, Decimal places = 0, tick Use 1000 Separator.","Chỉnh độ rộng cột: bôi đen các cột A đến J > nháy đúp vào đường ngăn giữa hai tiêu đề cột bất kỳ (AutoFit Column Width) hoặc Home > Format > AutoFit Column Width."],"note":"Cột Tuổi phải để định dạng Number hoặc General. Nếu Excel tự gán định dạng Date vì ô bên cạnh là ngày, kết quả Tuổi sẽ hiện như ngày tháng năm 1900, cần đổi lại."},{"title":"Bước 3: Định dạng trang (A4, Landscape, lề, căn giữa ngang)","forRequirement":"Yêu cầu 2","actions":["Tab Page Layout > nhóm Page Setup > bấm Dialog Launcher (mũi tên nhỏ góc dưới phải) để mở hộp thoại Page Setup.","Thẻ Page: Orientation chọn Landscape; Paper size chọn A4.","Thẻ Margins: Top = 2.5, Bottom = 2.5, Left = 2.5, Right = 1.5 (đơn vị cm). Phần 'Center on page' tick Horizontally (không tick Vertically). Header và Footer giữ mặc định.","Bấm OK. Nhấn Ctrl+P (hoặc File > Print) xem Print Preview: bảng nằm ngang và chính giữa theo chiều ngang trang.","Có thể đặt vùng in cho gọn: bôi đen A1:J11 > Page Layout > Print Area > Set Print Area."],"note":"Nếu Excel đang hiện đơn vị inch (do cài đặt Region), nhập 2.5 cm bằng cách gõ '2.5 cm' vào ô, Excel sẽ tự đổi sang inch. Hoặc 2.5 cm xấp xỉ 0.98 inch, 1.5 cm xấp xỉ 0.59 inch."},{"title":"Bước 4: Tính Tuổi (đến ngày hiện tại)","forRequirement":"Yêu cầu 3","actions":["Click ô D2, gõ công thức =YEAR(TODAY())-YEAR(C2) rồi Enter.","Giải thích: TODAY() trả về ngày hôm nay, YEAR() lấy năm, hiệu hai năm cho số tuổi tính theo năm.","Nếu muốn tuổi chính xác theo ngày/tháng: dùng =DATEDIF(C2,TODAY(),\"Y\"). Chỉ cần chọn một trong hai.","Kéo núm điền ở góc dưới phải ô D2 xuống D11 (hoặc nháy đúp núm điền, hoặc chọn D2:D11 rồi Ctrl+D).","Kiểm tra: ngày sinh 30/01/1978 cho kết quả bằng năm hiện tại trừ 1978 (nếu dùng DATEDIF thì có thể ít hơn 1 nếu chưa tới sinh nhật)."],"note":"Nếu máy dùng dấu chấm phẩy (;) làm dấu ngăn cách đối số (thường gặp khi Region là Vietnamese) thì gõ ; thay cho dấu phẩy: =DATEDIF(C2;TODAY();\"Y\"). Quy tắc này áp dụng cho mọi công thức dưới đây."},{"title":"Bước 5: Tính Điểm TB (hệ số 3 và 2, làm tròn 1 chữ số)","forRequirement":"Yêu cầu 4","actions":["Click ô H2, gõ =ROUND((F2*3+G2*2)/5,1) rồi Enter.","Giải thích: F2 là Toán nhân hệ số 3, G2 là Anh nhân hệ số 2, cộng lại chia tổng hệ số 3+2=5; ROUND(...,1) làm tròn tới 1 chữ số sau dấu phẩy.","Kéo núm điền từ H2 xuống H11.","Kiểm tra: dòng 1 (4 và 7) cho (12+14)/5 = 5.2; dòng 2 (6 và 8) cho (18+16)/5 = 6.8."],"note":"Phải bọc toàn bộ phép tính trong ROUND chứ không chỉ định dạng 1 chữ số thập phân (Format Cells). Xếp loại phải dựa trên giá trị đã làm tròn."},{"title":"Bước 6: Tính Xếp loại","forRequirement":"Yêu cầu 5","actions":["Click ô I2, gõ =IF(H2<5,\"Kém\",IF(H2<7,\"Trung bình\",IF(H2<8,\"Khá\",IF(H2<9.5,\"Giỏi\",\"Xuất sắc\")))) rồi Enter.","Giải thích: kiểm tra từ thấp lên cao. Nếu dưới 5 là Kém; nếu chưa đúng mà dưới 7 thì là Trung bình (tức từ 5 tới cận 7); tiếp theo dưới 8 là Khá; dưới 9.5 là Giỏi; còn lại (từ 9.5 trở lên) là Xuất sắc.","Kéo núm điền từ I2 xuống I11.","Gõ đúng chính tả chữ Việt như trong đề: Kém, Trung bình, Khá, Giỏi, Xuất sắc."],"note":"Chuỗi chữ trong công thức luôn đặt trong dấu nháy kép thẳng; nếu copy từ Word dễ bị nháy cong gây lỗi #NAME?."},{"title":"Bước 7: Tính Học bổng","forRequirement":"Yêu cầu 5","actions":["Click ô J2, gõ =IF(I2=\"Khá\",500000,IF(I2=\"Giỏi\",1000000,IF(I2=\"Xuất sắc\",2000000,\"\"))) rồi Enter.","Giải thích: nếu Xếp loại là Khá thì 500000, Giỏi thì 1000000, Xuất sắc thì 2000000, còn lại (Kém, Trung bình) để trống đúng như bảng thang điểm của đề.","Kéo núm điền J2 xuống J11.","Cách khác dựa trực tiếp vào điểm: =IF(H2>=9.5,2000000,IF(H2>=8,1000000,IF(H2>=7,500000,\"\"))). Kết quả tương đương.","Cột J đã định dạng Number có dấu phân cách hàng nghìn ở Bước 2."],"note":"Có thể thay \"\" bằng 0 nếu muốn hiện số 0; đề để trống nên dùng \"\"."},{"title":"Bước 8: Kiểm tra và lưu","forRequirement":"Tất cả","actions":["Đối chiếu bảng gợi ý ở phần đề: Điểm TB lần lượt 5.2, 6.8, 6.2, 7.6, 8.6, 9.6, 3.4, 8, 9.4, 7 và Xếp loại Trung bình, Trung bình, Trung bình, Khá, Giỏi, Xuất sắc, Kém, Giỏi, Giỏi, Khá.","Học bổng tương ứng: trống, trống, trống, 500000, 1000000, 2000000, trống, 1000000, 1000000, 500000.","Nhấn Ctrl+P để xem trước trang in: giấy ngang, bảng ở giữa theo chiều ngang, không bị cắt cột.","Lưu Ctrl+S (xyz_cau2.xlsx)."],"note":""}],"formulas":[{"cell":"D2","formula":"=YEAR(TODAY())-YEAR(C2)","meaning":"Tuổi = năm hiện tại trừ năm sinh. Kéo xuống D11. Có thể thay bằng =DATEDIF(C2,TODAY(),\"Y\") để tính tuổi tròn chính xác."},{"cell":"H2","formula":"=ROUND((F2*3+G2*2)/5,1)","meaning":"Điểm TB có trọng số: Toán hệ số 3, Anh hệ số 2, chia cho tổng hệ số 5, làm tròn 1 chữ số thập phân."},{"cell":"I2","formula":"=IF(H2<5,\"Kém\",IF(H2<7,\"Trung bình\",IF(H2<8,\"Khá\",IF(H2<9.5,\"Giỏi\",\"Xuất sắc\"))))","meaning":"Xếp loại theo thang: dưới 5 Kém; 5 đến cận 7 Trung bình; 7 đến cận 8 Khá; 8 đến cận 9.5 Giỏi; từ 9.5 trở lên Xuất sắc."},{"cell":"J2","formula":"=IF(I2=\"Khá\",500000,IF(I2=\"Giỏi\",1000000,IF(I2=\"Xuất sắc\",2000000,\"\")))","meaning":"Học bổng theo xếp loại; Kém và Trung bình để trống."}],"result":"Sheet có bảng 10 cột x 11 dòng (1 dòng tiêu đề, 10 thí sinh) kẻ khung đầy đủ, font Times New Roman 13; cột Tuổi, Điểm TB (1 chữ số thập phân), Xếp loại, Học bổng đều là công thức và tự thay đổi khi sửa Toán, Anh hoặc Ngày sinh. Print Preview hiển thị khổ A4 ngang với lề Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 và bảng nằm giữa trang theo chiều ngang. Tự kiểm tra: bấm vào từng ô cột D, H, I, J phải thấy công thức; đổi thử điểm Toán xem Xếp loại và Học bổng đổi theo."},"checklist":["Có đủ các cột TT, Họ tên, Ngày sinh, Tuổi, GT, Toán, Anh, Điểm TB, Xếp loại, Học bổng và 10 thí sinh.","Toàn bảng dùng font Times New Roman cỡ 13pt.","Bảng có kẻ khung toàn bộ (All Borders), tiêu đề in đậm căn giữa.","Cột Ngày sinh là kiểu ngày dd/mm/yyyy (không phải text), Điểm TB hiện 1 chữ số thập phân, Học bổng có dấu phân cách hàng nghìn.","Trang in: A4, Landscape.","Lề Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 và tick Horizontally trong Center on page.","Cột Tuổi dùng công thức với TODAY() (không gõ cứng số).","Cột Điểm TB dùng công thức hệ số 3 và 2 bọc trong ROUND(...,1).","Cột Xếp loại dùng IF lồng nhau đúng mốc 5, 7, 8, 9.5.","Cột Học bổng cho 500000 (Khá), 1000000 (Giỏi), 2000000 (Xuất sắc) và trống với Kém, Trung bình.","Công thức đã kéo xuống đủ 10 dòng, không có lỗi #VALUE!, #NAME?."],"commonMistakes":["Gõ ngày sinh dd/mm/yyyy trong khi máy dùng định dạng ngày kiểu mm/dd/yyyy khiến ngày như 30/01/1978 thành chữ (text) và công thức Tuổi báo #VALUE!. Cách khắc phục: kiểm tra ô có căn phải không; đổi Region (Control Panel > Region > Short date dd/MM/yyyy) rồi nhập lại.","Cột Tuổi hiển thị như ngày tháng (ví dụ 01/01/1900) do ô có định dạng Date; phải đổi sang Number, 0 chữ số thập phân.","Chỉ định dạng 1 chữ số thập phân mà không dùng ROUND nên giá trị thực vẫn dài (ví dụ 9.46 hiển thị 9.5 nhưng xếp loại vẫn tính như 9.46).","Viết sai hệ số: lấy Toán nhân 2 và Anh nhân 3 hoặc chia cho 2 thay vì 5.","Viết IF sai mốc (dùng <=7 thay <7) làm điểm 7.0 bị xếp Trung bình thay vì Khá; nhớ 'cận 7' nghĩa là nhỏ hơn 7.","Gõ chữ Kém/Khá/Giỏi sai chính tả hoặc không khớp với chuỗi so sánh trong công thức Học bổng.","Dùng dấu phẩy trong công thức trong khi máy yêu cầu dấu chấm phẩy (hoặc ngược lại) nên báo lỗi công thức; chỉ cần đổi dấu ngăn cách đối số.","Dùng dấu nháy cong khi copy từ Word thay cho nháy kép thẳng nên ra #NAME?.","Quên tick Horizontally ở Center on page hoặc đặt Portrait thay vì Landscape.","Nhập Tuổi bằng số cố định thay vì công thức TODAY()."],"uncertain":["Bảng đề in mờ nhưng đọc được rõ: tiêu đề cột TT, Họ tên, Ngày sinh, Tuổi, GT, Toán, Anh, Điểm TB, Xếp loại, Học bổng; hai dòng mẫu là Nguyễn Văn A, 30/01/1978, Nam, 4, 7 và Trần Thị B, 08/02/1974, Nữ, 6, 8.","File mẫu KT.xlsx có hai sheet: Sheet1 tính tuổi bằng =2020-RIGHT(C2,4) (cố định năm 2020, không đúng với 'đến ngày hiện tại') và có thêm cột K thừa; Sheet2 không làm tròn Điểm TB bằng ROUND. Hướng dẫn làm theo đề (TODAY() và ROUND), không theo hai chỗ lệch đó. Dữ liệu 10 thí sinh trong hướng dẫn là gợi ý, đề cho phép giả định.","Đề không nói rõ Học bổng của Kém và Trung bình, bảng thang điểm để trống nên hướng dẫn dùng \"\" (trống); dùng 0 cũng chấp nhận được."]},{"no":3,"app":"powerpoint","title":"Câu 3. Tạo các trang trình chiếu (Microsoft PowerPoint)","statement":{"intro":"Sử dụng phần mềm Microsoft PowerPoint thiết kế slides mẫu trình chiếu phục vụ cho báo cáo (>= 5 slides), trong đó có các nội dung sau:","requirements":["Nội dung 1) Trang giới thiệu: gồm có 2 nội dung: Tên tài liệu trong phần thi Word; Hà Nội, ngày...tháng...năm.","Nội dung 2) Nội dung: a. Mục lục nội dung trình bày trong bài thi Word. b. Các trang tiếp theo tương ứng với một nội dung trong mục lục.","Nội dung 3) Kết luận.","Yêu cầu 1) Đánh số trang slide.","Yêu cầu 2) Sử dụng slide master để định dạng kích thước, font trong phần tiêu đề, nội dung.","Yêu cầu 3) Tạo mới một Layout để sử dụng cho phần nội dung.","Yêu cầu 4) Sử dụng ít nhất 02 hiệu ứng Animation.","Yêu cầu 5) Sử dụng ít nhất 02 hiệu ứng Transition."],"material":[{"kind":"text","caption":"Nội dung trang giới thiệu (slide 1)","lines":["Tên tài liệu trong phần thi Word: (lấy tên tài liệu bạn đã soạn ở Câu 1)","Hà Nội, ngày...tháng...năm"]}]},"solution":{"summary":"Tạo bộ khung bằng Slide Master (font, cỡ chữ, số trang), tạo một Custom Layout dành cho slide nội dung, rồi dựng 6 slide: Giới thiệu, Mục lục, 3 slide nội dung tương ứng 3 chương, Kết luận; cuối cùng gắn ít nhất 2 Animation và 2 Transition.","steps":[{"title":"Bước 1: Tạo file và lưu","forRequirement":"Chuẩn bị","actions":["Mở PowerPoint, chọn Blank Presentation (slide đầu là Title Slide).","File > Save As > thư mục E:\\ThiCC > đặt tên xyz_cau3.pptx > Save. Khổ 16:9 hay 4:3 chọn ở Design > Slide Size (không bắt buộc)."],"note":"Nên dựng Slide Master trước khi tạo nội dung để toàn bộ slide tự theo mẫu."},{"title":"Bước 2: Định dạng Slide Master (font, kích thước tiêu đề và nội dung)","forRequirement":"Yêu cầu 2","actions":["Tab View > nhóm Master Views > Slide Master. Cột trái hiện slide mẫu lớn trên cùng (Slide Master) và các layout bên dưới.","Click vào slide mẫu lớn nhất ở trên cùng. Chọn khung tiêu đề (Click to edit Master title style) > Home > font Times New Roman, cỡ 36 (hoặc 40), Bold, màu tùy chọn; Align Left hoặc Center.","Chọn khung nội dung (Click to edit Master text styles): bôi đen từng dòng cấp 1 đến cấp 5. Đặt font Times New Roman, cỡ cấp 1 = 28, cấp 2 = 24, cấp 3 = 20, cấp 4 = 18, cấp 5 = 18.","Có thể thêm màu nền hoặc hình trang trí ở Slide Master: tab Slide Master > Background Styles; hoặc Insert > Shapes vẽ một thanh màu ở dưới. Bất cứ thứ gì thêm vào Slide Master sẽ xuất hiện trên mọi slide.","Chưa đóng Master View, tiếp tục các bước 3 và 4."],"note":"Không chỉnh font tay trong từng slide; chỉ chỉnh ở Master để đáp ứng yêu cầu 'sử dụng slide master'. Các layout con kế thừa từ Slide Master."},{"title":"Bước 3: Đánh số trang slide","forRequirement":"Yêu cầu 1","actions":["Vẫn ở Slide Master view, kiểm tra khung số trang (Slide Number placeholder, dạng <#>) ở góc dưới phải; chỉnh font Times New Roman cỡ 14, màu rõ nét, có thể kéo đổi vị trí.","Hoàn tất Bước 4 (tạo layout) rồi mới bấm Close Master View (tab Slide Master > Close Master View).","Tab Insert > nhóm Text > Slide Number (hoặc Header & Footer) > thẻ Slide: tick Slide number; tick Don't show on title slide nếu muốn trang giới thiệu không có số (không bắt buộc); bấm Apply to All.","Kiểm tra: số 1, 2, 3, ... hiện ở góc các slide."],"note":"Nếu số trang không hiện thì kiểm tra khung Slide Number còn trong layout (không bị xóa) và đã bấm Apply to All. Layout mới tạo ở bước sau cũng phải có khung này (Master Layout > tick Footers)."},{"title":"Bước 4: Tạo mới một Layout dành cho phần nội dung","forRequirement":"Yêu cầu 3","actions":["View > Slide Master. Click vào Slide Master, tab Slide Master > nhóm Edit Master > Insert Layout. Một layout mới xuất hiện cuối danh sách bên trái.","Đổi tên: chuột phải layout mới > Rename Layout... > gõ 'Noi dung' (hoặc 'Layout Nội dung') > Rename.","Trong layout mới, tab Slide Master > nhóm Master Layout > Insert Placeholder > chọn Content rồi kéo vẽ vào slide, ví dụ chiếm phần giữa; giữ khung Title ở trên. Xóa các khung chân trang thừa nếu muốn.","Trang trí riêng cho layout này (ví dụ thêm một đường kẻ hoặc hình nhỏ) để phân biệt với layout mặc định. Kiểm tra khung Slide Number vẫn có (Master Layout > tick Footers).","Tab Slide Master > Close Master View."],"note":"Đây là phần thường bị bỏ sót: bắt buộc phải là layout MỚI tự tạo và dùng nó cho các slide nội dung (không dùng lại Title and Content mặc định)."},{"title":"Bước 5: Dựng slide 1 (Trang giới thiệu)","forRequirement":"Nội dung 1","actions":["Chọn slide 1 (layout Title Slide). Ô tiêu đề (Click to add title) gõ tên tài liệu đã soạn ở Câu 1, ví dụ 'ỨNG DỤNG CÔNG NGHỆ THÔNG TIN'.","Ô phụ đề (Click to add subtitle) gõ 'Hà Nội, ngày ... tháng ... năm ...' (có thể điền ngày thực).","Không đổi font ở slide; font đã lấy từ Master."],"note":""},{"title":"Bước 6: Dựng slide 2 (Mục lục), các slide nội dung và Kết luận","forRequirement":"Nội dung 2a, 2b, 3","actions":["Home > New Slide (mũi tên) > chọn layout mới 'Noi dung' đã tạo ở Bước 4. Tiêu đề: 'MỤC LỤC'; trong ô nội dung gõ danh sách các chương trong bài Word (ví dụ: Chương 1. Tổng quan; Chương 2. Nội dung chính; Chương 3. Ứng dụng; Kết luận).","Tạo tiếp 3 slide mới cũng dùng layout 'Noi dung' (mỗi slide tương ứng một chương trong mục lục). Mỗi slide: tiêu đề là tên chương (khớp mục lục); ô nội dung gõ 3 đến 5 gạch đầu dòng tóm tắt các đề mục của chương đó trong Word (Heading 2 và Heading 3).","Slide cuối: New Slide với layout 'Noi dung', tiêu đề 'KẾT LUẬN', nội dung 3 gạch đầu dòng tổng kết và lời cảm ơn.","Tổng cộng 6 slide: 1 Giới thiệu, 2 Mục lục, 3 đến 5 nội dung các chương, 6 Kết luận (thỏa yêu cầu >= 5 slide).","Nếu slide đã tạo bằng layout khác, đổi layout: chọn slide > Home > Layout > chọn layout mới."],"note":"Nội dung các slide phải khớp tên chương trong mục lục của Word. Không nhập quá nhiều chữ (khoảng 3 đến 5 ý mỗi slide)."},{"title":"Bước 7: Thêm ít nhất 02 hiệu ứng Animation","forRequirement":"Yêu cầu 4","actions":["Chọn slide 1, click vào khung tiêu đề > tab Animations > nhóm Animation > chọn Fade (hoặc Fly In, Zoom). Trong nhóm Timing: Start chọn After Previous hoặc On Click.","Click khung phụ đề (Hà Nội, ngày ...) > chọn hiệu ứng khác, ví dụ Fly In (Effect Options > From Bottom).","Trên slide nội dung 3: chọn khung nội dung > Animations > Wipe hoặc Appear > Effect Options > By Paragraph để các ý hiện lần lượt.","Kiểm tra: Animations > Animation Pane để xem danh sách hiệu ứng; nhấn Preview hoặc F5 (chạy từ đầu) để thử."],"note":"Yêu cầu chỉ cần ít nhất 2 hiệu ứng; nên dùng hai hiệu ứng khác loại trên hai đối tượng khác nhau cho chắc."},{"title":"Bước 8: Thêm ít nhất 02 hiệu ứng Transition","forRequirement":"Yêu cầu 5","actions":["Chọn slide 1 trong ngăn trái > tab Transitions > nhóm Transition to This Slide > chọn Fade.","Chọn slide 2 > Transitions > chọn Push (hoặc Wipe, Split).","Chọn các slide còn lại > chọn tiếp một hiệu ứng khác (ví dụ Cover), hoặc dùng Apply To All cho một hiệu ứng chung. Tùy chọn: Timing > Duration 1.0 giây; chọn On Mouse Click.","Slide nào có hiệu ứng sẽ hiện ngôi sao nhỏ bên cạnh số slide trong ngăn trái. Nhấn F5 để xem toàn bộ."],"note":"Đảm bảo có tối thiểu 2 kiểu Transition khác nhau, ví dụ Fade và Push. Nếu bấm Apply To All sau cùng thì tất cả slide thành cùng một hiệu ứng, nên áp dụng riêng từng slide."},{"title":"Bước 9: Kiểm tra lần cuối và lưu","forRequirement":"Tất cả","actions":["F5 chạy trình chiếu từ đầu: kiểm tra Transition, Animation, số trang và font.","View > Slide Master: kiểm tra layout mới còn tồn tại.","Bấm Ctrl+S để lưu xyz_cau3.pptx trong E:\\ThiCC."],"note":""}],"formulas":[],"result":"File xyz_cau3.pptx có ít nhất 5 slide (ví dụ 6): slide 1 giới thiệu có tên tài liệu và dòng Hà Nội, ngày...tháng...năm; slide 2 là Mục lục; các slide tiếp theo mỗi slide một chương; slide cuối là Kết luận. Mọi slide có số trang; font và cỡ chữ tiêu đề và nội dung đồng nhất do Master định nghĩa; trong Slide Master có một Layout mới (đã đổi tên) được dùng cho slide nội dung; có ít nhất 2 Animation và 2 Transition khác nhau. Tự kiểm tra bằng F5 và bằng View > Slide Master."},"checklist":["Có từ 5 slide trở lên.","Slide 1 có tên tài liệu (trùng tài liệu Word) và dòng Hà Nội, ngày...tháng...năm.","Slide Mục lục khớp với mục lục của bài Word.","Mỗi chương trong mục lục có một slide riêng.","Có slide Kết luận.","Có đánh số trang slide (Insert > Slide Number > Apply to All).","Font và cỡ chữ tiêu đề, nội dung được thiết lập trong Slide Master.","Đã tạo một Custom Layout mới (Insert Layout) và các slide nội dung dùng layout đó.","Có ít nhất 02 hiệu ứng Animation.","Có ít nhất 02 hiệu ứng Transition."],"commonMistakes":["Sửa font và cỡ chữ trực tiếp trong từng slide thay vì ở Slide Master nên không đạt yêu cầu dùng Master.","Chỉ chèn thêm layout nhưng quên áp dụng cho slide nội dung (slide vẫn dùng Title and Content).","Chọn Slide Number nhưng không bấm Apply to All hoặc layout mới không có khung số trang nên số không hiện.","Dùng Transition giống nhau cho mọi slide nên chỉ tính 1 hiệu ứng; cần có ít nhất 2 loại khác nhau.","Gán Animation cho cả slide thay vì cho từng đối tượng (Animation áp dụng cho đối tượng như tiêu đề, khung nội dung, hình).","Tên chương trong slide không khớp với mục lục Word hoặc thiếu slide cho một chương.","Quá nhiều chữ trong một slide, chữ nhỏ không đọc được.","Quên lưu đúng tên xyz_cau3.pptx trong E:\\ThiCC."],"uncertain":["Đề không nêu kích thước slide cụ thể; hướng dẫn để mặc định (16:9 hoặc 4:3 tùy chọn).","Đề không nói rõ slide giới thiệu có phải hiện số trang hay không; hướng dẫn áp dụng cho mọi slide (Apply to All), có thể chọn Don't show on title slide.","Nội dung cụ thể của tài liệu Word do thí sinh tự chọn nên tên chương, tiêu đề slide trong hướng dẫn chỉ là ví dụ."]}]},{"id":7,"title":"Đề thực hành số 7","source":"De co ban 7","timeLimitMinutes":60,"generalNotes":["Đề thi cấp chứng chỉ ƯDCNTT cơ bản, Học viện Kỹ thuật Quân sự, Khoa Công nghệ thông tin. Đợt thi: B191220014. Thời gian: 60 phút.","Đề thi gồm 3 trang; không được sử dụng tài liệu, USB và các thiết bị lưu trữ khác.","Các file bài làm để trong thư mục D:\\ThiCC, cách đặt tên file: Câu 1: sbd_cau1.docx; Câu 2: sbd_cau2.xlsx; Câu 3: sbd_cau3.pptx. Trong đó sbd là số báo danh của thí sinh (ví dụ SBD 025 thì lưu 025_cau1.docx).","Trang 1 của đề: phần ghi chú, Câu 1 (Word) và phần đầu Câu 2 (Excel, yêu cầu 1 đến 3). Trang 2: yêu cầu 4, 5 của Câu 2 và Câu 3 (PowerPoint). Trang 3: nội dung văn bản phải soạn ở Câu 1."],"tasks":[{"no":1,"app":"word","title":"Câu 1. Soạn thảo văn bản (Microsoft Word)","statement":{"intro":"Sử dụng phần mềm Microsoft Word soạn thảo nội dung tài liệu trên trang 3 với các yêu cầu sau:","requirements":["1) Soạn và định dạng đầy đủ nội dung văn bản như trang 3.","2) Định dạng trang: Cỡ giấy: A4; Chiều: Portrait; Lề trên (Top): 2.5 cm, Lề dưới (Bottom): 2 cm, Lề trái (Left): 3.5 cm, Lề phải (Right): 1.5 cm; Font: Times New Roman, cỡ 13pt.","3) Sử dụng tab để thể hiện các vị trí cần điền vào chỗ trống.","4) Sử dụng bảng 1 dòng, 2 cột, không đường viền ở cuối trang và điền thông tin người hướng dẫn vào cột thứ 2.","5) Sử dụng danh sách (1,2,3) cho các nội dung nhận xét và kết luận."],"material":[{"kind":"text","caption":"Nội dung văn bản trang 3 (các dấu chấm là chỗ trống phải làm bằng tab có leader dấu chấm)","lines":["CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM","Độc lập - Tự do - Hạnh phúc","NHẬN XÉT CỦA NGƯỜI HƯỚNG DẪN THỰC HÀNH","Tên tôi là: ......................... Ngày/tháng/năm sinh .........................","Đơn vị công tác: .............................................................","Số Chứng chỉ hành nghề: ............. Ngày cấp: ............. Nơi cấp: .............","Phạm vi hoạt động chuyên môn của người hướng dẫn (ghi theo CCHN được cấp):",".............................................................................","Được phân công hướng dẫn thực hành cho:","Ông/bà: ......................... Ngày/tháng/năm sinh: .........................","Văn bằng chuyên môn của người được hướng dẫn (ghi theo Giấy xác nhận thực hành):",".............................................................................","Thời gian từ: ......................... đến: .........................","NHẬN XÉT QUÁ TRÌNH THỰC HÀNH:","(1) Năng lực chuyên môn:","Thực hành thành thạo các kỹ năng chuyên môn, các quy trình kỹ thuật chuyên ngành.","(2) Đạo đức nghề nghiệp:","Đối với người bệnh và người nhà người bệnh: Tuân thủ đúng chức năng, đạo đức nghề nghiệp trong khám, chữa bệnh, chăm sóc người bệnh theo quy định của ngành, của nhà nước.","(3) Kết luận:","Đủ năng lực chuyên môn và phẩm chất đạo đức nghề nghiệp để hành nghề khám bệnh, chữa bệnh chuyên ngành.","[Bảng 1 dòng 2 cột, không viền, cột 1 để trống, cột 2 gồm 3 dòng:]","Hà Nội, ngày      tháng      năm 20 ...","Người hướng dẫn","(Ký ghi rõ họ tên)"]}]},"solution":{"summary":"Thiết lập trang A4 dọc với 4 lề đúng đề và font Times New Roman 13pt cho toàn văn bản, gõ nội dung, dùng Tab có Leader dấu chấm (Right Tab) để làm các chỗ trống, đánh số (1), (2), (3) bằng Numbering với định dạng số tự tạo, và dùng bảng 1 hàng 2 cột bỏ viền ở cuối trang để đặt khối chữ ký.","steps":[{"title":"Bước 1. Tạo file và đặt font Times New Roman 13pt","forRequirement":"2","actions":["Mở Microsoft Word, tạo Blank document (Ctrl+N).","Vào tab Home, bấm mũi tên nhỏ ở góc dưới phải nhóm Font (hoặc Ctrl+D) > ô Font chọn Times New Roman, ô Size chọn 13 > bấm nút Set As Default ở góc dưới trái > chọn All documents based on the Normal.dotm template > OK. Như vậy mọi chữ gõ sau đó đều là Times New Roman 13pt.","Cách nhanh hơn nếu không muốn đổi mặc định: tab Home > nhóm Font > chọn Times New Roman và cỡ 13 ngay khi file còn trống, rồi mới gõ.","Lưu file ngay: Ctrl+S > chọn thư mục D:\\ThiCC > đặt tên sbd_cau1.docx (thay sbd bằng số báo danh của bạn) > Save."],"note":"Nếu quên chọn font trước khi gõ, cuối bài bấm Ctrl+A rồi chọn lại Times New Roman, 13 cho toàn văn bản (kể cả trong bảng)."},{"title":"Bước 2. Định dạng trang: A4, Portrait, 4 lề","forRequirement":"2","actions":["Vào tab Page Layout > nhóm Page Setup > Margins > Custom Margins... (hộp thoại Page Setup).","Thẻ Margins: nhập Top = 2.5 cm, Bottom = 2 cm, Left = 3.5 cm, Right = 1.5 cm. Gutter để 0. Mục Orientation chọn Portrait.","Sang thẻ Paper: ô Paper size chọn A4 (21 cm x 29.7 cm). Kiểm tra Width = 21 cm, Height = 29.7 cm.","Mục Apply to chọn Whole document > OK."],"note":"Nếu máy hiển thị đơn vị là inch, gõ kèm đơn vị, ví dụ 2.5 cm, Word tự đổi. Chiều rộng vùng viết sau khi trừ lề là 21 - 3.5 - 1.5 = 16 cm, con số này dùng để đặt tab ở Bước 4."},{"title":"Bước 3. Gõ nội dung phần đầu (quốc hiệu và tiêu đề)","forRequirement":"1","actions":["Dòng 1: gõ CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM, bôi đen, bấm Ctrl+E (căn giữa) và Ctrl+B (đậm).","Dòng 2: gõ Độc lập - Tự do - Hạnh phúc, căn giữa, đậm. Trong ảnh đề có một đường kẻ ngắn dưới dòng này: nếu muốn giống, có thể bôi đen dòng 2 > tab Home > nhóm Paragraph > Borders (mũi tên) > Bottom Border.","Bấm Enter, gõ NHẬN XÉT CỦA NGƯỜI HƯỚNG DẪN THỰC HÀNH, căn giữa, đậm (đề chỉ bắt buộc 13pt, nên giữ cỡ 13 hoặc tăng nhẹ lên 14 nếu muốn nổi bật).","Để có khoảng cách giữa các khối: tab Home > nhóm Paragraph > mở hộp thoại Paragraph > mục Spacing đặt After = 6 pt cho dòng tiêu đề."],"note":"Các gạch giữa 'Độc lập - Tự do - Hạnh phúc' gõ bằng phím gạch nối thường (-). Word có thể tự đổi sang gạch dài, không ảnh hưởng điểm."},{"title":"Bước 4. Làm chỗ trống bằng Tab có Leader dấu chấm (Right Tab)","forRequirement":"3","actions":["Nguyên tắc: không gõ tay hàng loạt dấu chấm. Với mỗi dòng cần điền, đặt các điểm dừng tab kiểu Right, Leader số 2 (dấu chấm ......) rồi gõ chữ, nhấn phím Tab, đến chỗ chữ tiếp theo lại nhấn Tab.","Dòng 'Tên tôi là: ... Ngày/tháng/năm sinh ...': nhấn Enter xuống dòng mới (căn trái). Mở hộp thoại Paragraph (tab Home > mũi tên nhỏ nhóm Paragraph) > nút Tabs... Trong ô Tab stop position gõ 9.5 cm, mục Alignment chọn Right, mục Leader chọn 2 (......), bấm Set. Lặp lại: Tab stop position 16 cm, Right, Leader 2, bấm Set. Bấm OK.","Gõ: Tên tôi là: rồi bấm phím Tab (xuất hiện dấu chấm đến 9.5 cm), gõ Ngày/tháng/năm sinh rồi bấm Tab lần nữa (dấu chấm chạy đến sát lề phải 16 cm). Bấm Enter.","Dòng 'Đơn vị công tác:': mỗi khi bấm Enter, Word mang theo tab của dòng trước. Để dòng này chỉ có một vùng điền, mở lại Tabs..., chọn tab 9.5 cm > Clear (xóa), giữ tab 16 cm. Gõ Đơn vị công tác: rồi Tab.","Dòng 'Số Chứng chỉ hành nghề: ... Ngày cấp: ... Nơi cấp: ...': Tabs... > Clear All rồi đặt 3 tab Right + Leader 2 tại 8 cm, 12 cm, 16 cm. Gõ: Số Chứng chỉ hành nghề: Tab Ngày cấp: Tab Nơi cấp: Tab.","Dòng 'Phạm vi hoạt động chuyên môn của người hướng dẫn (ghi theo CCHN được cấp):': gõ nội dung (phần trong ngoặc có thể nghiêng bằng Ctrl+I). Bấm Enter, đặt một tab Right 16 cm Leader 2 rồi chỉ bấm một lần phím Tab trên dòng trống này để có cả dòng chấm.","Dòng 'Được phân công hướng dẫn thực hành cho:' gõ bình thường.","Dòng 'Ông/bà: ... Ngày/tháng/năm sinh: ...': đặt tab Right Leader 2 tại 9.5 cm và 16 cm. Gõ Ông/bà: Tab Ngày/tháng/năm sinh: Tab.","Dòng 'Văn bằng chuyên môn của người được hướng dẫn (ghi theo Giấy xác nhận thực hành):' gõ bình thường, Enter, đặt tab 16 cm Leader 2 và bấm Tab một lần cho dòng chấm.","Dòng 'Thời gian từ: ... đến: ...': đặt tab Right Leader 2 tại 8 cm và 16 cm. Gõ Thời gian từ: Tab đến: Tab.","Muốn thay đổi vị trí tab sau này: đặt con trỏ vào dòng, kéo biểu tượng tab trên thước ngang (View > bật Ruler) hoặc dùng lại hộp thoại Tabs..."],"note":"Các số 8, 9.5, 12 cm chỉ là gợi ý để dòng đẹp; quan trọng là tab cuối cùng đặt tại 16 cm (đúng bằng bề rộng vùng viết) và có leader dấu chấm. Bật Show/Hide (Ctrl+Shift+8) phải thấy mũi tên tab thì mới đúng là dùng tab, không phải gõ dấu chấm."},{"title":"Bước 5. Gõ nhận xét và danh sách đánh số (1), (2), (3)","forRequirement":"5","actions":["Gõ dòng NHẬN XÉT QUÁ TRÌNH THỰC HÀNH: , căn giữa, đậm, có thể thêm Spacing Before 6pt. Trước khi gõ đoạn này, xóa các tab cũ (Paragraph > Tabs... > Clear All) để Tab không làm lệch chữ.","Bấm Enter, đặt căn trái. Tạo kiểu số: tab Home > nhóm Paragraph > mũi tên bên cạnh nút Numbering > Define New Number Format...","Trong hộp Define New Number Format: ô Number style chọn 1, 2, 3,... ; ô Number format đang là 1. - sửa thành (1) bằng cách xóa dấu chấm, gõ dấu ( ở đầu và ) ở cuối, giữ nguyên con số tô xám; Alignment chọn Left > OK.","Gõ Năng lực chuyên môn: (tiêu đề đậm, Ctrl+B). Số (1) tự xuất hiện. Bấm Enter, Word sinh số (2): bấm Backspace để bỏ số đó và viết đoạn văn bản thường: Thực hành thành thạo các kỹ năng chuyên môn, các quy trình kỹ thuật chuyên ngành.","Để đoạn thân đẹp: Paragraph > Indentation Left = 0, Special = First line 1 cm (tùy chọn).","Bấm Enter, bấm Numbering lại (hoặc chọn kiểu (1) trong mục Recently Used Number Formats). Nếu số hiện là (1) thay vì (2): chuột phải vào số > Continue Numbering để số tiếp nối là (2).","Gõ Đạo đức nghề nghiệp: (đậm). Enter, bỏ số (Backspace), gõ đoạn Đối với người bệnh và người nhà người bệnh: Tuân thủ đúng chức năng, đạo đức nghề nghiệp trong khám, chữa bệnh, chăm sóc người bệnh theo quy định của ngành, của nhà nước.","Enter, áp lại Numbering, kiểm tra số là (3) (nếu không, chuột phải > Continue Numbering). Gõ Kết luận: (đậm). Enter, bỏ số, gõ đoạn Đủ năng lực chuyên môn và phẩm chất đạo đức nghề nghiệp để hành nghề khám bệnh, chữa bệnh chuyên ngành.","Có thể căn đều hai bên (Ctrl+J) cho các đoạn thân để trình bày gọn."],"note":"Tiêu đề (1), (2), (3) phải là số tự động của Numbering, không gõ tay. Nếu nhầm thứ tự, chuột phải vào số > Continue Numbering hoặc Set Numbering Value."},{"title":"Bước 6. Chèn bảng 1 dòng 2 cột, không viền ở cuối trang, nhập thông tin người hướng dẫn vào cột 2","forRequirement":"4","actions":["Đặt con trỏ cuối văn bản (Ctrl+End), bấm Enter hai lần, tắt Numbering (nếu đang bật, bấm lại nút Numbering).","Tab Insert > nhóm Tables > Table > Insert Table... nhập Number of columns = 2, Number of rows = 1 > OK.","Chỉnh độ rộng cột: kéo đường kẻ giữa sang phải để cột 1 rộng khoảng 9 cm và cột 2 khoảng 7 cm (tổng 16 cm). Hoặc Table Tools > Layout > nhóm Cell Size, đặt Width từng cột.","Click vào ô thứ 2 (cột 2), gõ ba dòng: Hà Nội, ngày      tháng      năm 20 ... (Enter) Người hướng dẫn (Enter) (Ký ghi rõ họ tên). Dùng vài phím cách hoặc tab để tạo khoảng trống giữa ngày, tháng, năm.","Bôi đen ba dòng này > Ctrl+E để căn giữa trong ô. Dòng 1 nghiêng (Ctrl+I), dòng 2 đậm (Ctrl+B), dòng 3 nghiêng (Ctrl+I).","Để cột 1 trống (đề yêu cầu chỉ điền thông tin vào cột thứ 2).","Bỏ đường viền: bấm chọn cả bảng (bấm biểu tượng dấu cộng ở góc trên trái bảng) > Table Tools > Design > nhóm Table Styles > Borders (mũi tên) > chọn No Border.","Nếu bật View Gridlines (Table Tools > Layout > View Gridlines) sẽ thấy đường lưới mờ nhưng đây không phải viền in; không ảnh hưởng.","Kiểm tra bảng nằm cuối trang và toàn bộ văn bản vẫn gọn trong 1 trang: nếu bảng bị đẩy sang trang 2, giảm khoảng cách trước/sau các đoạn (Spacing) hoặc xóa bớt dòng trống."],"note":"Bảng phải 1 dòng, 2 cột và không có viền nhìn thấy khi xem Print Preview (Ctrl+P)."},{"title":"Bước 7. Kiểm tra cuối và lưu","forRequirement":"1, 2, 3, 4, 5","actions":["Bấm Ctrl+A kiểm tra ô Font vẫn là Times New Roman và cỡ 13 (nếu ô trống thì có phần đang khác font, chọn lại).","Mở Page Layout > Margins > Custom Margins kiểm tra lại 2.5 / 2 / 3.5 / 1.5 và Paper A4, Portrait.","Bấm Ctrl+Shift+8 hiện ký hiệu ẩn để xem có phím Tab (mũi tên) ở các chỗ trống và có đoạn thừa không.","Ctrl+P xem toàn văn bản gọn 1 trang, so sánh với trang 3 của đề.","Lưu bằng Ctrl+S vào D:\\ThiCC\\sbd_cau1.docx (định dạng Word Document .docx)."],"note":""}],"formulas":[],"result":"Văn bản 1 trang A4 dọc, lề trên 2.5, dưới 2, trái 3.5, phải 1.5 cm, toàn bộ Times New Roman 13pt. Các chỗ trống là dòng chấm chạy sát lề phải, làm bằng Tab (bật Ctrl+Shift+8 thấy mũi tên). Ba mục (1), (2), (3) có số tự động, tiêu đề đậm, đoạn thân bên dưới không đánh số. Cuối trang có bảng 1 hàng 2 cột không viền, cột 2 chứa Hà Nội, ngày tháng năm 20 ... / Người hướng dẫn / (Ký ghi rõ họ tên). Tự kiểm tra bằng Print Preview."},"checklist":["Giấy A4, hướng Portrait","Lề Top 2.5 cm, Bottom 2 cm, Left 3.5 cm, Right 1.5 cm","Toàn văn bản Times New Roman, cỡ 13pt","Đủ toàn bộ nội dung như trang 3 của đề, không sót dòng","Các chỗ trống làm bằng Tab có leader dấu chấm, không gõ tay hàng loạt dấu chấm","Các mục Nhận xét và Kết luận đánh số (1), (2), (3) bằng Numbering tự động","Cuối trang có bảng 1 dòng 2 cột, không đường viền","Thông tin người hướng dẫn (ngày tháng, chức danh, ký tên) nằm ở cột thứ 2","Lưu đúng tên sbd_cau1.docx trong D:\\ThiCC"],"commonMistakes":["Gõ tay một dãy dấu chấm thay vì dùng Tab có Leader nên bị trừ điểm yêu cầu dùng tab.","Đặt tab không phải Right hoặc vị trí lớn hơn 16 cm làm dòng bị tràn xuống dòng dưới.","Quên đặt font Times New Roman 13 cho nội dung trong bảng.","Đánh số bằng cách gõ tay (1), (2), (3) thay vì dùng Numbering.","Để cả đoạn thân bị đánh số, làm thứ tự thành (1) (2) (3) (4) (5) (6).","Làm bảng nhiều dòng hoặc 3 cột; hoặc bỏ viền chưa hết nên vẫn còn viền khi in.","Để thông tin ở cột 1 thay vì cột 2, hoặc để bảng tràn sang trang 2.","Nhập lề sai đơn vị (inch thay cho cm), nhầm Lề dưới 2 cm với 2.5 cm.","Quên lưu hoặc lưu sai thư mục, sai tên file (phải là sbd_cau1.docx)."],"uncertain":["Ảnh trang 3 chụp rõ chữ nhưng không biết chính xác độ rộng các chỗ trống: các vị trí tab gợi ý (8, 9.5, 12, 16 cm) là suy ra từ ảnh, không phải yêu cầu của đề.","Đề yêu cầu cỡ chữ 13pt cho cả văn bản; phần đậm/nghiêng/căn giữa của các dòng tiêu đề được lấy theo hình thức trong ảnh, đề không nêu rõ.","Đề chỉ ghi 'Sử dụng danh sách (1,2,3)'; được hiểu là kiểu số tự tạo (1), (2), (3) như trong ảnh, các đoạn thân bên dưới không đánh số.","Dòng 'Hà Nội, ngày tháng năm 20 ...' trong ảnh để trống ngày, tháng; giữ nguyên như vậy (không điền số liệu cụ thể)."]},{"no":2,"app":"excel","title":"Câu 2. Tạo bảng tính (Microsoft Excel)","statement":{"intro":"Quá trình học tập môn Thực tập tốt nghiệp của sinh viên dân sự thể hiện như bảng sau. Sử dụng phần mềm Microsoft Excel tạo bảng theo dõi học tập với các yêu cầu sau:","requirements":["1) Nhập dữ liệu (giả định) cho 05 sinh viên trên các cột: TT (thứ tự), Mã SV (Mã sinh viên), Họ tên, Buổi 1, Buổi 2,..., Buổi 5; các cột Buổi 1, Buổi 2,..., Buổi 5 nhận một trong hai giá trị: 1 nếu đi học, 0 nếu nghỉ học. M1 (điểm Modul 1), M2 (điểm Modul 2), M3 (điểm Modul 3), M4 (điểm Modul 4); các cột M1, M2, M3, M4 dùng thang điểm 10 lấy lẻ đến 0.5. Kẻ khung, căn chỉnh, định dạng các kiểu dữ liệu cho phù hợp; Font: Times New Roman, cỡ 13pt.","2) Định dạng trang: Khổ giấy A4, Landscape; Top: 2.5 cm, Bottom: 2.5 cm; Left: 2.5 cm, Right: 1.5 cm. Căn chỉnh bảng tính ra giữa trang in (Horizontally).","3) Nhập công thức tính Điểm bài tập vào cột BT. Biết rằng BT = (M1+M2+2*M3+M4)/5; làm tròn với 1 chữ số sau dấu phẩy.","4) Nhập công thức tính Điểm cộng vào cột ĐC. Biết rằng sinh viên đi học đủ từ 4 buổi trở lên sẽ được cộng 0.5 điểm.","5) Nhập công thức tính Điểm thực tập vào cột TT; Biết rằng nếu sinh viên đi học từ 2 buổi trở lên và không có modul nào bị điểm nhỏ hơn 4 thì TT = BT + ĐC ngược lại TT = 0. Chú ý: Giá trị của TT không vượt quá 10."],"material":[{"kind":"table","caption":"Bảng mẫu trong đề (chỉ có dòng 1 là dữ liệu; các cột BT, ĐC, TT để trống, thí sinh tự nhập thêm 4 sinh viên giả định)","rows":[["TT","Mã SV","Họ tên","Buổi 1","Buổi 2","Buổi 3","Buổi 4","Buổi 5","Modul 1","Modul 2","Modul 3","Modul 4","BT","ĐC","TT"],["1","1619001","Nguyễn Văn A","1","0","1","0","1","8","7","6","9","","",""],["...","...","","","","","","","","","","","","",""]]}]},"solution":{"summary":"Nhập bảng 15 cột (A đến O) với 5 sinh viên giả định, định dạng Times New Roman 13, kẻ khung, thiết lập Page Setup (A4 Landscape, lề, Center Horizontally), rồi dùng ROUND cho BT, IF + COUNTIF cho ĐC, IF + AND + MIN cho TT và kéo công thức xuống các dòng.","steps":[{"title":"Bước 1. Tạo bảng và nhập dữ liệu giả định cho 5 sinh viên","forRequirement":"1","actions":["Mở Excel, tạo Blank workbook. Lưu ngay Ctrl+S thành D:\\ThiCC\\sbd_cau2.xlsx (Excel Workbook).","Dòng 1 (A1 đến O1) gõ tiêu đề lần lượt: A1 = TT, B1 = Mã SV, C1 = Họ tên, D1 = Buổi 1, E1 = Buổi 2, F1 = Buổi 3, G1 = Buổi 4, H1 = Buổi 5, I1 = Modul 1, J1 = Modul 2, K1 = Modul 3, L1 = Modul 4, M1 = BT, N1 = ĐC, O1 = TT. (Cột I đến L là M1 đến M4 trong lời văn của đề.)","Dòng 2 nhập sinh viên đầu tiên đúng như đề: 1, 1619001, Nguyễn Văn A, 1, 0, 1, 0, 1, 8, 7, 6, 9.","Dòng 3 đến 6 nhập 4 sinh viên giả định, cột Buổi chỉ nhập 1 hoặc 0, điểm Modul theo thang 10 và là bội số của 0.5. Gợi ý: dòng 3: 2, 1619002, Nguyễn Văn B, 1,1,1,1,0, 10,10,10,10. Dòng 4: 3, 1619003, Nguyễn Văn C, 0,0,0,1,1, 6.5,5.5,4.5,3.5. Dòng 5: 4, 1619004, Nguyễn Văn D, 1,1,1,1,1, 8,7,7.5,6. Dòng 6: 5, 1619005, Nguyễn Văn E, 0,1,0,1,0, 9,9.5,5,4.5.","Cột TT (A): gõ 1 và 2 rồi chọn hai ô, kéo ô vuông nhỏ (Fill Handle) xuống để ra 3, 4, 5, hoặc gõ tay 1 đến 5."],"note":"Tùy chọn: chọn D2:H6 > tab Data > Data Validation > Allow: List, Source: 1,0 (dùng dấu chấm phẩy nếu máy dùng dấu đó) để tránh nhập sai cột Buổi."},{"title":"Bước 2. Font, kẻ khung, căn chỉnh, định dạng kiểu dữ liệu","forRequirement":"1","actions":["Bấm Ctrl+A chọn toàn bảng tính, tab Home > nhóm Font > Font chọn Times New Roman, Font Size chọn 13.","Chọn vùng A1:O6 > tab Home > nhóm Font > nút Borders (hình ô vuông chia 4) > All Borders để kẻ khung toàn bảng.","Chọn dòng tiêu đề A1:O1 > Bold (Ctrl+B), Alignment: Center (căn giữa ngang) và Middle Align (giữa dọc) tại tab Home > nhóm Alignment, bật Wrap Text. Để giống đề, có thể quay chữ dọc cho các cột Buổi và Modul: chọn D1:L1 > Orientation (nút ab nghiêng) > Rotate Text Up.","Căn dữ liệu: cột A, B, D đến O căn giữa (Center), riêng cột C (Họ tên) căn trái (Left).","Định dạng số: chọn I2:L6 > Home > nhóm Number > mũi tên Number Format > More Number Formats... > Number, Decimal places = 1 (hiển thị 8.0, 9.5). Làm tương tự cho M2:O6 với Decimal places = 1.","Cột Buổi (D đến H) để dạng General hoặc Number, Decimal places = 0. Cột Mã SV để General (số nguyên 1619001).","Chỉnh độ rộng cột cho đủ hiển thị: chọn cột A đến O > nhấp đúp vào đường biên giữa hai tiêu đề cột để AutoFit; hoặc Home > Format > AutoFit Column Width."],"note":"Đề yêu cầu điểm Modul lấy lẻ đến 0.5, nghĩa là giá trị nhập chỉ có dạng x.0 hoặc x.5. Nếu cần ép đúng, dùng Data Validation > Allow: Decimal, between 0 and 10."},{"title":"Bước 3. Tính Điểm bài tập (cột BT, ô M2) và kéo xuống","forRequirement":"3","actions":["Click ô M2, gõ công thức: =ROUND((I2+J2+2*K2+L2)/5,1) rồi nhấn Enter.","Giải thích: I2, J2, K2, L2 là điểm Modul 1, 2, 3, 4 của sinh viên ở dòng 2; Modul 3 được nhân hệ số 2; chia cho 5 (tổng hệ số 1+1+2+1 = 5); hàm ROUND(...,1) làm tròn đến 1 chữ số sau dấu phẩy.","Click lại M2, đưa chuột vào ô vuông nhỏ góc dưới phải ô, khi con trỏ thành dấu + đen thì nhấp đúp (hoặc kéo xuống đến M6) để sao chép công thức cho 5 dòng."],"note":"Nếu máy báo lỗi công thức, kiểm tra dấu ngăn cách tham số: máy cài kiểu Việt Nam thường dùng dấu chấm phẩy (;) thay cho dấu phẩy (,), ví dụ =ROUND((I2+J2+2*K2+L2)/5;1). Dùng một kiểu thống nhất cho mọi công thức."},{"title":"Bước 4. Tính Điểm cộng (cột ĐC, ô N2)","forRequirement":"4","actions":["Click ô N2, gõ: =IF(COUNTIF(D2:H2,1)>=4,0.5,0) rồi Enter.","Giải thích: COUNTIF(D2:H2,1) đếm số ô trong 5 buổi có giá trị 1, tức số buổi đi học. Nếu số buổi từ 4 trở lên thì ĐC = 0.5, ngược lại ĐC = 0.","Cách khác cũng đúng: =IF(SUM(D2:H2)>=4,0.5,0) vì mỗi buổi chỉ là 1 hoặc 0.","Kéo công thức xuống N6 bằng ô vuông nhỏ (Fill Handle)."],"note":""},{"title":"Bước 5. Tính Điểm thực tập (cột TT, ô O2)","forRequirement":"5","actions":["Click ô O2, gõ: =IF(AND(COUNTIF(D2:H2,1)>=2,MIN(I2:L2)>=4),MIN(M2+N2,10),0) rồi Enter.","Giải thích: AND kiểm tra đồng thời hai điều kiện: số buổi đi học từ 2 trở lên (COUNTIF(D2:H2,1)>=2) và điểm Modul nhỏ nhất không nhỏ hơn 4 (MIN(I2:L2)>=4, tức không modul nào dưới 4). Nếu cả hai đúng thì TT = BT + ĐC nhưng không vượt quá 10 (MIN(M2+N2,10)); nếu một điều kiện sai thì TT = 0.","Cách viết khác (như file mẫu): =IF(OR(COUNTIF(D2:H2,1)<2,MIN(I2:L2)<4),0,IF(M2+N2<=10,M2+N2,10)).","Kéo công thức xuống O6."],"note":"Không dùng điều kiện >4 cho modul; đề nói 'không có modul nào bị điểm nhỏ hơn 4', nghĩa là điểm bằng 4 vẫn đạt (>=4)."},{"title":"Bước 6. Định dạng trang in: A4, Landscape, lề, căn giữa ngang","forRequirement":"2","actions":["Tab Page Layout > nhóm Page Setup > bấm mũi tên nhỏ ở góc dưới phải để mở hộp thoại Page Setup.","Thẻ Page: mục Orientation chọn Landscape; ô Paper size chọn A4. Giữ Scaling = Adjust to 100% (nếu bảng quá rộng, chọn Fit to: 1 page(s) wide và để trống ô tall).","Thẻ Margins: Top = 2.5, Bottom = 2.5, Left = 2.5, Right = 1.5 (đơn vị cm). Phần Center on page tích chọn Horizontally (không tích Vertically).","Bấm OK. Kiểm tra bằng File > Print (Ctrl+P): bảng nằm giữa theo chiều ngang, không bị cắt cột nào sang trang sau."],"note":"Nếu hộp thoại hiện đơn vị inch, nhập kèm đơn vị cm (ví dụ 2.5 cm). Nếu bảng tràn sang trang thứ hai theo chiều ngang, thu hẹp độ rộng cột hoặc dùng Fit to 1 page wide."},{"title":"Bước 7. Tự kiểm tra kết quả và lưu","forRequirement":"1, 2, 3, 4, 5","actions":["Với bộ dữ liệu gợi ý ở Bước 1, kết quả đúng (BT, ĐC, TT): dòng 2: 7.2, 0, 7.2. Dòng 3: 10, 0.5, 10. Dòng 4: 4.9, 0, 0 (do Modul 4 = 3.5 nhỏ hơn 4). Dòng 5: 7.2, 0.5, 7.7. Dòng 6: 6.6, 0, 6.6.","Bấm Ctrl+` (hoặc tab Formulas > Show Formulas) để xem lại các công thức, bấm lại để tắt.","Bấm Ctrl+S lưu D:\\ThiCC\\sbd_cau2.xlsx."],"note":""}],"formulas":[{"cell":"M2","formula":"=ROUND((I2+J2+2*K2+L2)/5,1)","meaning":"Điểm bài tập BT = (M1 + M2 + 2*M3 + M4)/5, làm tròn 1 chữ số thập phân. Kéo xuống M6."},{"cell":"N2","formula":"=IF(COUNTIF(D2:H2,1)>=4,0.5,0)","meaning":"Đếm số buổi đi học (giá trị 1) trong D2:H2; từ 4 buổi trở lên thì được cộng 0.5 điểm, ngược lại 0. Kéo xuống N6."},{"cell":"O2","formula":"=IF(AND(COUNTIF(D2:H2,1)>=2,MIN(I2:L2)>=4),MIN(M2+N2,10),0)","meaning":"Nếu đi học từ 2 buổi trở lên và điểm modul thấp nhất >= 4 thì TT = BT + ĐC nhưng tối đa 10, ngược lại TT = 0. Kéo xuống O6."}],"result":"Bảng 15 cột A đến O với 5 sinh viên, Times New Roman 13, có khung và căn chỉnh. Cột BT, ĐC, TT hiện số đúng theo công thức (với dữ liệu gợi ý: TT lần lượt 7.2, 10, 0, 7.7, 6.6). Khi in thử (Ctrl+P): trang A4 nằm ngang, bảng nằm chính giữa theo chiều ngang, lề 2.5/2.5/2.5/1.5 cm."},"checklist":["Có đủ 15 cột: TT, Mã SV, Họ tên, Buổi 1 đến Buổi 5, Modul 1 đến Modul 4, BT, ĐC, TT","Có 5 sinh viên, cột Buổi chỉ nhận 1 hoặc 0, điểm Modul theo thang 10 lẻ 0.5","Toàn bảng Times New Roman 13pt, có kẻ khung, căn chỉnh hợp lý","Page Setup: A4, Landscape, Top 2.5, Bottom 2.5, Left 2.5, Right 1.5 cm","Đã tích Center on page > Horizontally","BT dùng công thức =ROUND((I2+J2+2*K2+L2)/5,1), đúng hệ số 2 cho Modul 3, làm tròn 1 chữ số","ĐC = 0.5 khi đi học từ 4 buổi trở lên, ngược lại 0","TT đúng điều kiện (từ 2 buổi và không modul nào dưới 4) và không vượt quá 10","Công thức đã kéo xuống đủ 5 dòng, không có lỗi #VALUE! hay #NAME?","Lưu đúng tên sbd_cau2.xlsx trong D:\\ThiCC"],"commonMistakes":["Tính BT bằng AVERAGE của 4 điểm (không có hệ số 2 cho Modul 3). Đề yêu cầu BT = (M1+M2+2*M3+M4)/5; file mẫu Book1.xlsx dùng trung bình đơn giản nên khác đề.","Quên bọc ROUND nên BT có nhiều chữ số thập phân, hoặc chỉ định dạng hiển thị (Number Format) mà không làm tròn thật.","Dùng dấu phẩy thay dấu chấm phẩy (hoặc ngược lại) khi máy cài ngăn cách khác nên báo lỗi công thức.","Viết điều kiện số buổi là >4 thay vì >=4; hoặc điều kiện điểm modul là >4 thay vì >=4.","Quên giới hạn TT tối đa 10 (không dùng MIN(...,10) hay IF), hoặc quên trường hợp TT = 0.","Tham chiếu sai dòng khi kéo công thức hoặc khóa $ không cần thiết.","Chọn Portrait thay vì Landscape, hoặc quên tích Center on page > Horizontally.","Nhập lề sai thứ tự (nhầm Left 2.5 với Right 1.5).","Nhập điểm dạng chữ (có khoảng trắng hoặc dùng dấu phẩy sai) làm công thức báo lỗi hoặc tính sai.","Quên đặt font Times New Roman 13 cho toàn bảng hoặc quên lưu file đúng tên."],"uncertain":["Mã SV của dòng mẫu trong đề đọc là 1619001 (rõ trong ảnh); file mẫu Book1.xlsx dùng 19001 đến 19005. Lời giải dùng 1619001 đến 1619005.","File mẫu Book1.xlsx tính BT bằng =ROUND(AVERAGE(I2:L2),1) (trung bình, không có hệ số 2 cho Modul 3). Điều này khác đề, nên lời giải dùng công thức theo đề: BT = (M1+M2+2*M3+M4)/5, làm tròn 1 chữ số. Công thức ĐC và TT của file mẫu khớp với đề.","Đề cho phép tự giả định dữ liệu 5 sinh viên; chỉ dòng 1 (1619001: buổi 1,0,1,0,1; điểm 8,7,6,9) lấy từ đề. Dữ liệu 4 sinh viên còn lại lấy điểm Modul và các buổi từ file mẫu. Dòng 1 của file mẫu có số liệu khác dòng 1 của đề; đáp án kiểm tra ở Bước 7 dùng dòng 1 của đề (BT = 7.2).","Tên cột Modul 1 đến Modul 4 theo bảng trong đề, tương ứng M1 đến M4 trong phần yêu cầu. Cột cuối tên TT (Điểm thực tập) trùng tên cột TT đầu bảng (thứ tự): giữ nguyên hai cột cùng tên theo đề."]},{"no":3,"app":"powerpoint","title":"Câu 3. Tạo các trang trình chiếu (Microsoft PowerPoint)","statement":{"intro":"Sử dụng phần mềm Microsoft PowerPoint thiết kế slides trình chiếu phục vụ cho bài thuyết trình giới thiệu về Hà Nội (05 slides) trong đó có các nội dung sau:","requirements":["Lưu ý: Trên slides trình chiếu không chứa nội dung liên quan thông tin cá nhân của thí sinh.","1) Trình bày và căn chỉnh 5 slide theo yêu cầu nội dung như trên. Đánh số trang tự động cho các slide (trừ slide đầu tiên).","2) Trong Master Slide, điều chỉnh tất cả font chữ về Arial, nội dung căn chỉnh 2 bên.","3) Tạo mới và sử dụng ít nhất 02 layout cho bài trình chiếu.","4) Mỗi nội dung trong slide 3, 4, 5 sử dụng 01 hiệu ứng hoạt hình (Animation).","5) Mỗi slide sử dụng 01 hiệu ứng chuyển slide khác nhau (Transition)."],"material":[{"kind":"text","caption":"Nội dung các trang theo đề","lines":["Trang 1: Giới thiệu - Tên bài thuyết trình “Du lịch Hà Nội” (đặt ở giữa trang)","Trang 2: Nội dung trình bày: tên 3 địa điểm du lịch của Hà Nội được trình bày ở các trang tiếp theo","Trang 3, 4, 5: Mỗi trang trình bày về một địa điểm: nội dung trình bày tùy vào hiểu biết của từng thí sinh, tuy nhiên mỗi địa điểm du lịch phải đảm bảo 3 nội dung nổi bật và có hình ảnh đi kèm (nội dung gợi ý: tên địa điểm, vị trí địa lý, đặc điểm nổi bật, phương tiện đi lại, những chú ý khi đến đó....)"]}]},"solution":{"summary":"Tạo 5 slide (tiêu đề, mục lục 3 địa điểm, 3 slide địa điểm có hình), sửa Slide Master (font Arial, căn đều hai bên), tạo ít nhất hai layout mới rồi áp dụng cho slide 2 đến 5, đánh số trang tự động trừ slide 1, thêm một Animation cho nội dung ở slide 3, 4, 5 và đặt một Transition khác nhau cho từng slide.","steps":[{"title":"Bước 1. Tạo file và soạn nội dung 5 slide","forRequirement":"1","actions":["Mở PowerPoint > File > New > Blank Presentation. Lưu ngay: Ctrl+S > D:\\ThiCC\\sbd_cau3.pptx.","Slide 1 mặc định có layout Title Slide. Bấm vào ô tiêu đề gõ: Du lịch Hà Nội. Ô tiêu đề phụ (Subtitle) xóa đi hoặc để trống (không ghi họ tên thí sinh, vì đề yêu cầu không chứa thông tin cá nhân). Tiêu đề phải nằm giữa trang: chọn ô tiêu đề > Home > Center (Ctrl+E) và kéo ô về giữa slide (Home > Arrange > Align > Align Center và Align Middle).","Thêm slide mới: tab Home > New Slide (Ctrl+M) cho đủ 5 slide. Slide 2: tiêu đề 'Nội dung trình bày', liệt kê 3 địa điểm, ví dụ: Hồ Hoàn Kiếm; Văn Miếu - Quốc Tử Giám; Hồ Tây. Slide 3, 4, 5: mỗi slide một địa điểm, tiêu đề là tên địa điểm và ít nhất 3 nội dung nổi bật.","Gợi ý nội dung slide 3 (Hồ Hoàn Kiếm): Vị trí: trung tâm quận Hoàn Kiếm, Hà Nội; Đặc điểm nổi bật: Tháp Rùa, đền Ngọc Sơn, cầu Thê Húc; Phương tiện và lưu ý: đi bộ, xe buýt, taxi, nên đi buổi sáng sớm hoặc cuối tuần khi phố đi bộ mở.","Gợi ý slide 4 (Văn Miếu - Quốc Tử Giám): Vị trí: phố Quốc Tử Giám, quận Đống Đa; Đặc điểm: trường đại học đầu tiên của Việt Nam, Khuê Văn Các, bia tiến sĩ; Lưu ý: ăn mặc lịch sự, giữ trật tự, đi xe buýt hoặc taxi.","Gợi ý slide 5 (Hồ Tây): Vị trí: quận Tây Hồ; Đặc điểm: hồ nước ngọt lớn nhất Hà Nội, chùa Trấn Quốc, đường ven hồ; Lưu ý: nên đi xe đạp hoặc taxi, ngắm hoàng hôn.","Chèn hình ảnh cho slide 3, 4, 5: Insert > Pictures > chọn file ảnh (nếu phòng thi có sẵn ảnh) hoặc Insert > Online Pictures (Clip Art ở Office 2010) > tìm tên địa điểm > Insert. Mỗi slide ít nhất 1 hình."],"note":"Nội dung do thí sinh tự soạn theo hiểu biết, miễn mỗi địa điểm có ít nhất 3 nội dung nổi bật (tên, vị trí, đặc điểm, phương tiện, lưu ý) và có hình kèm. Không ghi tên thí sinh, số báo danh, trường lớp lên slide."},{"title":"Bước 2. Sửa Slide Master: font Arial và căn đều hai bên","forRequirement":"2","actions":["Tab View > nhóm Master Views > Slide Master. Ở khung bên trái, bấm chọn slide lớn trên cùng (Slide Master, thumbnail to nhất) chứ không phải các layout nhỏ bên dưới.","Đổi font cho toàn bộ: tab Slide Master > nhóm Edit Theme > Fonts > Customize Fonts... > đặt Heading font và Body font đều là Arial > ô Name gõ Arial > Save. Cách này đổi font cho cả Title và Body trong mọi layout.","Kiểm tra bằng cách bấm từng ô (Title, Body, Date, Footer, Slide Number) trong Master xem tab Home hiển thị font Arial. Nếu chưa, chọn ô > Home > Font > Arial.","Căn đều hai bên: trong Slide Master, click vào ô nội dung lớn (Click to edit Master text styles), bấm Ctrl+A bôi đen hết các cấp chữ bên trong > tab Home > nhóm Paragraph > Justify (hoặc Ctrl+J).","Bấm vài layout bên dưới (Title and Content...) xem ô nội dung đã Justify chưa; nếu chưa, chọn ô và bấm Ctrl+J.","Phần Title không ép Justify: tiêu đề slide 1 phải nằm giữa trang (đề yêu cầu) nên giữ căn giữa cho Title của layout Title Slide.","Bấm Slide Master > Close Master View (hoặc View > Normal) để quay lại."],"note":"Phải làm trong Slide Master, không sửa từng slide. Sau khi gõ nội dung xong, chọn thử một ô văn bản bất kỳ ở slide để xác nhận font là Arial."},{"title":"Bước 3. Tạo ít nhất 2 layout mới và áp dụng","forRequirement":"3","actions":["Vào lại View > Slide Master. Ở khung trái chọn một layout > tab Slide Master > nhóm Edit Master > Insert Layout. Một layout mới xuất hiện với ô Title.","Layout 1, ví dụ tên 'Muc luc': tab Slide Master > nhóm Master Layout > Insert Placeholder > Text (hoặc Content) > kéo vẽ ô bên dưới tiêu đề. Đổi tên: chuột phải thumbnail layout > Rename Layout > gõ Muc luc > Rename.","Insert Layout lần nữa để làm Layout 2, ví dụ tên 'Dia diem': Insert Placeholder > Text vẽ ô văn bản bên trái (khoảng nửa trang), rồi Insert Placeholder > Picture vẽ ô hình bên phải. Đảm bảo văn bản trong ô Text căn đều hai bên (Ctrl+J), font Arial. Đổi tên layout thành Dia diem.","Bấm Close Master View.","Áp dụng layout: chọn slide 2 > tab Home > nhóm Slides > Layout > chọn layout 'Muc luc' vừa tạo (nằm ở nhóm Custom Design). Chọn slide 3 > Layout > Dia diem. Làm tương tự cho slide 4 và 5. Slide 1 giữ layout Title Slide.","Nếu đã gõ chữ trước khi đổi layout, nội dung tự chuyển vào ô mới; kiểm tra chữ không bị mất hoặc nằm ngoài ô, xóa ô trống thừa nếu có."],"note":"Như vậy có ít nhất 2 layout tạo mới và đã được sử dụng (Muc luc cho slide 2, Dia diem cho slide 3 đến 5)."},{"title":"Bước 4. Đánh số trang tự động, trừ slide đầu tiên","forRequirement":"1","actions":["Chọn tab Insert > nhóm Text > Header & Footer (hoặc Slide Number).","Trong hộp thoại Header and Footer, thẻ Slide: tích chọn Slide number. Tích thêm Don't show on title slide. Bấm Apply to All.","Kiểm tra: slide 1 không có số, slide 2 hiện 2, slide 3 hiện 3, v.v. Nếu số không hiện trên layout tự tạo, vào Slide Master > chọn layout đó > tab Slide Master > tích Footers, hoặc Insert Placeholder > Slide Number để thêm ô số trang vào layout.","Nếu Slide 1 vẫn hiện số: chọn slide 1 > Insert > Header & Footer > bỏ chọn Slide number > Apply (không bấm Apply to All)."],"note":"Số trang phải là số tự động (Slide Number), không gõ tay số vào từng slide."},{"title":"Bước 5. Thêm hiệu ứng Animation cho nội dung ở slide 3, 4, 5","forRequirement":"4","actions":["Chọn slide 3. Click vào khung văn bản nội dung (chọn viền khung, không chỉ con trỏ trong khung).","Tab Animations > nhóm Animation > chọn một hiệu ứng, ví dụ Fade, Fly In hoặc Wipe (hoặc Add Animation > Entrance).","Nếu muốn các ý chạy lần lượt: Effect Options > By Paragraph. Mỗi nội dung vẫn chỉ dùng 1 loại hiệu ứng.","Click vào hình trên slide, chọn một hiệu ứng (ví dụ Zoom hoặc Fade) để hình cũng có hiệu ứng.","Làm tương tự cho slide 4 và 5 (có thể dùng Animation Painter: chọn đối tượng đã có hiệu ứng > tab Animations > Animation Painter > bấm vào đối tượng ở slide khác).","Kiểm tra bằng tab Animations > Animation Pane (mỗi nội dung có đúng 1 dòng hiệu ứng) hoặc bấm Preview. Các số 1, 2, 3 nhỏ cạnh đối tượng cho thấy thứ tự."],"note":"Đề chỉ yêu cầu animation cho slide 3, 4, 5. Mỗi nội dung dùng 1 hiệu ứng, tránh chồng nhiều hiệu ứng lên cùng một đối tượng."},{"title":"Bước 6. Hiệu ứng chuyển slide (Transition) khác nhau cho mỗi slide","forRequirement":"5","actions":["Chọn slide 1 trong khung thumbnail bên trái > tab Transitions > nhóm Transition to This Slide > chọn Fade.","Chọn slide 2 > Transitions > chọn Push. Slide 3 > Wipe. Slide 4 > Split. Slide 5 > Cover (hoặc Zoom, Shape...).","KHÔNG bấm Apply To All (nút này áp cùng một hiệu ứng cho mọi slide, sai yêu cầu 'khác nhau').","Kiểm tra: các slide trong khung trái có ngôi sao nhỏ ở dưới; bấm Preview ở tab Transitions để xem thử."],"note":"Năm slide phải có năm hiệu ứng chuyển slide khác nhau, mỗi slide đúng 1 hiệu ứng."},{"title":"Bước 7. Kiểm tra cuối và lưu","forRequirement":"1, 2, 3, 4, 5","actions":["Bấm F5 (Slide Show từ đầu) chạy thử toàn bộ 5 slide: tiêu đề slide 1 ở giữa, slide 2 có đủ 3 địa điểm, slide 3 đến 5 có hình và hiệu ứng.","Kiểm tra không có tên thí sinh, số báo danh hay thông tin cá nhân trên slide (kể cả footer và ghi chú).","Kiểm tra căn chỉnh: chữ nằm trong khung, hình không đè chữ, không còn ô trống 'Click to add text' (xóa ô thừa).","Lưu Ctrl+S vào D:\\ThiCC\\sbd_cau3.pptx."],"note":""}],"formulas":[],"result":"File 5 slide: slide 1 chỉ có tiêu đề 'Du lịch Hà Nội' ở giữa trang, không số trang; slide 2 liệt kê 3 địa điểm; slide 3, 4, 5 mỗi slide một địa điểm với ít nhất 3 nội dung nổi bật và có hình. Slide 2 đến 5 có số trang tự động. Toàn bộ font là Arial, nội dung căn đều hai bên, có ít nhất 2 layout tự tạo đã được dùng. Slide 3, 4, 5 có animation cho nội dung; 5 slide có 5 hiệu ứng chuyển slide khác nhau. Chạy thử bằng F5 để kiểm tra."},"checklist":["Đủ 5 slide đúng cấu trúc: tiêu đề, mục lục 3 địa điểm, 3 slide địa điểm","Slide 1 có tên bài 'Du lịch Hà Nội' đặt giữa trang","Slide 2 liệt kê tên 3 địa điểm sẽ trình bày ở các trang sau","Mỗi slide 3, 4, 5 có ít nhất 3 nội dung nổi bật và có hình ảnh","Không có thông tin cá nhân của thí sinh trên slide","Có số trang tự động trên các slide trừ slide đầu tiên","Slide Master: font Arial cho toàn bộ, nội dung căn đều hai bên","Đã tạo mới và sử dụng ít nhất 2 layout","Mỗi nội dung ở slide 3, 4, 5 có 1 hiệu ứng Animation","Mỗi slide có 1 hiệu ứng Transition và 5 hiệu ứng đều khác nhau","Lưu đúng tên sbd_cau3.pptx trong D:\\ThiCC"],"commonMistakes":["Sửa font từng slide mà không sửa trong Slide Master nên phần Master chưa là Arial.","Sửa Master nhưng chỉ chọn một layout nhỏ chứ không chọn Slide Master lớn nhất, nên các layout khác vẫn font cũ.","Quên căn Justify cho nội dung ở Master (hoặc chỉ căn ở từng slide).","Gõ tay số trang thay vì dùng Insert > Slide Number; quên bỏ số trên slide đầu tiên.","Tạo layout mới nhưng không áp dụng cho slide nào (đề yêu cầu cả tạo mới và sử dụng).","Bấm Apply To All khi đặt Transition khiến mọi slide giống nhau.","Gán nhiều animation chồng lên một nội dung hoặc quên gán cho một slide trong 3, 4, 5.","Ghi tên thí sinh, số báo danh vào slide hoặc footer.","Slide địa điểm thiếu hình ảnh hoặc ít hơn 3 nội dung nổi bật.","Quên lưu file hoặc lưu sai tên/thư mục (phải là sbd_cau3.pptx trong D:\\ThiCC)."],"uncertain":["Đề không cung cấp sẵn nội dung chi tiết hay ảnh; ba địa điểm (Hồ Hoàn Kiếm, Văn Miếu - Quốc Tử Giám, Hồ Tây) và nội dung từng slide là gợi ý của lời giải, không phải dữ liệu của đề. Thí sinh có thể chọn địa điểm khác.","Cụm 'Mỗi nội dung trong slide 3, 4, 5 sử dụng 01 hiệu ứng hoạt hình' có thể hiểu là mỗi khối nội dung (văn bản, hình) có 1 hiệu ứng; lời giải gán 1 hiệu ứng cho khối văn bản và 1 cho hình ở mỗi slide.","Đề không nói nguồn ảnh (có thể phòng thi cho sẵn thư mục ảnh hoặc cho tìm ảnh trực tuyến); lời giải trình bày cả hai cách.","Yêu cầu 'nội dung căn chỉnh 2 bên' được hiểu là căn đều hai bên (Justify); tiêu đề slide 1 vẫn căn giữa theo yêu cầu 'đặt ở giữa trang'."]}]}];
